-- LangConfig additive tool seed — generated by export_tools_merge.py
-- 83 tool(s) from the live database.
--
-- Union semantics on tool_id: a row the target already has is left
-- untouched, a missing one is added with an id from the sequence. Run it
-- on a fresh database or on one already full of a teammate's tools.
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f custom_tools_merge.sql

BEGIN;

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 102, 'advanced_sql_agent_tool', 'SQL Agent (Advanced)', '用我：复杂业务问题、需要多步 SQL 推理时（Chinook）。
别用我：一条简单查询用 sql_agent_tool 或 pg_query。

Ask a natural-language question and get an answer from a PostgreSQL
database (read-only), with automatic planning for complex questions.

Runs the planner-based LangGraph SQL agent: it analyzes the question
against the schema first — simple questions are answered with one query,
while multi-hop / analytical questions are decomposed into a step-by-step
plan, each step executed and monitored, then synthesized into the final
answer. Handles joins, aggregations, multi-step and comparison questions.

Args:
    question: The natural-language SQL question to answer.
    database: Optional PostgreSQL database name to query. Empty uses the
        default (env SQL_POSTGRES_DB, else POSTGRES_DB, else chinook).

Returns:
    The final answer text (not raw query results).

Example:
    >>> advanced_sql_agent_tool(
    ...     "List the top 3 artists by revenue, then for the top artist "
    ...     "name their 3 longest tracks.", database="chinook")', 'python_function', 'custom', '{"function_name": "advanced_sql_agent_tool", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef advanced_sql_agent_tool(question: str, database: str = \"\") -> str:\n    \"\"\"\n    用我：复杂业务问题、需要多步 SQL 推理时（Chinook）。\n    别用我：一条简单查询用 sql_agent_tool 或 pg_query。\n\n    Ask a natural-language question and get an answer from a PostgreSQL\n    database (read-only), with automatic planning for complex questions.\n\n    Runs the planner-based LangGraph SQL agent: it analyzes the question\n    against the schema first — simple questions are answered with one query,\n    while multi-hop / analytical questions are decomposed into a step-by-step\n    plan, each step executed and monitored, then synthesized into the final\n    answer. Handles joins, aggregations, multi-step and comparison questions.\n\n    Args:\n        question: The natural-language SQL question to answer.\n        database: Optional PostgreSQL database name to query. Empty uses the\n            default (env SQL_POSTGRES_DB, else POSTGRES_DB, else chinook).\n\n    Returns:\n        The final answer text (not raw query results).\n\n    Example:\n        >>> advanced_sql_agent_tool(\n        ...     \"List the top 3 artists by revenue, then for the top artist \"\n        ...     \"name their 3 longest tracks.\", database=\"chinook\")\n    \"\"\"\n    from langgraph.tool_adapters import run_sql_agent_advanced\n    return run_sql_agent_advanced(question, database=database or None)", "args_schema": {"question": {"type": "string", "description": ""}, "database": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"question": {"type": "string", "description": ""}, "database": {"type": "string", "description": "", "default": ""}}, "required": ["question"]}', 'string', NULL, '{"category": "database", "order": 63, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-23 13:41:32.056176+00:00', '2026-11-01 03:15:31.477527+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'advanced_sql_agent_tool')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 102);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 92, 'bash', 'Bash Shell', 'Execute a bash shell command inside the workspace sandbox.

Use for running commands, scripts, git operations, package installs,
listing processes, or any terminal work the user asks for. The command
runs with the workspace outputs directory as its working directory (or
the given cwd, which must be inside the sandbox). Output is capped.

Args:
    command: The shell command to run (bash syntax; pipes/redirects allowed)
    timeout: Timeout in seconds (default 30, max 120)
    cwd: Working directory for the command (must be inside the sandbox)', 'python_function', 'custom', '{"function_name": "bash", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef bash(command: str, timeout: int = 30, cwd: str = None) -> str:\n    \"\"\"Execute a bash shell command inside the workspace sandbox.\n\n    Use for running commands, scripts, git operations, package installs,\n    listing processes, or any terminal work the user asks for. The command\n    runs with the workspace outputs directory as its working directory (or\n    the given cwd, which must be inside the sandbox). Output is capped.\n\n    Args:\n        command: The shell command to run (bash syntax; pipes/redirects allowed)\n        timeout: Timeout in seconds (default 30, max 120)\n        cwd: Working directory for the command (must be inside the sandbox)\n    \"\"\"\n    import subprocess\n\n    timeout = max(1, min(int(timeout or 30), 120))\n    if cwd:\n        resolved_cwd, error = _resolve_sandbox_path(cwd)\n        if error:\n            return error\n        run_cwd = str(resolved_cwd)\n    else:\n        roots = _sandbox_roots()\n        run_cwd = str(roots[0]) if roots else \".\"\n\n    # A path check bounds the tools that take a path; a shell takes a program, so the\n    # only place to bound `cat /anywhere` is the OS. wrap() returns None when no\n    # mechanism is available (probed once, reported at boot) and the plain command runs.\n    from tools.shell_sandbox import wrap as _wrap_shell\n    from services import user_roots as _user_roots\n    try:\n        _run_command = _wrap_shell(\n            command, Path(run_cwd), _user_roots.install_root()\n        ) or command\n    except Exception:\n        _run_command = command\n\n    try:\n        proc = subprocess.run(\n            _run_command, shell=True, cwd=run_cwd,\n            capture_output=True, text=True, timeout=timeout,\n        )\n    except subprocess.TimeoutExpired:\n        return f\"⚠️ Command timed out after {timeout}s: {command[:200]}\"\n    out = (proc.stdout or \"\") + (proc.stderr or \"\")\n    if not out.strip():\n        return f\"(no output; exit code {proc.returncode})\"\n    max_chars = 100_000\n    if len(out) > max_chars:\n        out = out[:max_chars] + f\"\\n… output truncated at {max_chars} chars\"\n    return f\"$ {command}\\n{out.strip()}\\n(exit {proc.returncode})\"", "args_schema": {"command": {"type": "string", "description": ""}, "timeout": {"type": "integer", "description": "", "default": 30}, "cwd": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"command": {"type": "string", "description": ""}, "timeout": {"type": "integer", "description": "", "default": 30}, "cwd": {"type": "string", "description": "", "default": null}}, "required": ["command"]}', 'string', NULL, '{"category": "shell", "order": 13, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'shell', TRUE, NULL, '["builtin", "shell"]', '2026-08-15 08:03:45.867636+00:00', '2026-11-11 02:00:59.928167+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'bash')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 92);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 214, 'create_agent', 'Create Agent (deep or normal)', 'Create an agent in the database (deep or normal). Requires human approval.

Args:
    name: Agent name, e.g. ''case-13-weather''
    system_prompt: Complete system prompt (what it does, how it answers, where it saves)
    native_tools: Tool ids from pg_list_custom_tools — never guess names
    kind: ''deep'' (harness gives ls/read_file/write_file/glob/grep, subagents, skills)
          or ''normal'' (platform assembles the prompt; file tools must be listed here)
    skills: Skill ids from search_skills / pg_list_skills
    description: One or two sentences for the agent list
    category: ''Custom'', ''Research'', ''Coding'', ...
    model: Model name; omit for the platform default
    temperature: 0.0–1.0 (default 0.3 — precise enough for build work)
    subagents: [{"name","description","system_prompt","tools","middleware","interrupt_on"}]
    middleware: [{"type":"todo_list","enabled":true,"config":{...}}, ...]
    mcp_servers: {"calendar": {"url": "http://127.0.0.1:3000"}} — see docs/design/agent-builder.md
    tool_params: Per-tool defaults, e.g. {"neo4j_agent_tool": {"database": "neo4j"}}
    agent_docs: {"AGENTS.md": "...", "CLAUDE.md": "..."}

Returns the new agent id plus which fields took effect. Build first in your head,
then write a rubric, then call this — see the agent-builder skill.', 'python_function', 'custom', '{"function_name": "create_agent", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nAGENT_BUILDER_APPROVED = \"[rejected] this write needs an approval decision — the tool did not run\"\n\ndef _in_agent_run() -> bool:\n    \"\"\"True when this tool call is executing inside a LangGraph run.\n\n    `interrupt()` raises outside a checkpointed graph, and these tools are also\n    callable from the UI and from scripts — those paths must not try to pause.\n    \"\"\"\n    try:\n        from langchain_core.runnables.config import ensure_config\n\n        cfg = ensure_config() or {}\n        return bool((cfg.get(\"configurable\") or {}).get(\"thread_id\"))\n    except Exception:\n        return False\n\ndef _approval_gate(tool_name: str, payload: dict, description: str) -> str | None:\n    \"\"\"Pause for a human decision. Returns None to proceed, or a refusal string.\"\"\"\n    if not _in_agent_run():\n        return None\n\n    from langgraph.types import interrupt\n\n    decision = interrupt(\n        {\n            \"action_requests\": [\n                {\"name\": tool_name, \"args\": payload, \"description\": description}\n            ],\n            \"review_configs\": [\n                {\"action_name\": tool_name, \"allowed_decisions\": [\"approve\", \"reject\"]}\n            ],\n        }\n    )\n\n    if isinstance(decision, dict) and \"decisions\" in decision:\n        flat = decision.get(\"decisions\") or []\n        decision = flat[0] if flat else {}\n    if isinstance(decision, list):\n        decision = decision[0] if decision else {}\n    kind = decision.get(\"type\") if isinstance(decision, dict) else decision\n\n    if kind == \"approve\":\n        return None\n    if kind == \"reject\":\n        return f\"[rejected by human] {decision.get(''message'') or ''no reason given''}\"\n    return AGENT_BUILDER_APPROVED\n\ndef _agent_config_payload(kind: str, cfg: dict) -> dict:\n    \"\"\"The DeepAgentConfig for a new agent, normal or deep.\n\n    `kind=\"normal\"` flips `use_deepagents` off: the platform then assembles the\n    prompt (guardrails + tool enforcement) instead of taking ours verbatim, and\n    the harness file tools no longer arrive for free — a normal agent that needs\n    to write files must list `write_file` itself.\n    \"\"\"\n    from models.deep_agent import (\n        DeepAgentConfig,\n        MiddlewareConfig,\n        SubAgentConfig,\n        create_default_backend_config,\n        create_default_guardrails_config,\n        create_default_middleware_config,\n    )\n\n    subagents = []\n    for sub in cfg.get(\"subagents\") or []:\n        if not isinstance(sub, dict) or not sub.get(\"name\"):\n            continue\n        subagents.append(\n            SubAgentConfig(\n                name=sub[\"name\"],\n                description=sub.get(\"description\") or \"\",\n                system_prompt=sub.get(\"system_prompt\") or \"\",\n                tools=list(sub.get(\"tools\") or []),\n                middleware=list(sub.get(\"middleware\") or []),\n                interrupt_on=sub.get(\"interrupt_on\") or {},\n            )\n        )\n\n    middleware = []\n    for mw in cfg.get(\"middleware\") or []:\n        if isinstance(mw, dict) and mw.get(\"type\"):\n            middleware.append(\n                MiddlewareConfig(\n                    type=mw[\"type\"],\n                    enabled=mw.get(\"enabled\", True),\n                    config=mw.get(\"config\") or {},\n                )\n            )\n    # None = \"I did not say\" → platform defaults. [] = \"I said none\" → none.\n    # Collapsing the two made a template that says \"no middleware\" silently get\n    # todo_list + filesystem + subagent (found by Agent Builder, 2026-11-01).\n    if cfg.get(\"middleware\") is None:\n        middleware = create_default_middleware_config()\n\n    return DeepAgentConfig(\n        model=cfg.get(\"model\") or None,\n        temperature=cfg.get(\"temperature\") if cfg.get(\"temperature\") is not None else 0.3,\n        system_prompt=(cfg.get(\"system_prompt\") or \"\").strip(),\n        native_tools=list(cfg.get(\"native_tools\") or []),\n        cli_tools=[],\n        custom_tools=[],\n        skills=cfg.get(\"skills\"),\n        tools=[],\n        use_deepagents=(kind != \"normal\"),\n        middleware=middleware,\n        subagents=subagents,\n        mcp_servers=cfg.get(\"mcp_servers\") or None,\n        tool_params=cfg.get(\"tool_params\") or None,\n        backend=create_default_backend_config(),\n        guardrails=create_default_guardrails_config(),\n    )\n\ndef _apply_config(agent, cfg_obj) -> list[str]:\n    \"\"\"Write a DeepAgentConfig onto the template row; returns the fields saved.\"\"\"\n    from sqlalchemy.orm.attributes import flag_modified\n\n    dumped = cfg_obj.dict()\n    agent.config = dumped\n    agent.middleware_config = [m.dict() for m in cfg_obj.middleware]\n    agent.subagents_config = [s.dict() for s in cfg_obj.subagents]\n    agent.backend_config = cfg_obj.backend.dict()\n    agent.guardrails_config = cfg_obj.guardrails.dict()\n    flag_modified(agent, \"config\")\n    saved = [\"model\", \"temperature\", \"system_prompt\", \"native_tools\", \"middleware\"]\n    if cfg_obj.subagents:\n        saved.append(\"subagents\")\n    if cfg_obj.mcp_servers:\n        saved.append(\"mcp_servers\")\n    if cfg_obj.tool_params:\n        saved.append(\"tool_params\")\n    if cfg_obj.skills:\n        saved.append(\"skills\")\n    return saved\n\ndef _as_list(value, sep: str = \",\") -> list:\n    \"\"\"Accept a real list, a JSON array string, or CSV — models send all three.\n\n    The tool schema says \"array\" now, but a model that has seen older catalog\n    text still emits \"web_search,tavily_search\". Coercing here keeps the build\n    correct instead of silently creating an agent whose tools are the\n    characters of that string (which happened once).\n    \"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [str(v).strip() for v in value if str(v).strip()]\n    if isinstance(value, str):\n        text = value.strip()\n        if not text:\n            return []\n        if text.startswith(\"[\"):\n            try:\n                import json as _json\n\n                parsed = _json.loads(text)\n                if isinstance(parsed, list):\n                    return [str(v).strip() for v in parsed if str(v).strip()]\n            except Exception:\n                pass\n        return [part.strip() for part in text.split(sep) if part.strip()]\n    return [str(value)]\n\ndef _as_dict(value):\n    \"\"\"Accept a dict or a JSON object string.\"\"\"\n    if value is None:\n        return None\n    if isinstance(value, dict):\n        return value\n    if isinstance(value, str) and value.strip().startswith(\"{\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return parsed if isinstance(parsed, dict) else None\n        except Exception:\n            return None\n    return None\n\ndef _as_list_of_dicts(value) -> list:\n    \"\"\"Accept a list, or a JSON array string (subagents/middleware).\"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [v for v in value if isinstance(v, dict)]\n    if isinstance(value, str) and value.strip().startswith(\"[\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return [v for v in parsed if isinstance(v, dict)] if isinstance(parsed, list) else []\n        except Exception:\n            return []\n    return []\n\ndef create_agent(name: str,\n                 system_prompt: str,\n                 native_tools: list[str],\n                 kind: str = \"deep\",\n                 skills: list[str] | None = None,\n                 description: str | None = None,\n                 category: str | None = None,\n                 model: str | None = None,\n                 temperature: float = 0.3,\n                 subagents: list[dict] | None = None,\n                 middleware: list[dict] | None = None,\n                 mcp_servers: dict | None = None,\n                 tool_params: dict | None = None,\n                 agent_docs: dict | None = None) -> str:\n    \"\"\"Create an agent in the database (deep or normal). Requires human approval.\n\n    Args:\n        name: Agent name, e.g. ''case-13-weather''\n        system_prompt: Complete system prompt (what it does, how it answers, where it saves)\n        native_tools: Tool ids from pg_list_custom_tools — never guess names\n        kind: ''deep'' (harness gives ls/read_file/write_file/glob/grep, subagents, skills)\n              or ''normal'' (platform assembles the prompt; file tools must be listed here)\n        skills: Skill ids from search_skills / pg_list_skills\n        description: One or two sentences for the agent list\n        category: ''Custom'', ''Research'', ''Coding'', ...\n        model: Model name; omit for the platform default\n        temperature: 0.0–1.0 (default 0.3 — precise enough for build work)\n        subagents: [{\"name\",\"description\",\"system_prompt\",\"tools\",\"middleware\",\"interrupt_on\"}]\n        middleware: [{\"type\":\"todo_list\",\"enabled\":true,\"config\":{...}}, ...]\n        mcp_servers: {\"calendar\": {\"url\": \"http://127.0.0.1:3000\"}} — see docs/design/agent-builder.md\n        tool_params: Per-tool defaults, e.g. {\"neo4j_agent_tool\": {\"database\": \"neo4j\"}}\n        agent_docs: {\"AGENTS.md\": \"...\", \"CLAUDE.md\": \"...\"}\n\n    Returns the new agent id plus which fields took effect. Build first in your head,\n    then write a rubric, then call this — see the agent-builder skill.\n    \"\"\"\n    from db.database import SessionLocal\n    from models.deep_agent import DeepAgentTemplate\n\n    if kind not in (\"deep\", \"normal\"):\n        return f\"❌ kind must be ''deep'' or ''normal'', got {kind!r}\"\n\n    native_tools = _as_list(native_tools)\n    skills = _as_list(skills)\n    subagents = _as_list_of_dicts(subagents)\n    middleware = _as_list_of_dicts(middleware)\n    mcp_servers = _as_dict(mcp_servers)\n    tool_params = _as_dict(tool_params)\n    agent_docs = _as_dict(agent_docs)\n\n    if not native_tools:\n        return \"❌ native_tools is empty — read pg_list_custom_tools and pass the real ids\"\n\n    refusal = _approval_gate(\n        \"create_agent\",\n        {\"name\": name, \"kind\": kind, \"native_tools\": native_tools,\n         \"skills\": skills or [], \"subagents\": [s.get(\"name\") for s in (subagents or [])]},\n        f\"Create agent {name!r} ({kind}) with {len(native_tools)} tools\",\n    )\n    if refusal:\n        return refusal\n\n    db = SessionLocal()\n    try:\n        cfg_obj = _agent_config_payload(kind, {\n            \"system_prompt\": system_prompt,\n            \"native_tools\": native_tools,\n            \"skills\": skills,\n            \"model\": model,\n            \"temperature\": temperature,\n            \"subagents\": subagents,\n            \"middleware\": middleware,\n            \"mcp_servers\": mcp_servers,\n            \"tool_params\": tool_params,\n        })\n        agent = DeepAgentTemplate(\n            name=name.strip(),\n            description=(description or \"\").strip(),\n            category=category or \"Custom\",\n            config=cfg_obj.dict(),\n            middleware_config=[],\n            subagents_config=[],\n            backend_config=cfg_obj.backend.dict(),\n            guardrails_config=cfg_obj.guardrails.dict(),\n            agent_docs=agent_docs,\n            is_public=False,\n        )\n        saved = _apply_config(agent, cfg_obj)\n        db.add(agent)\n        db.commit()\n        db.refresh(agent)\n\n        return (\n            f\"✅ agent ''{name}'' created — id={agent.id}, kind={kind}\\n\"\n            f\"保存字段: {'', ''.join(saved)}\\n\"\n            f\"工具 {len(cfg_obj.native_tools)} / 技能 {len(cfg_obj.skills or [])} / \"\n            f\"子代理 {len(cfg_obj.subagents)} / MCP {len(cfg_obj.mcp_servers or {})}\\n\"\n            f\"下一步: test_agent(agent_id={agent.id}, probe=...) 用针对 rubric 的探针跑一轮。\"\n        )\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to create agent: {e}\"\n    finally:\n        db.close()", "args_schema": {"name": {"type": "string", "description": ""}, "system_prompt": {"type": "string", "description": ""}, "native_tools": {"type": "array", "description": ""}, "kind": {"type": "string", "description": "", "default": "deep"}, "skills": {"type": "array", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "category": {"type": "string", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": 0.3}, "subagents": {"type": "array", "description": "", "default": null}, "middleware": {"type": "array", "description": "", "default": null}, "mcp_servers": {"type": "object", "description": "", "default": null}, "tool_params": {"type": "object", "description": "", "default": null}, "agent_docs": {"type": "object", "description": "", "default": null}}}', '{"type": "object", "properties": {"name": {"type": "string", "description": ""}, "system_prompt": {"type": "string", "description": ""}, "native_tools": {"type": "array", "description": ""}, "kind": {"type": "string", "description": "", "default": "deep"}, "skills": {"type": "array", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "category": {"type": "string", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": 0.3}, "subagents": {"type": "array", "description": "", "default": null}, "middleware": {"type": "array", "description": "", "default": null}, "mcp_servers": {"type": "object", "description": "", "default": null}, "tool_params": {"type": "object", "description": "", "default": null}, "agent_docs": {"type": "object", "description": "", "default": null}}, "required": ["name", "system_prompt", "native_tools"]}', 'string', NULL, '{"category": "agents", "order": 28, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-11-01 03:15:07.803670+00:00', '2026-11-11 01:12:26.331927+00:00'
