SELECT 249, 'db_rename_column', 'DB - Rename a misnamed column (plan, then confirm)', '用我：把一列改成能表达它真实含义的名字（例如 `sold_at` 其实是门店 id → `store_id`），改完再 `db_review(apply=true)`
      就能自动建出那条外键，仪表盘的维度链也会多一层。
别用我：改名之外的结构变更（改类型、拆表）——那属于迁移，不属于这里。

Rename a column, so a misnamed reference becomes a discoverable one. Two phases like the rest:

  * `confirm=False` → reports what the rename touches: the column''s type, null count, whether
    it is part of the primary key or a foreign key, how many distinct values it holds, and
    whether the new name follows the `*_id` convention that lets `db_review` infer the FK.
  * `confirm=True` → runs `ALTER TABLE … RENAME COLUMN …` (one statement, same type, no data
    movement) and tells you to re-run `db_review(apply=true)`.

Refuses a non-ASCII new name, a name that already exists, and a rename of a primary-key or
foreign-key column (those are referenced elsewhere; renaming them is a migration, not a fix).

Args:
    db_name: database
    table: table holding the column
    column: current name
    new_name: lower_snake_case ASCII target name (prefer `<target_table>_id`)
    confirm: set true only after the user agreed to the preview
    host/port/user/password: target server (empty = the platform''s own server)
    schema_name: schema (default public)', 'python_function', 'custom', '{"function_name": "db_rename_column", "code": "# --- imports ---\n\nimport re\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _pg_conn_kwargs(host: str = \"\", port: int = 0, user: str = \"\", password: str = \"\",\n                    dbname: str = \"\") -> dict:\n    \"\"\"Connection kwargs: explicit argument → env (POSTGRES_*) → platform default.\n\n    Defaults to the platform''s own server, so \"no arguments\" means \"the server this app runs\n    on\"; pass host/port to build or inspect a database beside it.\n    \"\"\"\n    import os\n\n    def pick(value, env_name, fallback):\n        if value not in (\"\", None) and value != 0:\n            return value\n        return os.environ.get(env_name) or fallback\n\n    kwargs = {\n        \"host\": pick(host, \"POSTGRES_HOST\", \"localhost\"),\n        \"port\": int(pick(port, \"POSTGRES_PORT\", 5432)),\n        \"user\": pick(user, \"POSTGRES_USER\", \"postgres\"),\n        \"password\": pick(password, \"POSTGRES_PASSWORD\", \"\"),\n    }\n    if dbname:\n        kwargs[\"dbname\"] = dbname\n    return kwargs\n\ndef db_rename_column(db_name: str, table: str, column: str, new_name: str, confirm: bool = False,\n                     host: str = \"\", port: int = 0, user: str = \"\", password: str = \"\",\n                     schema_name: str = \"public\") -> str:\n    \"\"\"\n    用我：把一列改成能表达它真实含义的名字（例如 `sold_at` 其实是门店 id → `store_id`），改完再 `db_review(apply=true)`\n          就能自动建出那条外键，仪表盘的维度链也会多一层。\n    别用我：改名之外的结构变更（改类型、拆表）——那属于迁移，不属于这里。\n\n    Rename a column, so a misnamed reference becomes a discoverable one. Two phases like the rest:\n\n      * `confirm=False` → reports what the rename touches: the column''s type, null count, whether\n        it is part of the primary key or a foreign key, how many distinct values it holds, and\n        whether the new name follows the `*_id` convention that lets `db_review` infer the FK.\n      * `confirm=True` → runs `ALTER TABLE … RENAME COLUMN …` (one statement, same type, no data\n        movement) and tells you to re-run `db_review(apply=true)`.\n\n    Refuses a non-ASCII new name, a name that already exists, and a rename of a primary-key or\n    foreign-key column (those are referenced elsewhere; renaming them is a migration, not a fix).\n\n    Args:\n        db_name: database\n        table: table holding the column\n        column: current name\n        new_name: lower_snake_case ASCII target name (prefer `<target_table>_id`)\n        confirm: set true only after the user agreed to the preview\n        host/port/user/password: target server (empty = the platform''s own server)\n        schema_name: schema (default public)\n    \"\"\"\n    import re\n\n    import psycopg2\n\n    if not re.fullmatch(r\"[a-z_][a-z0-9_]{0,58}\", new_name or \"\"):\n        return f\"Error: new_name {new_name!r} must be lower_snake_case ASCII\"\n\n    target = _pg_conn_kwargs(host, port, user, password, dbname=db_name)\n    try:\n        conn = psycopg2.connect(**target)\n    except Exception as exc:                                   # noqa: BLE001\n        return f\"Error: cannot connect to {db_name}: {exc}\"\n    try:\n        conn.autocommit = True\n        cur = conn.cursor()\n        cur.execute(\"\"\"select data_type, is_nullable from information_schema.columns\n                        where table_schema=%s and table_name=%s and column_name=%s\"\"\",\n                    (schema_name, table, column))\n        row = cur.fetchone()\n        if not row:\n            return f\"Error: {schema_name}.{table}.{column} does not exist\"\n        dtype, nullable = row\n        cur.execute(f''select count(*) from \"{schema_name}\".\"{table}\"'')\n        total = cur.fetchone()[0]\n        cur.execute(f''select count(*) from \"{schema_name}\".\"{table}\" where \"{column}\" is null'')\n        nulls = cur.fetchone()[0]\n        cur.execute(f''select count(distinct \"{column}\") from \"{schema_name}\".\"{table}\"'')\n        distinct = cur.fetchone()[0]\n        cur.execute(\"\"\"select count(*) from information_schema.columns\n                        where table_schema=%s and table_name=%s and column_name=%s\"\"\",\n                    (schema_name, table, new_name))\n        if cur.fetchone()[0]:\n            return f\"Error: {table}.{new_name} already exists\"\n        cur.execute(\"\"\"select conname, contype from pg_constraint\n                        where conrelid = (%s)::regclass\n                          and (contype in (''p'',''f''))\n                          and (%s) = any (\n                              select a.attname from pg_attribute a\n                               where a.attrelid = conrelid and a.attnum = any(conkey))\"\"\",\n                    (f''\"{schema_name}\".\"{table}\"'', column))\n        keyed = cur.fetchall()\n\n        preview = [\n            f\"改名预览：{schema_name}.{table}.{column} → {new_name}\",\n            f\"  类型 {dtype}，可空={nullable}；{total} 行，{nulls} 行为空，{distinct} 个不同值\",\n            f\"  新名字符合 *_id 约定：{''是'' if new_name.endswith(''_id'') else ''否（外键推不出来，建议 <目标表>_id）''}\",\n        ]\n        if keyed:\n            preview.append(\"  该列参与主键/外键：\" + \"、\".join(f\"{n}({t})\" for n, t in keyed)\n                           + \" —— 改名属于迁移，这里拒绝\")\n            return \"\\n\".join(preview)\n        if not confirm:\n            preview.append(\"确认后调用 db_rename_column(..., confirm=true)；然后再跑 db_review(apply=true) 建外键。\")\n            return \"\\n\".join(preview)\n\n        cur.execute(f''ALTER TABLE \"{schema_name}\".\"{table}\" RENAME COLUMN \"{column}\" TO \"{new_name}\"'')\n        preview.append(f\"  已改名。下一步：db_review(db_name=''{db_name}'', apply=true) —— 新名字能让外键自动建上。\")\n        return \"\\n\".join(preview)\n    finally:\n        conn.close()", "args_schema": {"db_name": {"type": "string", "description": ""}, "table": {"type": "string", "description": ""}, "column": {"type": "string", "description": ""}, "new_name": {"type": "string", "description": ""}, "confirm": {"type": "boolean", "description": "", "default": false}, "host": {"type": "string", "description": "", "default": ""}, "port": {"type": "integer", "description": "", "default": 0}, "user": {"type": "string", "description": "", "default": ""}, "password": {"type": "string", "description": "", "default": ""}, "schema_name": {"type": "string", "description": "", "default": "public"}}}', '{"type": "object", "properties": {"db_name": {"type": "string", "description": ""}, "table": {"type": "string", "description": ""}, "column": {"type": "string", "description": ""}, "new_name": {"type": "string", "description": ""}, "confirm": {"type": "boolean", "description": "", "default": false}, "host": {"type": "string", "description": "", "default": ""}, "port": {"type": "integer", "description": "", "default": 0}, "user": {"type": "string", "description": "", "default": ""}, "password": {"type": "string", "description": "", "default": ""}, "schema_name": {"type": "string", "description": "", "default": "public"}}, "required": ["db_name", "table", "column", "new_name"]}', 'string', NULL, '{"category": "database", "order": 70, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-11-11 03:05:55.310055+00:00', '2026-11-11 03:05:55.310057+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'db_rename_column')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 249);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 243, 'db_review', 'DB - Review Schema + Build PK/FK', '用我：体检一个库（行数/空值/主键候选/外键候选），并可以把主键外键建上。
别用我：只想看平台库的表用 pg_list_tables。

Review a database''s tables and keys, and optionally create them.

Primary keys are chosen by name ranking (`id`, then `<table>_id`, then other `*_id`;
money and timestamp columns last, because they are unique by accident in small tables).
A foreign key needs BOTH a `*_id` name and values that all exist in the target''s key —
a value that merely fits another table''s id range is not a reference. A column whose
name promises a timestamp while holding small integers is reported as a naming problem
and left unconstrained.

Args:
    db_name: database to review
    host/port/user/password: target server (empty = the platform''s own server)
    apply: create the primary and foreign keys — only after the user agreed to the review
    schema_name: schema to inspect (default: public)

Returns:
    The review, plus — with apply=True — the constraints created and what was skipped.', 'python_function', 'custom', '{"function_name": "db_review", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _pg_conn_kwargs(host: str = \"\", port: int = 0, user: str = \"\", password: str = \"\",\n                    dbname: str = \"\") -> dict:\n    \"\"\"Connection kwargs: explicit argument → env (POSTGRES_*) → platform default.\n\n    Defaults to the platform''s own server, so \"no arguments\" means \"the server this app runs\n    on\"; pass host/port to build or inspect a database beside it.\n    \"\"\"\n    import os\n\n    def pick(value, env_name, fallback):\n        if value not in (\"\", None) and value != 0:\n            return value\n        return os.environ.get(env_name) or fallback\n\n    kwargs = {\n        \"host\": pick(host, \"POSTGRES_HOST\", \"localhost\"),\n        \"port\": int(pick(port, \"POSTGRES_PORT\", 5432)),\n        \"user\": pick(user, \"POSTGRES_USER\", \"postgres\"),\n        \"password\": pick(password, \"POSTGRES_PASSWORD\", \"\"),\n    }\n    if dbname:\n        kwargs[\"dbname\"] = dbname\n    return kwargs\n\ndef db_review(db_name: str, host: str = \"\", port: int = 0, user: str = \"\", password: str = \"\",\n              apply: bool = False, schema_name: str = \"public\") -> str:\n    \"\"\"\n    用我：体检一个库（行数/空值/主键候选/外键候选），并可以把主键外键建上。\n    别用我：只想看平台库的表用 pg_list_tables。\n\n    Review a database''s tables and keys, and optionally create them.\n\n    Primary keys are chosen by name ranking (`id`, then `<table>_id`, then other `*_id`;\n    money and timestamp columns last, because they are unique by accident in small tables).\n    A foreign key needs BOTH a `*_id` name and values that all exist in the target''s key —\n    a value that merely fits another table''s id range is not a reference. A column whose\n    name promises a timestamp while holding small integers is reported as a naming problem\n    and left unconstrained.\n\n    Args:\n        db_name: database to review\n        host/port/user/password: target server (empty = the platform''s own server)\n        apply: create the primary and foreign keys — only after the user agreed to the review\n        schema_name: schema to inspect (default: public)\n\n    Returns:\n        The review, plus — with apply=True — the constraints created and what was skipped.\n    \"\"\"\n    import psycopg2\n\n    target = _pg_conn_kwargs(host, port, user, password, dbname=db_name)\n    try:\n        conn = psycopg2.connect(**target)\n    except Exception as exc:\n        return f\"Error: cannot connect to {db_name}: {exc}\"\n    cur = conn.cursor()\n    cur.execute(\"\"\"select table_name from information_schema.tables\n                    where table_schema=%s and table_type=''BASE TABLE'' order by 1\"\"\", (schema_name,))\n    tables = [r[0] for r in cur.fetchall()]\n    if not tables:\n        conn.close()\n        return f\"No tables in {db_name}.{schema_name}\"\n\n    out = [f\"# Review of {db_name}.{schema_name} — {len(tables)} tables\"]\n    pk_existing: dict = {}\n    cur.execute(\"\"\"select c.relname, a.attname from pg_index i\n                     join pg_class c on c.oid=i.indrelid\n                     join pg_namespace n on n.oid=c.relnamespace\n                     join pg_attribute a on a.attrelid=c.oid and a.attnum = any(i.indkey)\n                    where i.indisprimary and n.nspname=%s order by 1, a.attnum\"\"\", (schema_name,))\n    for table, col in cur.fetchall():\n        pk_existing.setdefault(table, []).append(col)\n\n    stats: dict = {}\n    pk_cands: dict = {}\n    for table in tables:\n        cur.execute(''select count(*) from \"'' + schema_name + ''\".\"'' + table + ''\"'')\n        total = cur.fetchone()[0]\n        cur.execute(\"\"\"select column_name, data_type from information_schema.columns\n                        where table_schema=%s and table_name=%s order by ordinal_position\"\"\",\n                    (schema_name, table))\n        rows = []\n        for col, dtype in cur.fetchall():\n            cur.execute(''select count(*) filter (where \"'' + col + ''\" is null), count(distinct \"''\n                        + col + ''\") from \"'' + schema_name + ''\".\"'' + table + ''\"'')\n            nulls, distinct = cur.fetchone()\n            rows.append({\"column\": col, \"type\": dtype, \"nulls\": nulls,\n                         \"distinct\": distinct, \"total\": total})\n        stats[table] = rows\n\n        def rank(column: str) -> int:\n            \"\"\"Sort key for a candidate column NAME (not a stats dict — sorting names with a\n            dict-keyed function raised `string indices must be integers`).\"\"\"\n            name = column.lower()\n            if name == \"id\":\n                return 0\n            if name == table.rstrip(\"s\") + \"_id\":\n                return 1\n            if name.endswith(\"_id\"):\n                return 2\n            if name.endswith(\"_at\") or name.endswith(\"_ts\") or name in (\"ts\", \"date\"):\n                return 8\n            if any(k in name for k in (\"amount\", \"price\", \"total\", \"cost\", \"revenue\", \"qty\")):\n                return 9\n            return 5\n\n        cands = sorted([c[\"column\"] for c in rows\n                        if total > 0 and c[\"nulls\"] == 0 and c[\"distinct\"] == total], key=rank)\n        pk_cands[table] = cands   # kept OUT of `stats`: those dicts are columns only\n        out.append(f\"\\n## {table}  ({total} rows)\")\n        out.extend(f\"  - {c[''column'']:<22} {c[''type'']:<24} null={c[''nulls'']} distinct={c[''distinct'']}\"\n                   for c in rows)\n        out.append(f\"  PK 候选: {'', ''.join(cands) if cands else ''（无）''}\")\n\n    def chosen_pk(table: str):\n        key = pk_existing.get(table)\n        if key and len(key) == 1:\n            dtype = next((c[\"type\"] for c in stats[table] if c[\"column\"] == key[0]), \"\")\n            return key[0], dtype\n        cands = pk_cands.get(table) or []\n        if not cands:\n            return None\n        best = cands[0]\n        dtype = next(c[\"type\"] for c in stats[table] if c[\"column\"] == best)\n        return best, dtype\n\n    fam = {\"smallint\": \"int\", \"integer\": \"int\", \"bigint\": \"int\", \"numeric\": \"num\",\n           \"text\": \"txt\", \"character varying\": \"txt\", \"timestamp with time zone\": \"ts\",\n           \"boolean\": \"bool\", \"date\": \"date\", \"jsonb\": \"json\"}\n    named_fks: list = []\n    hints: list = []\n    out.append(\"\\n## 外键候选\")\n    for table in tables:\n        for c in stats[table]:\n            col, dtype = c[\"column\"], c[\"type\"]\n            if not col.lower().endswith(\"_id\") or col.lower() == \"id\" or c[\"distinct\"] == 0:\n                continue\n            base = col.lower()[:-3]\n            targets = [t for t in tables\n                       if t.lower() in (base, base + \"s\", base + \"es\") or t.lower().rstrip(\"s\") == base]\n            for ref in targets:\n                if ref == table:\n                    continue\n                key = chosen_pk(ref)\n                if not key:\n                    continue\n                ref_col, ref_type = key\n                if fam.get(dtype) != fam.get(ref_type):\n                    continue\n                cur.execute(''select count(*) from \"'' + schema_name + ''\".\"'' + table + ''\" t where t.\"''\n                            + col + ''\" is not null and not exists (select 1 from \"''\n                            + schema_name + ''\".\"'' + ref + ''\" r where r.\"'' + ref_col\n                            + ''\" = t.\"'' + col + ''\")'')\n                orphans = cur.fetchone()[0]\n                if orphans == 0:\n                    out.append(f\"  {table}.{col} -> {ref}.{ref_col}  (0 orphans, {c[''distinct'']} values)\")\n                    named_fks.append((table, col, ref, ref_col))\n                else:\n                    out.append(f\"  {table}.{col} -> {ref}.{ref_col}  x {orphans} orphans (not built)\")\n        for c in stats[table]:\n            name = c[\"column\"].lower()\n            if fam.get(c[\"type\"]) == \"int\" and name.endswith((\"_at\", \"_code\", \"_no\", \"_key\")) \\\n                    and c[\"distinct\"]:\n                hints.append(f\"  {table}.{c[''column'']} — 名字像时间/编码，取值却是小整数，可能是命名 bug\"\n                             f\"（例如 sold_at 实际存门店 id）\")\n\n    if not named_fks:\n        out.append(\"  （无）\")\n    if hints:\n        out.append(\"\\n## 命名提示（不建约束，建议改名后再建）\")\n        out.extend(hints)\n\n    if not apply:\n        conn.close()\n        out.append(\"\\n报告模式：没有改动数据库。要建约束请再调用一次 apply=true。\")\n        return \"\\n\".join(out)\n\n    out.append(\"\\n## 应用约束\")\n    for table in tables:\n        if pk_existing.get(table):\n            out.append(f\"  {table}: 已有主键，跳过\")\n            continue\n        key = chosen_pk(table)\n        if not key:\n            out.append(f\"  {table}: 无主键候选，跳过\")\n            continue\n        try:\n            cur.execute(''ALTER TABLE \"'' + schema_name + ''\".\"'' + table\n                        + ''\" ADD CONSTRAINT \"'' + table + ''_pkey\" PRIMARY KEY (\"'' + key[0] + ''\")'')\n            conn.commit()\n            out.append(f\"  {table}: PK ({key[0]}) ok\")\n        except Exception as exc:\n            conn.rollback()\n            out.append(f\"  {table}: PK 失败 — {exc}\")\n\n    cur.execute(\"\"\"select conrelid::regclass::text from pg_constraint\n                    where contype=''f'' and connamespace=(select oid from pg_namespace where nspname=%s)\"\"\",\n                (schema_name,))\n    for table, col, ref, ref_col in named_fks:\n        try:\n            cur.execute(''ALTER TABLE \"'' + schema_name + ''\".\"'' + table + ''\" ADD CONSTRAINT \"''\n                        + table + \"_\" + col + ''_fkey\" FOREIGN KEY (\"'' + col + ''\") REFERENCES \"''\n                        + schema_name + ''\".\"'' + ref + ''\" (\"'' + ref_col + ''\")'')\n            conn.commit()\n            out.append(f\"  {table}.{col} -> {ref}.{ref_col}: FK ok\")\n        except Exception as exc:\n            conn.rollback()\n            out.append(f\"  {table}.{col}: FK 失败 — {exc}\")\n    conn.close()\n    return \"\\n\".join(out)", "args_schema": {"db_name": {"type": "string", "description": ""}, "host": {"type": "string", "description": "", "default": ""}, "port": {"type": "integer", "description": "", "default": 0}, "user": {"type": "string", "description": "", "default": ""}, "password": {"type": "string", "description": "", "default": ""}, "apply": {"type": "boolean", "description": "", "default": false}, "schema_name": {"type": "string", "description": "", "default": "public"}}}', '{"type": "object", "properties": {"db_name": {"type": "string", "description": ""}, "host": {"type": "string", "description": "", "default": ""}, "port": {"type": "integer", "description": "", "default": 0}, "user": {"type": "string", "description": "", "default": ""}, "password": {"type": "string", "description": "", "default": ""}, "apply": {"type": "boolean", "description": "", "default": false}, "schema_name": {"type": "string", "description": "", "default": "public"}}, "required": ["db_name"]}', 'string', NULL, '{"category": "database", "order": 66, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-11-11 01:12:26.337163+00:00', '2026-11-11 02:00:59.931393+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'db_review')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 243);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 245, 'db_verify_against_file', 'DB - Verify against Excel/CSV', '用我：建库之后核对"库里真的是这个文件吗"——行数、列名、每一行的值、数值合计，逐 sheet 对账。
别用我：只看结构用 db_review；只想读文件用 read_any_file。

Cross-check a loaded database against the spreadsheet it came from.

For every sheet in the file it finds the matching table (same naming rules the build
used), then compares: the table exists, the row count, the **column names**, and the
full row multiset — values normalised so that `120` from the sheet and
`Decimal(''120.000'')` from Postgres count as equal, but `120` and `180` never do.
Columns are matched BY NAME, not by position: a rename (`sold_at` → `store_id`) used to
pass as "5 columns vs 5 columns" and the row values happened to line up, which made the
one check that proves the load a false PASS. Numeric columns also get their SUM/MIN/MAX
compared, because that catches "right number of rows, wrong column content" which a
count alone cannot. Any table in the database that the file did not produce is reported
too — a leftover from an earlier build is exactly the kind of thing a user will later
query by accident.

Returns PASS only when every sheet matches on all of those checks. PARTIAL means the
counts match but values do not; FAIL names the first differences, with row indexes.

Args:
    file: the .xlsx / .csv that was loaded (inside the workspace)
    db_name: the database to verify, e.g. "orders_xlsx"
    host/port/user/password: target server (empty = the platform''s own server)
    max_examples: how many differing rows to show per table (default 5)
    renames: a rename you made on purpose after the build, so it is not reported as a
        mismatch — "orders.sold_at=store_id,customers.status=tier"

Returns:
    A per-table verdict table plus a final PASS / PARTIAL / FAIL line.', 'python_function', 'custom', '{"function_name": "db_verify_against_file", "code": "# --- imports ---\n\nimport re\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\nimport csv as _csv\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef _pg_conn_kwargs(host: str = \"\", port: int = 0, user: str = \"\", password: str = \"\",\n                    dbname: str = \"\") -> dict:\n    \"\"\"Connection kwargs: explicit argument → env (POSTGRES_*) → platform default.\n\n    Defaults to the platform''s own server, so \"no arguments\" means \"the server this app runs\n    on\"; pass host/port to build or inspect a database beside it.\n    \"\"\"\n    import os\n\n    def pick(value, env_name, fallback):\n        if value not in (\"\", None) and value != 0:\n            return value\n        return os.environ.get(env_name) or fallback\n\n    kwargs = {\n        \"host\": pick(host, \"POSTGRES_HOST\", \"localhost\"),\n        \"port\": int(pick(port, \"POSTGRES_PORT\", 5432)),\n        \"user\": pick(user, \"POSTGRES_USER\", \"postgres\"),\n        \"password\": pick(password, \"POSTGRES_PASSWORD\", \"\"),\n    }\n    if dbname:\n        kwargs[\"dbname\"] = dbname\n    return kwargs\n\ndef _ident(name: str, fallback: str = \"c\") -> str:\n    \"\"\"ASCII snake_case identifier from an arbitrary header / sheet name.\"\"\"\n    import re\n    cleaned = re.sub(r\"[^0-9A-Za-z]+\", \"_\", str(name or \"\").strip()).strip(\"_\").lower()\n    if not cleaned:\n        return fallback\n    if cleaned[0].isdigit():\n        cleaned = fallback + \"_\" + cleaned\n    return cleaned[:60]\n\ndef _resolve_agent_file(value: str):\n    \"\"\"(path, error) for a spreadsheet argument: sandbox-checked, and relative to the run workspace.\n\n    Two things a plain `Path(value).resolve()` gets wrong here: a RELATIVE path resolves against\n    the server''s cwd (`backend/`) so an agent cannot open `upload/orders.xlsx`, and an ABSOLUTE\n    path outside the sandbox (`/etc/passwd`) was accepted. The first is why the table-building\n    agent could not read its own upload; the second is why that argument needed a sandbox.\n    \"\"\"\n    if not Path(value).expanduser().is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / Path(value).expanduser()).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n        looked = \", \".join(str(r) for r in _sandbox_roots()[:2])\n        return None, f\"Error: no such file: {value} (looked under {looked})\"\n    resolved, error = _resolve_sandbox_path(value)\n    if error:\n        return None, error\n    return resolved, None\n\ndef _read_source_sheets(path):\n    \"\"\"(sheets, error) — {sheet: (headers, body)} from an .xlsx/.xlsm/.csv, same rules as the build.\n\n    Shared by `db_build_from_file` and `db_verify_against_file` on purpose: a verifier that\n    parses the file differently from the builder would \"confirm\" its own parsing bug.\n    \"\"\"\n    sheets: dict = {}\n    suffix = path.suffix.lower()\n    if suffix in (\".xlsx\", \".xlsm\"):\n        from openpyxl import load_workbook\n        wb = load_workbook(path, data_only=True, read_only=True)\n        try:\n            for sheet in wb.sheetnames:\n                if sheet in (\"00_index\", \"catalog\"):\n                    continue  # exporter metadata, not tables\n                data = list(wb[sheet].iter_rows(values_only=True))\n                if not data or not data[0]:\n                    continue\n                headers = [\"\" if c is None else str(c) for c in data[0]]\n                body = [list(r) for r in data[1:]\n                        if any(c is not None and str(c).strip() != \"\" for c in r)]\n                if body:\n                    sheets[sheet] = (headers, body)\n        finally:\n            wb.close()\n    elif suffix == \".csv\":\n        import csv as _csv\n        with path.open(newline=\"\", encoding=\"utf-8-sig\", errors=\"replace\") as fh:\n            reader = list(_csv.reader(fh))\n        if reader:\n            sheets[path.stem] = (reader[0], [r for r in reader[1:] if any(str(c).strip() for c in r)])\n    else:\n        return {}, f\"Error: unsupported file type {suffix!r} (use .xlsx / .xlsm / .csv)\"\n    if not sheets:\n        return {}, \"Error: nothing to read — every sheet was empty\"\n    return sheets, None\n\ndef _canon(value) -> str:\n    \"\"\"Canonical string for comparing one cell across two representations.\n\n    The same value arrives differently on each side: the file gives `120` (int) where the\n    database returns `Decimal(''120.000'')`; a timestamp is a `str` in the sheet and a\n    `datetime` from psql; a JSONB column comes back as a dict. Comparing `str()` on both\n    sides would report thousands of \"differences\" that are formatting.\n    \"\"\"\n    import datetime as _dt\n    import json as _json\n    from decimal import Decimal as _Decimal\n\n    if value is None:\n        return \"∅\"\n    if isinstance(value, bool):\n        return \"t\" if value else \"f\"\n    if isinstance(value, _Decimal):\n        if value == value.to_integral_value():\n            return str(value.to_integral_value())\n        return format(value.normalize(), \"f\")\n    if isinstance(value, int):\n        return str(value)\n    if isinstance(value, float):\n        return _canon(_Decimal(str(value)))\n    if isinstance(value, _dt.datetime):\n        return value.isoformat(sep=\" \")\n    if isinstance(value, _dt.date):\n        return value.isoformat()\n    if isinstance(value, (dict, list)):\n        return _json.dumps(value, ensure_ascii=False, sort_keys=True)\n    return str(value).strip()\n\ndef _multiset(rows) -> dict:\n    \"\"\"Row → count, so comparison survives a different physical order.\"\"\"\n    from collections import Counter\n    return Counter(tuple(_canon(v) for v in row) for row in rows)\n\ndef db_verify_against_file(file: str, db_name: str, host: str = \"\", port: int = 0,\n                           user: str = \"\", password: str = \"\", max_examples: int = 5,\n                           renames: str = \"\") -> str:\n    \"\"\"\n    用我：建库之后核对\"库里真的是这个文件吗\"——行数、列名、每一行的值、数值合计，逐 sheet 对账。\n    别用我：只看结构用 db_review；只想读文件用 read_any_file。\n\n    Cross-check a loaded database against the spreadsheet it came from.\n\n    For every sheet in the file it finds the matching table (same naming rules the build\n    used), then compares: the table exists, the row count, the **column names**, and the\n    full row multiset — values normalised so that `120` from the sheet and\n    `Decimal(''120.000'')` from Postgres count as equal, but `120` and `180` never do.\n    Columns are matched BY NAME, not by position: a rename (`sold_at` → `store_id`) used to\n    pass as \"5 columns vs 5 columns\" and the row values happened to line up, which made the\n    one check that proves the load a false PASS. Numeric columns also get their SUM/MIN/MAX\n    compared, because that catches \"right number of rows, wrong column content\" which a\n    count alone cannot. Any table in the database that the file did not produce is reported\n    too — a leftover from an earlier build is exactly the kind of thing a user will later\n    query by accident.\n\n    Returns PASS only when every sheet matches on all of those checks. PARTIAL means the\n    counts match but values do not; FAIL names the first differences, with row indexes.\n\n    Args:\n        file: the .xlsx / .csv that was loaded (inside the workspace)\n        db_name: the database to verify, e.g. \"orders_xlsx\"\n        host/port/user/password: target server (empty = the platform''s own server)\n        max_examples: how many differing rows to show per table (default 5)\n        renames: a rename you made on purpose after the build, so it is not reported as a\n            mismatch — \"orders.sold_at=store_id,customers.status=tier\"\n\n    Returns:\n        A per-table verdict table plus a final PASS / PARTIAL / FAIL line.\n    \"\"\"\n    declared = {}\n    for item in (renames or \"\").split(\",\"):\n        if \"=\" not in item:\n            continue\n        left, new = item.split(\"=\", 1)\n        if \".\" in left:\n            tbl, old = left.rsplit(\".\", 1)\n            declared[(tbl.strip().lower(), old.strip().lower())] = new.strip().lower()\n    from pathlib import Path\n\n    import psycopg2\n\n    path, path_error = _resolve_agent_file(file)\n    if path_error:\n        return path_error\n    sheets, error = _read_source_sheets(path)\n    if error:\n        return error\n\n    target = _pg_conn_kwargs(host, port, user, password, dbname=db_name)\n    try:\n        conn = psycopg2.connect(**target)\n    except Exception as exc:\n        return f\"Error: cannot connect to {db_name}: {exc}\"\n    conn.set_session(readonly=True, autocommit=True)\n    cur = conn.cursor()\n\n    cur.execute(\"\"\"select table_name from information_schema.columns\n                    where table_schema=''public'' group by 1 order by 1\"\"\")\n    db_tables = {r[0] for r in cur.fetchall()}\n\n    out = [f\"# 核对：{path.name} → {db_name} @ {target[''host'']}:{target[''port'']}\"]\n    failures = 0\n    partials = 0\n    seen = set()\n\n    for sheet_name, (headers, body) in sheets.items():\n        table = _ident(sheet_name, fallback=\"sheet\")\n        seen.add(table)\n        if table not in db_tables:\n            out.append(f\"\\n## [{sheet_name}] -> {table}: ✗ 表不存在\")\n            failures += 1\n            continue\n\n        cur.execute(''select * from \"'' + table + ''\"'')\n        db_rows = cur.fetchall()\n        db_cols = [d[0] for d in cur.description]\n\n        file_rows = len(body)\n        db_count = len(db_rows)\n\n        # Names, not positions. The build names columns after the sheet''s header, so a\n        # column the file calls X must be a column the database calls X — unless the caller\n        # declares the rename it made on purpose (`renames=\"orders.sold_at=store_id\"`).\n        want = [declared.get((table, (h or \"\").strip().lower()), (h or \"\").strip().lower())\n                for h in headers]\n        have = [(c or \"\").strip().lower() for c in db_cols]\n        missing_cols = [h for h in want if h not in have]\n        extra_cols = [c for c in have if c not in want]\n        col_ok = not missing_cols and not extra_cols and len(have) == len(want)\n        reordered = False\n        if col_ok and have != want:\n            # Same names, different order (a rename applied, or the table was rebuilt by\n            # hand): reorder the database rows to the file''s order once, and every\n            # positional comparison below stays meaningful.\n            order = [have.index(w) for w in want]\n            db_rows = [tuple(r[i] for i in order) for r in db_rows]\n            db_cols = [db_cols[i] for i in order]\n            reordered = True\n\n        same_rows = 0\n        diff_examples = []\n        if col_ok and file_rows == db_count:\n            file_ms = _multiset(body)\n            db_ms = _multiset(db_rows)\n            same_rows = sum((file_ms & db_ms).values())\n            if same_rows != file_rows:\n                for i, row in enumerate(body):\n                    key = tuple(_canon(v) for v in row)\n                    if db_ms.get(key, 0) == 0 and len(diff_examples) < max_examples:\n                        # Pair by the first column, not by index: the database returns rows in\n                        # whatever order it likes, so index-pairing showed a *different* row as\n                        # the neighbour (\"file row 0 vs db row 0\" was two unrelated products).\n                        head = _canon(row[0]) if row else None\n                        db_row = next((r for r in db_rows if r and _canon(r[0]) == head), None)\n                        diff_examples.append((\"row\", i, row, db_row if db_row is not None else \"（库里没有对应行）\"))\n\n        # numeric aggregates — a count can match while every value sits in the wrong column\n        agg_lines = []\n        if col_ok:\n            for i, col in enumerate(db_cols):\n                numbers = []\n                for row in body:\n                    raw = row[i] if i < len(row) else None\n                    try:\n                        from decimal import Decimal as _D\n                        if raw not in (None, \"\"):\n                            numbers.append(_D(str(raw)))\n                    except Exception:\n                        numbers = []\n                        break\n                if not numbers or len(numbers) != file_rows:\n                    continue\n                cur.execute(''select sum(\"'' + col + ''\"), min(\"'' + col + ''\"), max(\"'' + col + ''\") from \"''\n                            + table + ''\"'')\n                dsum, dmin, dmax = cur.fetchone()\n                fsum, fmin, fmax = sum(numbers), min(numbers), max(numbers)\n                if dsum is None:\n                    continue\n                ok = (_canon(dsum) == _canon(fsum) and _canon(dmin) == _canon(fmin)\n                      and _canon(dmax) == _canon(fmax))\n                agg_lines.append(f\"    {col}: sum {_canon(fsum)} vs {_canon(dsum)}\"\n                                 + (\"\" if ok else \"  ✗\"))\n                if not ok:\n                    diff_examples.append((\"sum\", col, _canon(fsum), _canon(dsum)))\n\n        verdict = \"PASS\"\n        problems = []\n        if missing_cols or extra_cols:\n            bit = []\n            if missing_cols:\n                bit.append(\"文件有库里没有：\" + \", \".join(missing_cols))\n            if extra_cols:\n                bit.append(\"库里有文件没有：\" + \", \".join(extra_cols))\n            problems.append(\"列名不一致（\" + \"；\".join(bit) + \"）—— 改名/加删列后用 renames 声明\")\n        elif not col_ok:\n            problems.append(f\"列数 {len(headers)} vs {len(db_cols)}\")\n        if file_rows != db_count:\n            problems.append(f\"行数 {file_rows} vs {db_count}\")\n        if col_ok and file_rows == db_count and same_rows != file_rows:\n            problems.append(f\"{file_rows - same_rows} 行的值不一致\")\n        if problems:\n            verdict = \"FAIL\" if (not col_ok or file_rows != db_count) else \"PARTIAL\"\n            failures += 1 if verdict == \"FAIL\" else 0\n            partials += 1 if verdict == \"PARTIAL\" else 0\n\n        out.append(f\"\\n## [{sheet_name}] -> {table}: {verdict}\")\n        out.append(f\"  行数 {file_rows} vs {db_count} | 列数 {len(headers)} vs {len(db_cols)} | \"\n                   f\"一致的整行 {same_rows}/{file_rows}\")\n        if reordered:\n            out.append(\"  列顺序不同（已按列名对齐后比较）\")\n        for problem in problems:\n            out.append(f\"  ✗ {problem}\")\n        out.extend(agg_lines[:8])\n        # Both kinds of difference end up in the same list; unpacking was assuming 3 fields\n        # for row diffs and 4 for aggregate diffs (`too many values to unpack`).\n        for kind, where, left, right in diff_examples[:max_examples]:\n            if kind == \"sum\":\n                out.append(f\"  ✗ 合计不符 {where}: 文件 {left} ≠ 库 {right}\")\n            else:\n                out.append(f\"  ✗ 第 {where} 行: 文件 {left} ≠ 库 {right}\")\n\n    extra = sorted(db_tables - seen)\n    if extra:\n        out.append(\"\\n## 库里多出来的表（文件没有）\")\n        out.append(\"  \" + \", \".join(extra) + \"  ← 可能是上一次建库的残留\")\n\n    conn.close()\n    if failures:\n        out.append(f\"\\nFAIL — {failures} 张表对不上，别拿这个库回答业务问题。\")\n        return \"\\n\".join(out)\n    if partials:\n        out.append(f\"\\nPARTIAL — 行数都对，但 {partials} 张表里有值对不上；先查清再报数。\")\n        return \"\\n\".join(out)\n    out.append(\"\\nPASS — 每张表的行数、列和值都与文件一致。\")\n    return \"\\n\".join(out)", "args_schema": {"file": {"type": "string", "description": ""}, "db_name": {"type": "string", "description": ""}, "host": {"type": "string", "description": "", "default": ""}, "port": {"type": "integer", "description": "", "default": 0}, "user": {"type": "string", "description": "", "default": ""}, "password": {"type": "string", "description": "", "default": ""}, "max_examples": {"type": "integer", "description": "", "default": 5}, "renames": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"file": {"type": "string", "description": ""}, "db_name": {"type": "string", "description": ""}, "host": {"type": "string", "description": "", "default": ""}, "port": {"type": "integer", "description": "", "default": 0}, "user": {"type": "string", "description": "", "default": ""}, "password": {"type": "string", "description": "", "default": ""}, "max_examples": {"type": "integer", "description": "", "default": 5}, "renames": {"type": "string", "description": "", "default": ""}}, "required": ["file", "db_name"]}', 'string', NULL, '{"category": "database", "order": 68, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-11-11 01:16:18.116325+00:00', '2026-11-11 08:16:53.677948+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'db_verify_against_file')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 245);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 87, 'delete_file', 'Delete File', 'Delete a file (or an empty directory) inside the workspace sandbox.

Use when the user asks to remove or clean up a file. Refuses to delete
non-empty directories — there is no recursive delete by design.

Args:
    file_path: Path to the file to delete (relative to the workspace or absolute)', 'python_function', 'custom', '{"function_name": "delete_file", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef delete_file(file_path: str) -> str:\n    \"\"\"Delete a file (or an empty directory) inside the workspace sandbox.\n\n    Use when the user asks to remove or clean up a file. Refuses to delete\n    non-empty directories — there is no recursive delete by design.\n\n    Args:\n        file_path: Path to the file to delete (relative to the workspace or absolute)\n    \"\"\"\n    resolved, error = _resolve_sandbox_path(file_path)\n    if error:\n        return error\n    if not resolved.exists():\n        return f\"Error: ''{file_path}'' not found\"\n    if resolved.is_dir():\n        try:\n            resolved.rmdir()\n            return f\"Removed empty directory ''{file_path}''\"\n        except OSError:\n            return (f\"Error: ''{file_path}'' is a non-empty directory — \"\n                    f\"refusing recursive delete\")\n    resolved.unlink()\n    return f\"Deleted file ''{file_path}''\"", "args_schema": {"file_path": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": ""}}, "required": ["file_path"]}', 'string', NULL, '{"category": "filesystem", "order": 9, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-15 08:02:47.985665+00:00', '2026-11-11 02:00:59.925339+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'delete_file')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 87);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 83, 'delete_skill', 'Delete Skill', 'Delete a skill from the database by its skill_id.

Args:
    skill_id: The kebab-case ID of the skill to delete', 'python_function', 'custom', '{"function_name": "delete_skill", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport re as _re\n\ndef _skill_support_files(base: Path, limit: int = 40) -> list:\n    \"\"\"Files next to SKILL.md, as skill-relative paths (sorted, capped).\n\n    A skill that ships templates or reference tables is useless if the model\n    cannot see that they exist: the instructions are in the DB, the files are on\n    disk. Seen 2026-11-01 — Agent Builder rebuilt a template from memory because\n    `templates/` was invisible.\n    \"\"\"\n    if base is None or not base.is_dir():\n        return []\n    out = []\n    for path in sorted(base.rglob(\"*\")):\n        if not path.is_file() or path.name == \"SKILL.md\":\n            continue\n        out.append(str(path.relative_to(base)))\n        if len(out) >= limit:\n            break\n    return out\n\nasync def skill(skill_id: str, file: str = \"\", lang: str = \"\") -> str:\n    \"\"\"Fetch a skill''s full instructions by its id — or one of its support files.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Skills may ship supporting files next to SKILL.md (templates, fact tables,\n    scripts). Those are NOT loaded with the instructions; list them with this\n    tool first (it prints `Support files:`), then ask for one by path.\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n        file: Optional path inside the skill directory, e.g.\n              \"templates/T2-supervisor-experts.md\". Leave empty for the\n              instructions. Must stay inside the skill.\n        lang: Which language to serve. Empty (the default) serves `SKILL.md` — the working text, which is\n              Chinese for every skill that has been translated. `lang=\"en\"` serves the archived English\n              original from `backend/skills/en-originals/<id>/SKILL.md`, which nothing else reads: it is a\n              backup and a source for checking a translation, and it enters a context only when asked for\n              by name.\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            registry.record_usage(skill_id, \"explicit\", \"failed\", source=\"skill tool: not found\")\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        base = Path(found.source_path) if getattr(found, \"source_path\", None) else None\n\n        if file:\n            if base is None or not base.is_dir():\n                return f\"Error: skill ''{skill_id}'' has no source directory on disk.\"\n            target = (base / file).resolve()\n            try:\n                target.relative_to(base.resolve())\n            except ValueError:\n                return f\"Error: ''{file}'' escapes skill ''{skill_id}''.\"\n            if not target.is_file():\n                listing = _skill_support_files(base)\n                return (f\"Error: ''{file}'' not found in skill ''{skill_id}''. \"\n                        f\"Support files: {'', ''.join(listing) or ''none''}\")\n            text = target.read_text(encoding=\"utf-8\", errors=\"replace\")\n            return f\"# Skill file: {skill_id}/{file}\\n\\n{text}\"\n\n        # The working text is Chinese: `SKILL.md` is what an agent reads, and the English original lives\n        # outside the skill library (`backend/skills/en-originals/<id>/`) as a backup. Nothing loads it\n        # unless the caller asks for it explicitly by language — which is why the default below is the\n        # canonical file and not a sibling.\n        body_text, body_lang = found.instructions, \"zh\"\n        if lang and lang.split(\"-\")[0].lower() == \"en\":\n            # base is .../skills/builtin/<id>; the archive sits beside the library root\n            archived = (Path(base).parents[1] / \"en-originals\" / found.skill_id / \"SKILL.md\"\n                        if base is not None else None)\n            if archived is not None and archived.is_file():\n                raw = archived.read_text(encoding=\"utf-8\", errors=\"replace\")\n                if raw.startswith(\"---\"):\n                    end = raw.find(\"\\n---\", 3)\n                    if end != -1:\n                        raw = raw[end + 4:].lstrip(\"\\n\")\n                body_text, body_lang = raw, \"en\"\n        parts = [\n            f\"# Skill: {found.name}\" + (f\"  (instructions: {body_lang})\" if body_lang != \"zh\" else \"\"),\n            f\"**Description:** {found.description}\",\n            \"\",\n            body_text,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        support = _skill_support_files(base) if base else []\n        if support:\n            parts += [\n                \"\",\n                \"**Support files** (not loaded above — fetch one with \"\n                f\"skill(\\\"{found.skill_id}\\\", file=\\\"<path>\\\")):\",\n                *[f\"- {f}\" for f in support],\n            ]\n        # Count the use. Until this existed, `usage_count`/`avg_success_rate` were read by the UI and written by\n        # nobody: the library showed \"0 uses\" for skills that had been served hundreds of times.\n        registry.record_usage(found.skill_id, \"explicit\", \"success\", source=\"skill tool\")\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"\n\ndef delete_skill(skill_id: str) -> str:\n    \"\"\"Delete a skill from the database by its skill_id.\n\n    Args:\n        skill_id: The kebab-case ID of the skill to delete\n    \"\"\"\n    from db.database import SessionLocal\n    from models.skill import Skill\n    import re as _re\n\n    # Sanitize the identifier before touching the DB.\n    if not _re.fullmatch(r\"[a-z0-9][a-z0-9-]*\", skill_id or \"\"):\n        return f\"❌ Invalid skill_id ''{skill_id}'': use kebab-case (letters, digits, hyphens).\"\n\n    db = SessionLocal()\n    try:\n        skill = db.query(Skill).filter(Skill.skill_id == skill_id).first()\n        if not skill:\n            return f\"❌ Skill ''{skill_id}'' not found.\"\n        db.delete(skill)\n        db.commit()\n        return f\"✅ Skill ''{skill_id}'' deleted successfully!\"\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to delete skill: {e}\"\n    finally:\n        db.close()", "args_schema": {"skill_id": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"skill_id": {"type": "string", "description": ""}}, "required": ["skill_id"]}', 'string', NULL, '{"category": "skills", "order": 27, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-01 14:44:18.034637+00:00', '2026-11-11 01:12:26.325790+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'delete_skill')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 83);

