SELECT 107, 'doc_to_deck', 'Document to Deck (HTML+PPTX)', '用我：从一份文档一步生成 HTML+PPTX 两版幻灯片。
    别用我：只要一份普通文档用 write_file；只想先看大纲用 doc_to_slides_outline。
Convert one or more documents (.md / .txt / .pdf / .docx) into themed
    HTML + PPTX decks in a single call (batch supported).

    Pipeline: read each document → LLM outline (12–15 slides, draft → refine)
    → normalize against the template → render HTML (single file, no CDN) and
    PPTX (from the template''s own layouts). With multiple documents, each doc
    becomes a section of one combined deck.

    Args:
        file_paths: JSON array of absolute document paths, e.g.
            ''["/abs/doc1.md", "/abs/doc2.pdf"]'' (a single path is fine too).
        template: Template id (business|fashion|tech|health|education|minimal).
        formats: Comma-separated outputs: html, pptx (pdf also supported).
        output_dir: Output directory (inside the presentation output folder).
        pages: Target slide count (0 = template default).

    Returns:
        Paths of the generated files.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import doc_to_deck\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"用我：从一份文档一步生成 HTML+PPTX 两版幻灯片。     别用我：只要一份普通文档用 write_file；只想先看大纲用 doc_to_slides_outline。 Convert one or more documents (.md / .txt / .pdf / .docx) into themed \"\"\"\n    return str(await doc_to_deck.ainvoke({**kwargs}))\n", "args_schema": {"file_paths": {"type": "string", "description": ""}, "template": {"type": "string", "description": "", "default": "business"}, "formats": {"type": "string", "description": "", "default": "html,pptx"}, "output_dir": {"type": "string", "description": "", "default": ""}, "pages": {"type": "integer", "description": "", "default": 0}}}', '{"type": "object", "properties": {"file_paths": {"type": "string", "description": ""}, "template": {"type": "string", "description": "", "default": "business"}, "formats": {"type": "string", "description": "", "default": "html,pptx"}, "output_dir": {"type": "string", "description": "", "default": ""}, "pages": {"type": "integer", "description": "", "default": 0}}, "required": ["file_paths"]}', 'string', NULL, '{"category": "presentation", "order": 22, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078099+00:00', '2026-11-11 01:12:26.331925+00:00'
