SELECT 48, 'edit_file', 'Edit File', 'Perform exact string replacement in a file.

Finds the old_string in the file and replaces it with new_string.
The old_string must be unique in the file to avoid ambiguous edits.

Example:
    edit_file(file_path="config.py", old_string="DEBUG = False", new_string="DEBUG = True")', 'python_function', 'custom', '{"function_name": "_edit_file_impl", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nimport os\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef _record_file_version(\n    file_path: Path,\n    operation: str,\n    content: str = None,\n    old_string: str = None,\n    new_string: str = None,\n    workspace_context: dict = None,\n    agent_context: dict = None\n) -> None:\n    \"\"\"\n    Record a file version in the database for diff viewing.\n\n    This creates a FileVersion record that tracks changes to files,\n    enabling version history and diff viewing in the UI.\n\n    Args:\n        file_path: Full path to the file\n        operation: \"create\", \"edit\", or \"replace\"\n        content: Full content for create/replace operations\n        old_string: For edit operations, the string that was replaced\n        new_string: For edit operations, the replacement string\n        workspace_context: Context about the workspace (project_id, workflow_id, task_id)\n        agent_context: Context about the agent making the change\n    \"\"\"\n    try:\n        import hashlib\n        from db.database import SessionLocal\n        from models.workspace_file import WorkspaceFile\n        from models.file_version import FileVersion\n        from services.workspace_manager import get_workspace_manager\n\n        # Compute relative path from outputs/ directory\n        workspace_mgr = get_workspace_manager()\n        outputs_dir = workspace_mgr.base_dir\n        try:\n            relative_path = str(file_path.relative_to(outputs_dir))\n        except ValueError:\n            relative_path = str(file_path)\n\n        db = SessionLocal()\n        try:\n            # Find or create the WorkspaceFile record\n            workspace_file = db.query(WorkspaceFile).filter(\n                WorkspaceFile.file_path == relative_path\n            ).first()\n\n            if not workspace_file:\n                logger.debug(f\"No WorkspaceFile record found for {relative_path}, skipping version tracking\")\n                return\n\n            # Get the current version number\n            max_version = db.query(FileVersion).filter(\n                FileVersion.workspace_file_id == workspace_file.id\n            ).count()\n            new_version_number = max_version + 1\n\n            # Compute content hash if we have content\n            content_hash = None\n            if content:\n                content_hash = hashlib.sha256(content.encode(''utf-8'')).hexdigest()\n\n            # Calculate line changes for edits\n            lines_added = None\n            lines_removed = None\n            change_summary = None\n\n            if operation == \"create\":\n                lines_added = content.count(''\\n'') + 1 if content else 0\n                lines_removed = 0\n                change_summary = f\"Created file with {lines_added} lines\"\n            elif operation == \"edit\" and old_string and new_string:\n                old_lines = old_string.count(''\\n'')\n                new_lines = new_string.count(''\\n'')\n                lines_added = max(0, new_lines - old_lines)\n                lines_removed = max(0, old_lines - new_lines)\n                change_summary = f\"Replaced {len(old_string)} chars with {len(new_string)} chars\"\n            elif operation == \"replace\":\n                lines_added = content.count(''\\n'') + 1 if content else 0\n                change_summary = f\"Replaced entire file ({lines_added} lines)\"\n\n            # Create the version record\n            file_version = FileVersion(\n                workspace_file_id=workspace_file.id,\n                version_number=new_version_number,\n                content_hash=content_hash,\n                content_snapshot=content if operation in (\"create\", \"replace\") else None,\n                operation=operation,\n                old_string=old_string,\n                new_string=new_string,\n                agent_label=agent_context.get(''agent_label'') if agent_context else None,\n                agent_type=agent_context.get(''agent_type'') if agent_context else None,\n                node_id=agent_context.get(''node_id'') if agent_context else None,\n                task_id=workspace_context.get(''task_id'') if workspace_context else None,\n                execution_id=workspace_context.get(''execution_id'') if workspace_context else None,\n                change_summary=change_summary,\n                lines_added=lines_added,\n                lines_removed=lines_removed,\n            )\n            db.add(file_version)\n            db.commit()\n\n            logger.debug(f\"Recorded version {new_version_number} for {relative_path} (operation: {operation})\")\n\n        finally:\n            db.close()\n\n    except Exception as e:\n        # Don''t fail the file operation if version recording fails\n        logger.warning(f\"Could not record file version: {e}\")\n\ndef _edit_file_impl(\n    file_path: str,\n    old_string: str,\n    new_string: str,\n    _workspace_context: dict = None,\n    _agent_context: dict = None\n) -> str:\n    \"\"\"\n    Implementation of edit_file tool with version tracking.\n\n    Finds the old_string in the file and replaces it with new_string.\n    The old_string must be unique in the file to avoid ambiguous edits.\n\n    Args:\n        file_path: Path to the file to edit\n        old_string: The exact string to find and replace\n        new_string: The string to replace it with\n        _workspace_context: Context about the workspace (for version tracking)\n        _agent_context: Context about the agent (for version tracking)\n\n    Returns:\n        Success message or error if old_string not found/not unique\n    \"\"\"\n    try:\n        path, err = _resolve_sandbox_path(file_path)\n        if err:\n            return err\n\n        if not path.exists():\n            return f\"Error: File not found: {file_path}\"\n\n        if not path.is_file():\n            return f\"Error: Path is not a file: {file_path}\"\n\n        content = path.read_text(encoding=\"utf-8\")\n\n        # Check if old_string exists and is unique\n        count = content.count(old_string)\n        if count == 0:\n            return f\"Error: String not found in file: ''{old_string[:50]}...''\"\n        if count > 1:\n            return f\"Error: String found {count} times. Must be unique for safe replacement.\"\n\n        # Perform replacement\n        new_content = content.replace(old_string, new_string, 1)\n        path.write_text(new_content, encoding=\"utf-8\")\n\n        # Phase 2: durable storage copy when STORAGE_MODE=db (no-op in local).\n        from services.workspace_manager import get_workspace_manager\n        get_workspace_manager().persist_output(path, new_content.encode(\"utf-8\"))\n\n        logger.info(f\"Edited file: {file_path}\")\n\n        # Record version for diff tracking\n        _record_file_version(\n            file_path=path,\n            operation=\"edit\",\n            content=new_content,  # Store full content after edit\n            old_string=old_string,\n            new_string=new_string,\n            workspace_context=_workspace_context,\n            agent_context=_agent_context\n        )\n\n        return f\"Successfully replaced string in {path.name}\"\n\n    except UnicodeDecodeError:\n        return f\"Error: File is not a text file or uses unsupported encoding\"\n    except Exception as e:\n        logger.error(f\"Error editing file {file_path}: {e}\")\n        return f\"Error editing file: {str(e)}\"", "args_schema": {"file_path": {"type": "string", "description": "Path to the file to edit"}, "old_string": {"type": "string", "description": "The exact string to find and replace (must be unique in file)"}, "new_string": {"type": "string", "description": "The string to replace it with"}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": "Path to the file to edit"}, "old_string": {"type": "string", "description": "The exact string to find and replace (must be unique in file)"}, "new_string": {"type": "string", "description": "The string to replace it with"}}, "required": ["file_path", "old_string", "new_string"]}', 'string', NULL, '{"category": "filesystem", "order": 6, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034569+00:00', '2026-11-11 02:00:59.919392+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'edit_file')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 48);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 218, 'gen_dashboard', 'Generate Dashboard', '用我：生成/刷新某个数据库的 HTML 仪表盘（确定性生成器，不写 HTML）。
别用我：自己手写 HTML 或做一次性图表——那用 python_execute。

Build or refresh a database dashboard by running the deterministic generator
in data/analysis_dbs/gen_<db>_dashboard.py. Returns JSON.

You MUST know the user''s choices before calling this: which pages, which
language, and anything to stress. When an option is missing the tool refuses
with status "needs_clarification" and the exact questions to ask — nothing is
rendered, so ask the user first and call again with their answers.

Args:
    database: Database name, e.g. "chinook". Empty lists what is available.
    pages: Comma-separated page ids (hub, revenue, catalog, customers), or
        "all". Empty means "not decided yet" -> clarification.
    lang: "zh" or "en". Empty means "not decided yet" -> clarification.
    top: Rows in top-N lists and pies (0 = not decided yet -> clarification).
    title: Optional custom title for the hub page.

Returns:
    JSON with status "needs_clarification" | "ok" | "error".', 'python_function', 'custom', '{"function_name": "gen_dashboard", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\n_DASHBOARD_DIR = Path(__file__).resolve().parents[2] / \"data\" / \"analysis_dbs\"\n\n_DASHBOARD_QUESTIONS = {\n    \"pages\": \"要哪些页面？（hub 总览 / revenue 营收 / catalog 曲库 / customers 客户，或全部）\",\n    \"lang\": \"语言用中文还是 English？（zh / en）\",\n    \"focus\": \"有什么要突出的？（Top-N 只取几行、自定义标题、重点国家或流派）\",\n}\n\ndef _dashboard_generators() -> dict[str, dict]:\n    \"\"\"Discover generator modules: data/analysis_dbs/gen_<db>_dashboard.py.\n\n    The module must expose GENERATOR = {...} (see gen_chinook_dashboard.py). The\n    manifest is read with ast so discovery never imports a module it only wants\n    to describe.\n    \"\"\"\n    import ast as _ast\n\n    found: dict[str, dict] = {}\n    if not _DASHBOARD_DIR.is_dir():\n        return found\n    for path in sorted(_DASHBOARD_DIR.glob(\"gen_*_dashboard.py\")):\n        try:\n            tree = _ast.parse(path.read_text(encoding=\"utf-8\"))\n        except Exception:\n            continue\n        for node in tree.body:\n            if not (isinstance(node, _ast.Assign) and any(\n                getattr(t, \"id\", \"\") == \"GENERATOR\" for t in node.targets\n            )):\n                continue\n            try:\n                manifest = _ast.literal_eval(node.value)\n            except Exception:\n                continue\n            if isinstance(manifest, dict) and manifest.get(\"database\"):\n                found[manifest[\"database\"]] = {**manifest, \"path\": str(path)}\n    return found\n\ndef gen_dashboard(\n    database: str = \"\",\n    pages: str = \"\",\n    lang: str = \"\",\n    top: int = 0,\n    title: str = \"\",\n) -> str:\n    \"\"\"\n    用我：生成/刷新某个数据库的 HTML 仪表盘（确定性生成器，不写 HTML）。\n    别用我：自己手写 HTML 或做一次性图表——那用 python_execute。\n\n    Build or refresh a database dashboard by running the deterministic generator\n    in data/analysis_dbs/gen_<db>_dashboard.py. Returns JSON.\n\n    You MUST know the user''s choices before calling this: which pages, which\n    language, and anything to stress. When an option is missing the tool refuses\n    with status \"needs_clarification\" and the exact questions to ask — nothing is\n    rendered, so ask the user first and call again with their answers.\n\n    Args:\n        database: Database name, e.g. \"chinook\". Empty lists what is available.\n        pages: Comma-separated page ids (hub, revenue, catalog, customers), or\n            \"all\". Empty means \"not decided yet\" -> clarification.\n        lang: \"zh\" or \"en\". Empty means \"not decided yet\" -> clarification.\n        top: Rows in top-N lists and pies (0 = not decided yet -> clarification).\n        title: Optional custom title for the hub page.\n\n    Returns:\n        JSON with status \"needs_clarification\" | \"ok\" | \"error\".\n    \"\"\"\n    import json as _json\n\n    gens = _dashboard_generators()\n    db = (database or \"\").strip().lower()\n    if not db:\n        return _json.dumps({\n            \"status\": \"error\",\n            \"why\": \"no database given\",\n            \"available\": sorted(gens),\n        }, ensure_ascii=False)\n    manifest = gens.get(db)\n    if manifest is None:\n        return _json.dumps({\n            \"status\": \"error\",\n            \"why\": f\"no deterministic generator for database ''{db}''\",\n            \"available\": sorted(gens),\n            \"hint\": \"add data/analysis_dbs/gen_<db>_dashboard.py exporting GENERATOR = {...}\",\n        }, ensure_ascii=False)\n\n    valid_pages = list(manifest.get(\"pages\") or {})\n    pages_arg = (pages or \"\").strip().lower()\n    if pages_arg == \"all\":\n        wanted = list(valid_pages)\n    else:\n        wanted = [p.strip() for p in pages_arg.split(\",\") if p.strip()]\n    if wanted:\n        unknown = [p for p in wanted if p not in valid_pages]\n        if unknown:\n            return _json.dumps({\n                \"status\": \"error\",\n                \"why\": f\"unknown page(s): {unknown}\",\n                \"valid_pages\": valid_pages,\n                \"page_meaning\": manifest.get(\"pages\"),\n            }, ensure_ascii=False)\n\n    langs = list((manifest.get(\"options\") or {}).get(\"lang\") or [\"zh\", \"en\"])\n    lang_arg = (lang or \"\").strip().lower()\n\n    # ── The clarification gate ──────────────────────────────────────────────\n    # Any undecided option stops the call. The agent cannot render its way past\n    # a missing decision, which is the whole point of having the tool rather\n    # than a prompt instruction.\n    missing = []\n    if not wanted:\n        missing.append(\"pages\")\n    if not lang_arg:\n        missing.append(\"lang\")\n    if not top:\n        missing.append(\"focus\")\n    if missing:\n        return _json.dumps({\n            \"status\": \"needs_clarification\",\n            \"database\": db,\n            \"ask\": [_DASHBOARD_QUESTIONS[m] for m in missing],\n            \"valid_pages\": valid_pages,\n            \"page_meaning\": manifest.get(\"pages\"),\n            \"valid_lang\": langs,\n            \"defaults\": manifest.get(\"defaults\"),\n            \"note\": \"Nothing was generated. Ask the user, then call again with their answers.\",\n        }, ensure_ascii=False)\n\n    if lang_arg not in langs:\n        return _json.dumps({\n            \"status\": \"error\",\n            \"why\": f\"unsupported lang ''{lang_arg}''\",\n            \"valid_lang\": langs,\n        }, ensure_ascii=False)\n\n    lo, hi = (manifest.get(\"options\") or {}).get(\"top\") or (3, 100)\n    top_val = max(int(lo), min(int(hi), int(top)))\n\n    # ── Run the generator in-process ────────────────────────────────────────\n    import importlib.util\n\n    path = Path(manifest[\"path\"])\n    spec = importlib.util.spec_from_file_location(f\"gen_dashboard_{db}\", path)\n    if spec is None or spec.loader is None:\n        return _json.dumps({\"status\": \"error\", \"why\": f\"cannot load {path}\"}, ensure_ascii=False)\n    module = importlib.util.module_from_spec(spec)\n    try:\n        spec.loader.exec_module(module)\n        conn = module.connect(db)\n        try:\n            data = module.collect(conn)\n        finally:\n            conn.close()\n        written = module.build(_DASHBOARD_DIR, data, wanted, lang_arg, top_val, title or None)\n        gate = module.check(written, data, wanted)\n    except Exception as exc:  # noqa: BLE001 — surface the real reason to the model\n        return _json.dumps({\n            \"status\": \"error\",\n            \"why\": f\"{type(exc).__name__}: {exc}\",\n            \"generator\": str(path),\n        }, ensure_ascii=False)\n\n    # Record who owns these pages: the Analysis activity lists per account, so a\n    # page without an owner is shared with everyone (see services/dashboard_owners).\n    try:\n        from services.user_roots import subject_user_id\n        from services.dashboard_owners import record_many\n\n        record_many([p.name for p in written], subject_user_id())\n    except Exception:  # noqa: BLE001 — bookkeeping must not fail the render\n        pass\n\n    if gate != 0:\n        return _json.dumps({\n            \"status\": \"error\",\n            \"why\": \"generator gate failed — numbers in the HTML do not match the database\",\n            \"files\": [p.name for p in written],\n            \"generator\": str(path),\n        }, ensure_ascii=False)\n\n    return _json.dumps({\n        \"status\": \"ok\",\n        \"database\": db,\n        \"pages\": wanted,\n        \"lang\": lang_arg,\n        \"top\": top_val,\n        \"title\": title or None,\n        \"files\": [p.name for p in written],\n        \"urls\": [f\"/api/files/{p.name}\" for p in written],\n        \"gate\": \"PASS\",\n        \"summary\": (\n            f\"revenue {data[''revenue_total'']:,.2f} \"\n            f\"(USA {data[''revenue_usa'']:,.2f}, ARPU {data[''arpu_usa'']:,.2f}) · \"\n            f\"{data[''invoices'']} invoices · \"\n            f\"{data[''tracks_sold'']:,}/{data[''tracks'']:,} tracks sold · \"\n            f\"{len(data[''monthly''])} months\"\n        ),\n        \"where\": \"Analysis activity lists these first (newest first)\",\n        \"note\": \"Report both revenue readings: the pages show all-invoice and USA-only side by side.\",\n    }, ensure_ascii=False)", "args_schema": {"database": {"type": "string", "description": "", "default": ""}, "pages": {"type": "string", "description": "", "default": ""}, "lang": {"type": "string", "description": "", "default": ""}, "top": {"type": "integer", "description": "", "default": 0}, "title": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"database": {"type": "string", "description": "", "default": ""}, "pages": {"type": "string", "description": "", "default": ""}, "lang": {"type": "string", "description": "", "default": ""}, "top": {"type": "integer", "description": "", "default": 0}, "title": {"type": "string", "description": "", "default": ""}}, "required": []}', 'string', NULL, '{"category": "analysis", "order": 17, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'data_analysis', TRUE, NULL, '["builtin", "data_analysis"]', '2026-11-03 14:53:14.015035+00:00', '2026-11-11 01:12:26.335668+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'gen_dashboard')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 218);

