SELECT 247, 'list_files', 'List Files (workspace directory)', '用我：看工作区里有什么——列目录（文件 + 子目录 + 大小）。找用户刚上传的文件就用它。
别用我：找文件内容里的字符串用 grep；读文件内容用 read_file / read_any_file。

List the files in a workspace directory, newest first.

Why this exists: the deepagents filesystem toolset is provided by the SDK for the agent''s
backend, and an agent whose backend is `state` had no directory listing at all — asked to
find its uploaded workbook, it answered 「我没有列目录的工具」 and guessed names for a dozen
turns. This tool is deliberately named `list_files` (not `ls`) so the platform''s
"drop native fs tools when a disk backend is active" rule cannot remove it.

Args:
    path: directory inside the workspace (default: the workspace root; "upload" works)
    pattern: glob filter for names, e.g. "*.xlsx" (default: everything)

Returns:
    One line per entry (`<name>` and size, directories marked), plus the resolved directory.', 'python_function', 'custom', '{"function_name": "list_files", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef list_files(path: str = \"\", pattern: str = \"*\") -> str:\n    \"\"\"\n    用我：看工作区里有什么——列目录（文件 + 子目录 + 大小）。找用户刚上传的文件就用它。\n    别用我：找文件内容里的字符串用 grep；读文件内容用 read_file / read_any_file。\n\n    List the files in a workspace directory, newest first.\n\n    Why this exists: the deepagents filesystem toolset is provided by the SDK for the agent''s\n    backend, and an agent whose backend is `state` had no directory listing at all — asked to\n    find its uploaded workbook, it answered 「我没有列目录的工具」 and guessed names for a dozen\n    turns. This tool is deliberately named `list_files` (not `ls`) so the platform''s\n    \"drop native fs tools when a disk backend is active\" rule cannot remove it.\n\n    Args:\n        path: directory inside the workspace (default: the workspace root; \"upload\" works)\n        pattern: glob filter for names, e.g. \"*.xlsx\" (default: everything)\n\n    Returns:\n        One line per entry (`<name>` and size, directories marked), plus the resolved directory.\n    \"\"\"\n    import fnmatch\n    from pathlib import Path as _P\n\n    target, error = _resolve_agent_file(path or \".\")\n    if error:\n        return error\n    if not target.is_dir():\n        return f\"Error: {path or ''.''} is not a directory (resolved to {target})\"\n    try:\n        entries = sorted(target.iterdir(), key=lambda e: e.stat().st_mtime, reverse=True)\n    except OSError as exc:\n        return f\"Error: cannot list {target}: {exc}\"\n\n    lines = [f\"Directory: {target}\"]\n    shown = 0\n    for entry in entries:\n        if not fnmatch.fnmatch(entry.name, pattern):\n            continue\n        try:\n            size = entry.stat().st_size\n        except OSError:\n            size = 0\n        if entry.is_dir():\n            lines.append(f\"  {entry.name}/\")\n        else:\n            lines.append(f\"  {entry.name}  ({size:,} bytes)\")\n        shown += 1\n        if shown >= 200:\n            lines.append(\"  … (truncated at 200 entries)\")\n            break\n    if shown == 0:\n        lines.append(f\"  (empty{'' for pattern '' + pattern if pattern != ''*'' else ''''})\")\n    return \"\\n\".join(lines)\n\ndef _resolve_agent_file(value: str):\n    \"\"\"(path, error) for a spreadsheet argument: sandbox-checked, and relative to the run workspace.\n\n    Two things a plain `Path(value).resolve()` gets wrong here: a RELATIVE path resolves against\n    the server''s cwd (`backend/`) so an agent cannot open `upload/orders.xlsx`, and an ABSOLUTE\n    path outside the sandbox (`/etc/passwd`) was accepted. The first is why the table-building\n    agent could not read its own upload; the second is why that argument needed a sandbox.\n    \"\"\"\n    if not Path(value).expanduser().is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / Path(value).expanduser()).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n        looked = \", \".join(str(r) for r in _sandbox_roots()[:2])\n        return None, f\"Error: no such file: {value} (looked under {looked})\"\n    resolved, error = _resolve_sandbox_path(value)\n    if error:\n        return None, error\n    return resolved, None", "args_schema": {"path": {"type": "string", "description": "", "default": ""}, "pattern": {"type": "string", "description": "", "default": "*"}}}', '{"type": "object", "properties": {"path": {"type": "string", "description": "", "default": ""}, "pattern": {"type": "string", "description": "", "default": "*"}}, "required": []}', 'string', NULL, '{"category": "filesystem", "order": 63, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-11-11 02:00:59.934358+00:00', '2026-11-11 02:00:59.934365+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'list_files')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 247);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 45, 'ls', 'List Directory', 'List directory contents with metadata.

Shows files and directories with their types and sizes.

Args:
    directory_path: Path to the directory (default: current directory)

Returns:
    Formatted list of directory contents with metadata

Example:
    >>> ls()
    >>> ls("/home/user/projects")', 'python_function', 'custom', '{"function_name": "ls", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef ls(directory_path: str = \".\") -> str:\n    \"\"\"\n    List directory contents with metadata.\n\n    Shows files and directories with their types and sizes.\n\n    Args:\n        directory_path: Path to the directory (default: current directory)\n\n    Returns:\n        Formatted list of directory contents with metadata\n\n    Example:\n        >>> ls()\n        >>> ls(\"/home/user/projects\")\n    \"\"\"\n    try:\n        path, err = _resolve_sandbox_path(directory_path)\n        if err:\n            return err\n\n        if not path.exists():\n            return f\"Error: Directory not found: {directory_path}\"\n\n        if not path.is_dir():\n            return f\"Error: Path is not a directory: {directory_path}\"\n\n        entries = list(path.iterdir())\n\n        if not entries:\n            return f\"Empty directory: {directory_path}\"\n\n        # Format with metadata\n        lines = []\n        for entry in sorted(entries, key=lambda x: (not x.is_dir(), x.name.lower())):\n            if entry.is_dir():\n                lines.append(f\"[DIR]  {entry.name}/\")\n            else:\n                size = entry.stat().st_size\n                if size < 1024:\n                    size_str = f\"{size}B\"\n                elif size < 1024 * 1024:\n                    size_str = f\"{size / 1024:.1f}KB\"\n                else:\n                    size_str = f\"{size / (1024 * 1024):.1f}MB\"\n                lines.append(f\"[FILE] {entry.name} ({size_str})\")\n\n        logger.info(f\"Listed {len(entries)} entries in {directory_path}\")\n        return \"\\n\".join(lines)\n\n    except Exception as e:\n        logger.error(f\"Error listing directory {directory_path}: {e}\")\n        return f\"Error listing directory: {str(e)}\"", "args_schema": {"directory_path": {"type": "string", "description": "", "default": "."}}}', '{"type": "object", "properties": {"directory_path": {"type": "string", "description": "", "default": "."}}, "required": []}', 'string', NULL, '{"category": "filesystem", "order": 3, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034563+00:00', '2026-11-11 02:00:59.919387+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'ls')
