SELECT 72, 'neo4j_get_doc', 'Neo4j - Get Document Metadata', 'Get full metadata for one Document node from Neo4j by project_id and name.

Returns enriched metadata: description, supported queries, file path, tags, etc.
Use the returned file_path with read_file to get the actual document content.

Args:
    project_id: Project ID
    name: Document name in Neo4j (use neo4j_list_docs to find names)

Returns:
    Complete document metadata

Example:
    >>> neo4j_get_doc(project_id=1, name="cfd711e3_report.pdf")', 'python_function', 'custom', '{"function_name": "neo4j_get_doc", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_get_doc(project_id: int, name: str) -> str:\n    \"\"\"\n    Get full metadata for one Document node from Neo4j by project_id and name.\n\n    Returns enriched metadata: description, supported queries, file path, tags, etc.\n    Use the returned file_path with read_file to get the actual document content.\n\n    Args:\n        project_id: Project ID\n        name: Document name in Neo4j (use neo4j_list_docs to find names)\n\n    Returns:\n        Complete document metadata\n\n    Example:\n        >>> neo4j_get_doc(project_id=1, name=\"cfd711e3_report.pdf\")\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        doc = idx.get_document(project_id, name)\n        if not doc:\n            return f\"❌ Document ''{name}'' not found in Neo4j for project_id={project_id}.\"\n        lines = [\n            f\"## Document: {doc.doc_name}\",\n            f\"**Name**: `{doc.name}`\",\n            f\"**File Path**: `{doc.file_path}`\",\n            f\"**Context Doc ID**: {doc.context_doc_id}\",\n            f\"**Doc Index ID**: {doc.doc_index_id or ''(not set)''}\",\n            f\"**Page Count**: {doc.page_count}\",\n            f\"**Description**: {doc.description or ''(none)''}\",\n            \"\",\n            \"### What this document is about\",\n            doc.what_this_document_is_about or \"(no enrichment)\",\n            \"\",\n            \"### Supported Queries\",\n        ]\n        if doc.supported_queries:\n            for q in doc.supported_queries:\n                lines.append(f\"- {q}\")\n        else:\n            lines.append(\"(none)\")\n        lines.append(\"\")\n        lines.append(\"### Tags\")\n        lines.append(f\"{'', ''.join(doc.tags) if doc.tags else ''(none)''}\")\n        lines.append(\"\")\n        lines.append(\"### File Path (for read_file)\")\n        lines.append(f\"`{doc.file_path}`\")\n        lines.append(\"\")\n        lines.append(\"*Use `read_file` with the file path above to get the full document content.*\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error getting Neo4j document: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}}, "required": ["project_id", "name"]}', 'string', NULL, '{"category": "graph", "order": 46, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034615+00:00', '2026-11-11 01:12:26.319865+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_get_doc')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 72);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 71, 'neo4j_list_docs', 'Neo4j - List Documents', 'List all Document nodes in Neo4j for a project with their metadata.

Neo4j stores document routing metadata (summary, supported queries, tags, file path).
Use this to discover what documents are indexed before searching.

Args:
    project_id: Project ID to list documents for

Returns:
    Formatted list of documents with enriched metadata

Example:
    >>> neo4j_list_docs(project_id=1)', 'python_function', 'custom', '{"function_name": "neo4j_list_docs", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_list_docs(project_id: int) -> str:\n    \"\"\"\n    List all Document nodes in Neo4j for a project with their metadata.\n\n    Neo4j stores document routing metadata (summary, supported queries, tags, file path).\n    Use this to discover what documents are indexed before searching.\n\n    Args:\n        project_id: Project ID to list documents for\n\n    Returns:\n        Formatted list of documents with enriched metadata\n\n    Example:\n        >>> neo4j_list_docs(project_id=1)\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        docs = idx.list_documents(project_id)\n        if not docs:\n            return f\"No documents indexed in Neo4j for project_id={project_id}.\"\n        lines = [f\"## Neo4j Documents (project {project_id}, {len(docs)} total)\", \"\"]\n        for d in docs:\n            q_count = len(d.supported_queries or [])\n            lines.append(\n                f\"- **{d.doc_name}** (`{d.name}`)  \"\n                f\"pages={d.page_count}  \"\n                f\"queries={q_count}\"\n            )\n            about = d.what_this_document_is_about or d.description or \"\"\n            if about:\n                lines.append(f\"  {about[:200]}\")\n            if d.file_path:\n                lines.append(f\"  path: `{d.file_path}`\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing Neo4j documents: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": ""}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": ""}}, "required": ["project_id"]}', 'string', NULL, '{"category": "graph", "order": 45, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034613+00:00', '2026-11-11 01:12:26.319864+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_list_docs')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 71);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 73, 'neo4j_query', 'Neo4j - Cypher Query', 'Run an arbitrary Cypher query against Neo4j and return results.

Use this for custom graph queries beyond the built-in document tools.
The query runs against the document index Neo4j database.

Args:
    cypher: The Cypher query string (e.g. ''MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count'')
    parameters: Optional dict of query parameters (e.g. {"pid": 1})

Returns:
    Query results as formatted text

Example:
    >>> neo4j_query("MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count ORDER BY d.page_count DESC LIMIT 5", {"pid": 1})', 'python_function', 'custom', '{"function_name": "neo4j_query", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_query(cypher: str, parameters: dict | None = None) -> str:\n    \"\"\"\n    Run an arbitrary Cypher query against Neo4j and return results.\n\n    Use this for custom graph queries beyond the built-in document tools.\n    The query runs against the document index Neo4j database.\n\n    Args:\n        cypher: The Cypher query string (e.g. ''MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count'')\n        parameters: Optional dict of query parameters (e.g. {\"pid\": 1})\n\n    Returns:\n        Query results as formatted text\n\n    Example:\n        >>> neo4j_query(\"MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count ORDER BY d.page_count DESC LIMIT 5\", {\"pid\": 1})\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        rows = idx._run_cypher(cypher, parameters or {})\n        if not rows:\n            return \"Query returned no results.\"\n        col_names = list(rows[0].keys())\n        lines = [\"## Cypher Results\", \"\"]\n        lines.append(\"| \" + \" | \".join(col_names) + \" |\")\n        lines.append(\"| \" + \" | \".join(\"---\" for _ in col_names) + \" |\")\n        for row in rows:\n            vals = []\n            for c in col_names:\n                v = row.get(c)\n                s = str(v) if v is not None else \"NULL\"\n                if len(s) > 200:\n                    s = s[:200] + \"…\"\n                vals.append(s)\n            lines.append(\"| \" + \" | \".join(vals) + \" |\")\n        lines.append(f\"\\n*{len(rows)} row(s) returned*\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Cypher error: {e}\"", "args_schema": {"cypher": {"type": "string", "description": ""}, "parameters": {"type": "object", "description": "", "default": null}}}', '{"type": "object", "properties": {"cypher": {"type": "string", "description": ""}, "parameters": {"type": "object", "description": "", "default": null}}, "required": ["cypher"]}', 'string', NULL, '{"category": "graph", "order": 47, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034617+00:00', '2026-11-11 01:12:26.319865+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_query')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 73);

