SELECT 74, 'neo4j_upsert_doc', 'Neo4j - Upsert Document', 'Create or update a Document node in Neo4j.

Registers a document in the graph index so it becomes discoverable
via graphindex_search / neo4j_list_docs. The actual file content
should already exist on disk at file_path.

Args:
    project_id: Project ID this document belongs to
    name: Unique document name (e.g. hash-prefixed filename)
    file_path: Absolute path to the document on disk
    description: Short description of what this document is
    tags: List of categorization tags
    doc_name: Optional display name (defaults to name)

Returns:
    Confirmation message

Example:
    >>> neo4j_upsert_doc(project_id=1, name="my_report.pdf", file_path="/data/my_report.pdf", description="Q3 financial analysis", tags=["finance", "quarterly"])', 'python_function', 'custom', '{"function_name": "neo4j_upsert_doc", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_upsert_doc(project_id: int, name: str, file_path: str,\n                     description: str = \"\",\n                     tags: list[str] | None = None,\n                     doc_name: str | None = None) -> str:\n    \"\"\"\n    Create or update a Document node in Neo4j.\n\n    Registers a document in the graph index so it becomes discoverable\n    via graphindex_search / neo4j_list_docs. The actual file content\n    should already exist on disk at file_path.\n\n    Args:\n        project_id: Project ID this document belongs to\n        name: Unique document name (e.g. hash-prefixed filename)\n        file_path: Absolute path to the document on disk\n        description: Short description of what this document is\n        tags: List of categorization tags\n        doc_name: Optional display name (defaults to name)\n\n    Returns:\n        Confirmation message\n\n    Example:\n        >>> neo4j_upsert_doc(project_id=1, name=\"my_report.pdf\", file_path=\"/data/my_report.pdf\", description=\"Q3 financial analysis\", tags=[\"finance\", \"quarterly\"])\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        from services.neo4j_document_index import build_document_node_properties\n        props = build_document_node_properties(\n            project_id=project_id,\n            context_doc_id=0,\n            doc_index_id=None,\n            name=name,\n            file_path=file_path,\n            description=description,\n            tags=tags or [],\n        )\n        if doc_name:\n            props[\"doc_name\"] = doc_name\n        idx.upsert_document(project_id, name, file_path, properties=props)\n        display = doc_name or name\n        return f\"✅ Document ''{display}'' upserted in Neo4j for project {project_id}.\"\n    except Exception as e:\n        return f\"❌ Error upserting document: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}, "file_path": {"type": "string", "description": ""}, "description": {"type": "string", "description": "", "default": ""}, "tags": {"type": "array", "description": "", "default": null}, "doc_name": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}, "file_path": {"type": "string", "description": ""}, "description": {"type": "string", "description": "", "default": ""}, "tags": {"type": "array", "description": "", "default": null}, "doc_name": {"type": "string", "description": "", "default": null}}, "required": ["project_id", "name", "file_path"]}', 'string', NULL, '{"category": "graph", "order": 48, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034619+00:00', '2026-11-11 01:12:26.319866+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_upsert_doc')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 74);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 227, 'ontology_ask', 'Ontology Ask (business question → number or refusal)', 'Ask an ontology a business question and get the number, or a refusal BY NAME. Runs the ontology''s own Query pipeline (menu → rules-first intent → validate → compile → guardrails → verified prose): the words are matched to a declared metric/class/action, the ontology''s compiler builds the SQL, and no SQL is ever typed by a model. Returns the value (or grouped rows), the definition it came from, the compiled SQL and the guard''s notes; a question the ontology cannot answer comes back as a refusal naming the missing declaration; a question with a period/customer comes back as needs_confirmation with the understanding (re-ask with confirm=true). Use this for every numeric question instead of writing a query.', 'python_function', 'custom', '{"function_name": "ontology_ask", "code": "# --- imports ---\nimport json as _json\nimport os as _os\nimport pathlib as _pl\nimport subprocess as _sp\n\n_CHILD = r\"\"\"\nimport json, os, pathlib, sys\nsys.path.insert(0, os.environ[\"ONTOLOGY_COMPILER\"])\nimport nl\n\npayload = json.loads(sys.argv[1])\ntry:\n    out = nl.ask(payload[\"question\"], confirm=bool(payload.get(\"confirm\")), record=True)\n    print(json.dumps({\"ok\": True, **{k: out.get(k) for k in\n        (\"intent\", \"result\", \"answer\", \"answer_source\", \"steps\", \"needs_confirmation\",\n         \"understanding\", \"total_ms\")}}, ensure_ascii=False, default=str))\nexcept nl.NlRefusal as exc:\n    print(json.dumps({\"ok\": False, \"refused\": str(exc),\n                      \"text\": getattr(exc, \"polished\", None) or str(exc)}, ensure_ascii=False))\nexcept Exception as exc:\n    print(json.dumps({\"ok\": False, \"error\": \"%s: %s\" % (type(exc).__name__, exc)}, ensure_ascii=False))\n\"\"\"\n\n\ndef _repo():\n    \"\"\"The app''s ontology FEATURE: the compiler, the profiles and the gates live in this repository.\"\"\"\n    from services import ontology_publish\n    return _pl.Path(ontology_publish.FEATURE)\n\n\ndef _python():\n    from services import ontology_publish\n    return ontology_publish.PYTHON\n\n\ndef _profile_for(repo, key):\n    \"\"\"One ontology is one folder in the feature''s profiles/: `<key>/<key>_settings.json`.\"\"\"\n    for candidate in (repo / \"profiles\" / key / (key + \"_settings.json\"),\n                      repo / \"profiles\" / key / \"settings.json\"):\n        if candidate.is_file():\n            return candidate\n    return None\n\n\ndef _installed(repo):\n    \"\"\"The ontologies this app ships: every folder under the feature''s profiles/.\"\"\"\n    try:\n        return sorted(p.name for p in (repo / \"profiles\").iterdir()\n                      if p.is_dir() and not p.name.startswith(\".\"))\n    except OSError:\n        return []\n\n\ndef ontology_ask(question: str, ontology_key: str = \"logistics\", confirm: bool = False,\n                 polish: bool = True) -> str:\n    \"\"\"Ask an ontology a business question and get the number, or the refusal BY NAME.\n\n    Use me for EVERY question that needs a number from a database covered by an ontology. I run the\n    ontology''s own pipeline (the one its Query page serves): the words are matched to a declared\n    metric/class/action (rules first, a model only when unsure), the ontology''s compiler builds the SQL,\n    the guardrails bound it, and the answer is written as prose about that number. I never type SQL and\n    never compute.\n\n    Arguments:\n      question       the user''s words, verbatim — do not clean them up first; the words are the evidence\n      ontology_key   which ontology answers (default logistics); any folder name under profiles/ works\n      confirm        a question that states a period or a customer comes back as `needs_confirmation`\n                     with the understanding; call again with confirm=true to run it\n      polish         false = the deterministic template writes the prose (faster, no model)\n\n    What you get back is one of three things, and all three are useful:\n      * the number, the definition it came from and the compiled SQL (so it can be quoted);\n      * a REFUSAL that names the declaration which is missing — report it; do not invent a number;\n      * `needs_confirmation` with the understanding — show it to the user and ask before running.\n    \"\"\"\n    text = (question or \"\").strip()\n    if not text:\n        return \"ERROR: ask a question; an empty one has no answer.\"\n    key = (ontology_key or \"logistics\").strip()\n    repo = _repo()\n    profile = _profile_for(repo, key)\n    if profile is None:\n        return (\"ERROR: no ontology %r — available: %s\"\n                % (key, \", \".join(_installed(repo)) or \"(none)\"))\n\n    env = dict(_os.environ)\n    env[\"APP_SETTINGS\"] = str(profile)\n    env[\"ONTOLOGY_COMPILER\"] = str(repo / \"compiler\")\n    env[\"NL_ANSWER_LLM\"] = \"1\" if polish else \"0\"\n    try:\n        p = _sp.run([_python(), \"-c\", _CHILD, _json.dumps({\"question\": text, \"confirm\": bool(confirm)})],\n                    capture_output=True, text=True, timeout=300,\n                    cwd=str(repo / \"compiler\"), env=env)\n    except Exception as exc:\n        return \"ERROR: the pipeline did not run (%s: %s)\" % (type(exc).__name__, exc)\n\n    lines = (p.stdout or \"\").strip().splitlines()\n    if not lines:\n        tail = (p.stderr or \"\").strip().splitlines()\n        return (\"ERROR: the pipeline printed nothing%s\"\n                % (\": \" + tail[-1] if tail else \" (exit %s)\" % p.returncode))\n    try:\n        data = _json.loads(lines[-1])\n    except Exception:\n        return \"ERROR: the pipeline''s answer was not JSON: %s\" % lines[-1][:400]\n\n    head = \"ontology %s  ·  question: %s\" % (key, text)\n    if data.get(\"error\"):\n        return head + \"\\n\\nERROR: \" + str(data[\"error\"])\n    if not data.get(\"ok\"):\n        return (head + \"\\n\\nREFUSED (this is the answer, not a failure — it names what is missing):\\n  \"\n                + str(data.get(\"text\") or data.get(\"refused\")))\n\n    intent = data.get(\"intent\") or {}\n    result = data.get(\"result\") or {}\n    body = []\n    body.append(\"intent: %s %s%s\" % (intent.get(\"kind\"), intent.get(\"name\"),\n                                     (\" slots=\" + _json.dumps(intent.get(\"slots\"), ensure_ascii=False))\n                                     if intent.get(\"slots\") else \"\"))\n    if data.get(\"needs_confirmation\"):\n        understanding = (data.get(\"understanding\") or {}).get(\"text\")\n        body.append(\"\")\n        body.append(\"NEEDS CONFIRMATION — the question states a constraint; this is how it was understood:\")\n        body.append(\"  \" + (understanding or \"(no echo)\"))\n        body.append(\"  Re-ask with confirm=true to run it.\")\n        return head + \"\\n\\n\" + \"\\n\".join(body)\n    rows = result.get(\"rows\")\n    if rows:\n        body.append(\"rows (%d):\" % len(rows))\n        for row in rows[:20]:\n            if isinstance(row, dict):\n                body.append(\"  %s = %s\" % (row.get(\"key\"), row.get(\"value\")))\n            else:\n                body.append(\"  \" + \" / \".join(str(c) for c in row))\n        if len(rows) > 20:\n            body.append(\"  … %d more\" % (len(rows) - 20))\n    else:\n        body.append(\"value: %s\" % result.get(\"value\"))\n    if result.get(\"sql\"):\n        body.append(\"\")\n        body.append(\"compiled SQL (from the declarations, not typed by anyone):\")\n        body.append(\"  \" + str(result[\"sql\"]).replace(\"\\n\", \" \").strip())\n    for note in result.get(\"notes\") or []:\n        body.append(\"guard: \" + str(note))\n    body.append(\"\")\n    body.append(\"answer (%s):\" % data.get(\"answer_source\"))\n    body.append(\"  \" + str(data.get(\"answer\") or \"\").replace(\"\\n\", \"\\n  \"))\n    steps = data.get(\"steps\") or []\n    if steps:\n        body.append(\"\")\n        body.append(\"trace: \" + \" · \".join(\"%s %sms\" % (s.get(\"step\"), s.get(\"ms\")) for s in steps))\n    return head + \"\\n\\n\" + \"\\n\".join(body)\n", "args_schema": {"question": {"type": "string", "description": "The user''s words, verbatim."}, "ontology_key": {"type": "string", "description": "Which ontology answers (default logistics).", "default": "logistics"}, "confirm": {"type": "boolean", "description": "Run a slot question after confirming it.", "default": false}, "polish": {"type": "boolean", "description": "false = deterministic prose.", "default": true}}}', '{"type": "object", "properties": {"question": {"type": "string", "description": "The user''s words, verbatim."}, "ontology_key": {"type": "string", "description": "Which ontology answers (default logistics).", "default": "logistics"}, "confirm": {"type": "boolean", "description": "Run a question that states a period/customer (after showing the understanding).", "default": false}, "polish": {"type": "boolean", "description": "false = deterministic prose, no model (faster).", "default": true}}, "required": ["question"]}', 'string', NULL, '{"category": "ontology", "order": 4, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'ontology', TRUE, 'false', '["ontology", "query", "natural-language", "answer"]', '2026-11-07 02:54:16.803272+00:00', '2026-11-11 08:26:10.205671+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'ontology_ask')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 227);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 225, 'ontology_inspect', 'Ontology Inspect (ask the compiler)', 'Ask the compiler about an ontology instead of reading its source: list every metric and every refusal by name, or inspect ONE metric (the declaration it compiles from, the compiled SQL, the number under the guardrails, the plan estimate and the guard''s notes — or the compiler''s refusal sentence), or ask what a user question resolves to. Runs the real compiler, guardrails and NL pipeline under the profile''s venv. Pass source_dir=''work/<key>'' to inspect a workspace copy, so before/after an edit is two calls. Use this instead of opening sqlgen.py / nl.py: the answer you need is three facts away, and reading the engine costs a context window.', 'python_function', 'custom', '{"function_name": "ontology_inspect", "code": "# --- imports ---\nimport json as _json\nimport os as _os\nimport pathlib as _pl\nimport subprocess as _sp\nimport sys as _sys\n\n# The child runs the ontology repo''s own compiler/guardrails/NL, under the venv that has\n# psycopg2 + rdflib. Keep this script here (not in the repo) so the tool carries its own contract.\n_CHILD = r\"\"\"\nimport json, os, pathlib, sys\nsys.path.insert(0, os.environ[\"ONTOLOGY_COMPILER\"])\npayload = json.loads(sys.argv[1])\nimport sqlgen, guard, nl, actions\n\ng = sqlgen.load()\nmode = payload.get(\"mode\") or \"list\"\nout = {\"ok\": True, \"mode\": mode}\nnames = sorted(sqlgen.metrics(g))\nrefused = []\nfor name in names:\n    try:\n        sqlgen.compile_metric(g, name)\n    except Exception as exc:\n        refused.append({\"name\": name, \"why\": str(exc).splitlines()[0]})\ncompiled = [n for n in names if n not in {r[\"name\"] for r in refused}]\nout[\"metrics\"] = compiled\nout[\"refused\"] = refused\n\nif mode == \"metric\":\n    name = payload[\"name\"]\n    if name not in names:\n        out[\"ok\"] = False\n        out[\"error\"] = name + \" is not a declared metric\"\n        out[\"near\"] = [n for n in names if name.lower() in n.lower()][:10]\n    else:\n        try:\n            c = sqlgen.compile_metric(g, name)\n            out[\"sql\"] = c.sql\n            out[\"notes\"] = c.notes\n            import psycopg2\n            conn = psycopg2.connect(**actions.DSN)\n            conn.autocommit = True\n            cfg = guard.config()\n            # the PROFILE''s limits, not the defaults: a tool that reports a 1000-row page cap while\n            # the profile says 500 would make every \"the guard is on\" claim wrong\n            prof = json.loads(pathlib.Path(os.environ[\"APP_SETTINGS\"]).read_text())\n            if isinstance(prof.get(\"guard\"), dict):\n                cfg.update({k: v for k, v in prof[\"guard\"].items() if v is not None})\n            with conn.cursor() as cur:\n                r = guard.run(cur, c.sql, cfg=cfg, mode=\"declared\")\n                rows = r.get(\"rows\") or []\n                out[\"value\"] = str(rows[0][0]) if rows and rows[0] else None\n                out[\"plan_rows\"] = r.get(\"plan_rows\")\n                out[\"guard_notes\"] = r.get(\"notes\") or []\n            conn.close()\n        except Exception as exc:\n            out[\"ok\"] = False\n            out[\"refused\"] = str(exc).splitlines()[0]\n\nif mode == \"question\":\n    try:\n        res = nl.ask(payload[\"question\"], record=False)\n        out[\"intent\"] = res.get(\"intent\")\n        out[\"value\"] = str((res.get(\"result\") or {}).get(\"value\"))\n        out[\"answer\"] = res.get(\"answer\") or \"\"\n    except Exception as exc:\n        out[\"ok\"] = False\n        out[\"refused\"] = str(exc)[:800]\n\nprint(json.dumps(out, ensure_ascii=False))\n\"\"\"\n\n\ndef _profile(folder):\n    folder = _pl.Path(folder)\n    for pat in (\"*_settings.json\", \"settings.json\"):\n        found = sorted(folder.glob(pat))\n        if found:\n            return found[0]\n    return None\n\n\ndef _repo_root():\n    # The ontology feature root (it holds profiles/ and compiler/). `REPO` was the old\n    # outside-the-app mirror and no longer exists — measured as\n    # \"module ''services.ontology_publish'' has no attribute ''REPO''\" on every ontology_inspect call,\n    # which left the builder without a compiled/refused list and counting TTL by hand.\n    from services import ontology_publish\n    return _pl.Path(ontology_publish.FEATURE)\n\n\ndef _python():\n    from services import ontology_publish\n    return ontology_publish.PYTHON\n\n\ndef ontology_inspect(ontology_key: str, metric: str = \"\", question: str = \"\",\n                     source_dir: str = \"\") -> str:\n    \"\"\"Ask the compiler about an ontology — instead of reading its source.\n\n    Use me before you change a declaration and after, and instead of opening sqlgen.py / nl.py:\n    the answers below are produced by running the real compiler, the real guardrails and the real\n    NL pipeline against the profile.\n\n    Arguments:\n      ontology_key  the folder name under features/ontology/profiles/, e.g. \"logistics\".\n      metric        one metric: its compiled SQL, its value under the guardrails, the plan estimate\n                    and the guard''s notes — or the compiler''s refusal sentence. Empty = list.\n      question      a user question: what it resolves to and the number (or the refusal, verbatim).\n      source_dir    inspect a COPY instead of the installed ontology (e.g. \"work/logistics\"),\n                    so before/after is two calls. Relative paths resolve against your workspace.\n    \"\"\"\n    key = (ontology_key or \"\").strip()\n    if not key or \"/\" in key or key.startswith(\".\"):\n        return \"ERROR: ontology_key must be a folder name under profiles/, e.g. ''logistics''.\"\n\n    repo = _repo_root()\n    if source_dir and source_dir.strip():\n        folder = _pl.Path(source_dir).expanduser()\n        if not folder.is_absolute():\n            try:\n                from services.user_roots import current_root\n                folder = _pl.Path(current_root()) / folder\n            except Exception:\n                pass\n    else:\n        folder = repo / \"profiles\" / key\n        if not folder.is_dir():\n            try:\n                available = sorted(p.name for p in (repo / \"profiles\").iterdir()\n                                   if p.is_dir() and not p.name.startswith(\".\"))\n            except Exception:\n                available = []\n            return (\"ERROR: no installed ontology %r. Available: %s\"\n                    % (key, \", \".join(available) or \"(none)\"))\n\n    profile = _profile(folder)\n    if profile is None:\n        return (\"ERROR: no *_settings.json in %s — that folder is not an ontology profile\"\n                % folder)\n\n    mode = \"question\" if question.strip() else (\"metric\" if metric.strip() else \"list\")\n    payload = {\"mode\": mode}\n    if mode == \"metric\":\n        payload[\"name\"] = metric.strip()\n    if mode == \"question\":\n        payload[\"question\"] = question.strip()\n\n    env = dict(_os.environ)\n    env[\"APP_SETTINGS\"] = str(profile)\n    env[\"ONTOLOGY_COMPILER\"] = str(repo / \"compiler\")\n    env[\"NL_ANSWER_LLM\"] = \"0\"          # deterministic: rules + the compiler, no prose model\n    try:\n        p = _sp.run([_python(), \"-c\", _CHILD, _json.dumps(payload)],\n                    capture_output=True, text=True, timeout=180,\n                    cwd=str(repo / \"compiler\"), env=env)\n    except Exception as exc:\n        return \"ERROR: could not run the compiler (%s: %s)\" % (type(exc).__name__, exc)\n\n    lines_out = (p.stdout or \"\").strip().splitlines()\n    if not lines_out:\n        tail = (p.stderr or \"\").strip().splitlines()\n        return (\"ERROR: the compiler printed nothing%s\"\n                % (\": \" + tail[-1] if tail else \" (exit %s)\" % p.returncode))\n    try:\n        data = _json.loads(lines_out[-1])\n    except Exception:\n        return \"ERROR: the compiler''s answer was not JSON: %s\" % lines_out[-1][:400]\n\n    head = \"ontology %s  (%s)\\nprofile: %s\" % (key if not source_dir else key + \" · copy\",\n                                               mode, profile)\n    body = []\n    if mode == \"list\":\n        body.append(\"compiled (%d): %s\" % (len(data.get(\"metrics\") or []),\n                                           \", \".join(data.get(\"metrics\") or []) or \"(none)\"))\n        refused = data.get(\"refused\") or []\n        body.append(\"\")\n        body.append(\"refused by name (%d):\" % len(refused))\n        for r in refused:\n            body.append(\"  REFUSED %s: %s\" % (r.get(\"name\"), r.get(\"why\")))\n        body.append(\"\")\n        body.append(\"Ask for one metric (metric=...) or a question (question=...) next; that is \"\n                    \"cheaper and more precise than reading the engine.\")\n    elif mode == \"metric\":\n        if not data.get(\"ok\"):\n            body.append(\"REFUSED: %s\" % data.get(\"refused\") or data.get(\"error\"))\n            if data.get(\"near\"):\n                body.append(\"did you mean: %s\" % \", \".join(data[\"near\"]))\n        else:\n            body.append(\"compiled SQL:\\n%s\" % (data.get(\"sql\") or \"\").strip())\n            body.append(\"\")\n            body.append(\"value: %s   (plan_rows=%s)\" % (data.get(\"value\"), data.get(\"plan_rows\")))\n            for note in data.get(\"guard_notes\") or []:\n                body.append(\"  guard: %s\" % note)\n            if data.get(\"notes\"):\n                body.append(\"notes: %s\" % \" · \".join(str(n) for n in data[\"notes\"]))\n        rest = data.get(\"refused\")\n        if isinstance(rest, list) and rest:\n            body.append(\"\")\n            body.append(\"refused by name (%d): %s\" % (len(rest),\n                                                      \", \".join(r[\"name\"] for r in rest)))\n    else:\n        q = payload[\"question\"]\n        if data.get(\"ok\"):\n            intent = data.get(\"intent\") or {}\n            body.append(\"resolved: %s %s\" % (intent.get(\"kind\"), intent.get(\"name\")))\n            body.append(\"value: %s\" % data.get(\"value\"))\n            if data.get(\"answer\"):\n                body.append(\"answer: %s\" % data[\"answer\"])\n        else:\n            body.append(\"REFUSED: %s\" % (data.get(\"refused\") or \"see the compiler\"))\n        body.append(\"\")\n        body.append(\"A refusal names the declaration that is missing. Declare it; never type SQL \"\n                    \"for it, and never widen a guard to get past it.\")\n\n    if source_dir:\n        body.append(\"\")\n        body.append(\"(inspected the COPY at %s — the installed ontology is unchanged)\" % folder)\n    return head + \"\\n\\n\" + \"\\n\".join(body)\n", "args_schema": {"ontology_key": {"type": "string", "description": "The ontology''s folder name under features/ontology/profiles/, e.g. ''logistics''."}, "metric": {"type": "string", "description": "One metric to inspect (empty = list everything).", "default": ""}, "question": {"type": "string", "description": "A user question to resolve (empty = ignore).", "default": ""}, "source_dir": {"type": "string", "description": "Inspect this copy instead of the installed ontology.", "default": ""}}}', '{"type": "object", "properties": {"ontology_key": {"type": "string", "description": "The ontology''s folder name under features/ontology/profiles/, e.g. ''logistics''."}, "metric": {"type": "string", "description": "One metric to inspect (empty = list everything).", "default": ""}, "question": {"type": "string", "description": "A user question to resolve (empty = ignore).", "default": ""}, "source_dir": {"type": "string", "description": "Inspect this copy instead of the installed ontology (e.g. ''work/logistics'').", "default": ""}}, "required": ["ontology_key"]}', 'string', NULL, '{"category": "ontology", "order": 3, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'ontology', TRUE, 'false', '["ontology", "inspect", "metrics", "refusals"]', '2026-11-07 01:25:20.174769+00:00', '2026-11-11 08:26:09.982585+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'ontology_inspect')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 225);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 224, 'ontology_open', 'Ontology Open (edit a copy)', 'Open a published ontology for editing: copies ontologies/<key>/ from the ontology repo into your workspace (work/<key>/ by default) and reports the profile facts an editor needs first (namespace, ontology dir, overlay file, database, guard limits, features, sample/alias counts). The repo is read-only here: you edit the COPY and hand it back with ontology_publish, which stages rather than installs. Refuses to overwrite a destination that already holds unpublished edits unless overwrite=true. Use this instead of shell-copying the repo, which breaks the workspace boundary and leaves no audit trail.', 'python_function', 'custom', '{"function_name": "ontology_open", "code": "# --- imports ---\nimport json as _json\nimport pathlib as _pl\nimport shutil as _shutil\nimport time as _time\n\n_TEXT_SUFFIXES = {\n    \".ttl\", \".json\", \".py\", \".md\", \".html\", \".htm\", \".css\", \".js\", \".txt\", \".csv\",\n    \".tsv\", \".yml\", \".yaml\", \".sql\", \".owl\", \".jsonl\",\n}\n_SKIP_DIRS = {\".staging\", \".backup\", \"__pycache__\", \".git\", \".pytest_cache\", \".mypy_cache\",\n              \"node_modules\", \".venv\"}\n_SKIP_NAMES = {\".gitignore\"}\n_MAX_FILE_BYTES = 4 * 1024 * 1024\n\n\ndef _workspace_root():\n    from services.user_roots import current_root\n    return _pl.Path(current_root())\n\n\ndef _copy_tree(src, dst):\n    \"\"\"Copy the ontology''s text files (never staging/backup scratch). Returns (paths, skipped).\"\"\"\n    written, skipped = [], []\n    for path in sorted(src.rglob(\"*\")):\n        if not path.is_file():\n            continue\n        parts = path.relative_to(src).parts\n        rel = \"/\".join(parts)\n        if any(p in _SKIP_DIRS for p in parts) or path.name in _SKIP_NAMES:\n            continue\n        if path.suffix.lower() not in _TEXT_SUFFIXES:\n            skipped.append(rel + \" (not text)\")\n            continue\n        if path.stat().st_size > _MAX_FILE_BYTES:\n            skipped.append(rel + \" (too large)\")\n            continue\n        target = dst / rel\n        target.parent.mkdir(parents=True, exist_ok=True)\n        _shutil.copy2(path, target)\n        written.append(rel)\n    return written, skipped\n\n\ndef _profile_summary(folder):\n    \"\"\"The bits an editor must know before touching a declaration.\"\"\"\n    candidates = sorted(folder.glob(\"*_settings.json\")) or sorted(folder.glob(\"settings.json\"))\n    if not candidates:\n        return None\n    try:\n        d = _json.loads(candidates[0].read_text(encoding=\"utf-8\"))\n    except Exception as exc:\n        return {\"profile\": candidates[0].name, \"error\": \"unreadable: %s\" % exc}\n    dsn = d.get(\"dsn\") or {}\n    guard = d.get(\"guard\") or {}\n    return {\n        \"profile\": candidates[0].name,\n        \"title\": d.get(\"title\"),\n        \"ns\": d.get(\"ns\"),\n        \"ontology_dir\": d.get(\"ontology_dir\", \"ontology\"),\n        \"overlay\": d.get(\"overlay\"),\n        \"database\": dsn.get(\"dbname\") or dsn.get(\"database\"),\n        \"guard\": {k: guard.get(k) for k in\n                  (\"enabled\", \"max_rows\", \"statement_timeout_ms\", \"max_plan_rows\",\n                   \"default_window_days\") if k in guard},\n        \"big_tables\": list((guard.get(\"big_tables\") or {}) or []) or None,\n        \"features\": d.get(\"features\") or {},\n        \"samples\": len(d.get(\"samples\") or []),\n        \"aliases\": len(d.get(\"aliases\") or {}),\n    }\n\n\ndef ontology_open(ontology_key: str, dest: str = \"\", overwrite: bool = False) -> str:\n    \"\"\"Open a published ontology for editing: copy it from the repo into your workspace.\n\n    The installed ontology is the truth and it does not live in your workspace. This copies\n    `ontologies/<key>/` (declarations, overlay, profile, tutorial, build reports) into\n    `work/<key>/` so you can READ it and edit the COPY. The repo itself is never written:\n    `ontology_publish` is the only way back, and it stages rather than installs.\n\n    Ask, then edit, then publish — never the other way round. Editing a copy whose profile or\n    declarations you have not read is how a grain or a threshold gets invented.\n\n    Arguments:\n      ontology_key  the ontology''s folder name under ontologies/, e.g. \"logistics\".\n      dest          where to put it, relative to your workspace (default \"work/<key>\").\n      overwrite     false (default) refuses a destination that already exists, so a re-open\n                    cannot silently throw away edits you have not published. Pass true when\n                    you mean to start again from the installed truth.\n\n    Returns the copied file list plus the profile facts an editor needs first: namespace,\n    ontology dir, overlay file, database name, guard limits, features, sample/alias counts.\n    \"\"\"\n    key = (ontology_key or \"\").strip()\n    if not key or \"/\" in key or key.startswith(\".\"):\n        return \"ERROR: ontology_key must be a folder name under ontologies/, e.g. ''logistics''.\"\n\n    try:\n        from services import ontology_publish as _pub\n    except Exception as exc:\n        return \"ERROR: the ontology repo is not available in this install (%s).\" % exc\n\n    src = _pl.Path(_pub.ONTOLOGIES) / key\n    if not src.is_dir():\n        try:\n            available = sorted(p.name for p in _pl.Path(_pub.ONTOLOGIES).iterdir()\n                               if p.is_dir() and not p.name.startswith(\".\"))\n        except Exception:\n            available = []\n        return (\"ERROR: no installed ontology %r. Available: %s\"\n                % (key, \", \".join(available) or \"(none)\"))\n\n    try:\n        root = _workspace_root()\n    except Exception as exc:\n        return \"ERROR: could not resolve your workspace root (%s)\" % exc\n\n    target = _pl.Path(dest).expanduser() if dest else root / \"work\" / key\n    if not target.is_absolute():\n        target = root / target\n    if key not in [p.name for p in target.parents] and key != target.name:\n        return (\"ERROR: dest must be a folder for %r (got %s). Use work/%s.\"\n                % (key, target, key))\n\n    if target.exists() and any(target.iterdir()):\n        if not overwrite:\n            stamp = _time.strftime(\"%Y%m%d-%H%M%S\")\n            return (\"REFUSED: %s already exists and holds files. Your edits there are the ones \"\n                    \"you have not published yet, so this does not overwrite them.\\n\"\n                    \"- keep working on it, or\\n\"\n                    \"- copy it aside yourself (`work/%s.edited-%s`) and pass overwrite=true to \"\n                    \"start again from the installed truth.\" % (target, key, stamp))\n\n    written, skipped = _copy_tree(src, target)\n    profile = _profile_summary(target)\n    lines = [\"OPENED %s into %s (%d file(s)) - the repo itself was not touched.\"\n             % (key, target, len(written))]\n    lines.append(\"\")\n    lines.append(\"files: \" + \", \".join(written))\n    if skipped:\n        lines.append(\"skipped: \" + \", \".join(skipped))\n    if profile:\n        lines.append(\"\")\n        lines.append(\"profile: \" + _json.dumps(profile, ensure_ascii=False))\n        if profile.get(\"database\"):\n            lines.append(\"the profile''s dsn names database %r - the verification scripts take \"\n                         \"--profile and read this; never type the password anywhere.\"\n                         % profile[\"database\"])\n    lines.append(\"\")\n    lines.append(\"Next: read the profile and the declaration file you mean to change \"\n                 \"(%s), make the edit in %s, then call ontology_publish with \"\n                 \"source_dir=%s. Do not edit the installed ontology, and do not publish \"\n                 \"without reading the file you touched.\"\n                 % (profile.get(\"overlay\") if profile and profile.get(\"overlay\")\n                    else \"the .ttl file\", target, target))\n    return \"\\n\".join(lines)\n", "args_schema": {"ontology_key": {"type": "string", "description": "The ontology''s folder name under ontologies/, e.g. ''logistics''."}, "dest": {"type": "string", "description": "Destination folder relative to your workspace (default work/<key>).", "default": ""}, "overwrite": {"type": "boolean", "description": "Replace an existing copy (default false).", "default": false}}}', '{"type": "object", "properties": {"ontology_key": {"type": "string", "description": "The ontology''s folder name under ontologies/, e.g. ''logistics''."}, "dest": {"type": "string", "description": "Destination folder relative to your workspace (default work/<key>).", "default": ""}, "overwrite": {"type": "boolean", "description": "Replace an existing copy (default false: refuse, so unpublished edits survive).", "default": false}}, "required": ["ontology_key"]}', 'string', NULL, '{"category": "ontology", "order": 2, "section": null, "is_concurrency_safe": false, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'ontology', TRUE, 'false', '["ontology", "edit", "workspace", "semantic-layer"]', '2026-11-07 00:08:20.487291+00:00', '2026-11-07 00:08:20.487291+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'ontology_open')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 224);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 221, 'ontology_publish', 'Ontology Publish (stage)', 'Publish an ontology build or edit through the validated channel (stage only, never install). Pass source_dir (the folder holding 01-structure.ttl / 02-meaning.ttl / metrics_ext.ttl / *_settings.json / tutorial.json) plus `include` when that folder also holds drafts, and optionally files_json ({relative path: content}) for a small edit. The platform copies the files over a STAGING copy of the installed ontology and re-runs the whole suite there: every metric compiled or refused by name, every gate. A publish that introduces a new refusal or a failing gate is refused. The installed ontology, the running workbench and git are untouched: a human with the ontology_editor role confirms the apply, and only then does the workbench reload. Use this instead of copying files into the ontology repo by hand.', 'python_function', 'custom', '{"function_name": "ontology_publish", "code": "# --- imports ---\nimport json as _json\nimport pathlib as _pl\n\n# What a publish may carry: declarations, the profile, the tutorial, the generated pages and\n# scripts. Anything else (images, databases, .pyc) is named and skipped rather than silently\n# dropped or force-encoded.\n_TEXT_SUFFIXES = {\n    \".ttl\", \".json\", \".py\", \".md\", \".html\", \".htm\", \".css\", \".js\", \".txt\", \".csv\",\n    \".tsv\", \".yml\", \".yaml\", \".sql\", \".owl\", \".jsonl\",\n}\n# An agent''s workspace also holds things that are NOT the ontology. Publishing those would\n# install skill bundles and transcripts into an ontology folder, so they never travel.\n_SKIP_DIRS = {\".staging\", \".backup\", \"__pycache__\", \".git\", \".pytest_cache\", \".mypy_cache\",\n              \"node_modules\", \".venv\", \"skills\", \"conversation_history\", \"upload\", \"uploads\"}\n_SKIP_NAMES = {\"AGENTS.md\", \"CLAUDE.md\"}\n_MAX_FILE_BYTES = 2 * 1024 * 1024\n\n\ndef _declaration_noise(parts, name):\n    \"\"\"True for paths that are scaffolding (an agent''s workspace), never ontology content.\"\"\"\n    return any(part in _SKIP_DIRS for part in parts) or (len(parts) == 1 and name in _SKIP_NAMES)\n\n\ndef _matches(rel, wanted):\n    \"\"\"Does `rel` fall under one of the `include` entries (exact, inside a folder, or a glob)?\"\"\"\n    for w in wanted:\n        if rel == w or rel.startswith(w + \"/\"):\n            return True\n        try:\n            if _pl.PurePosixPath(rel).match(w):\n                return True\n        except Exception:\n            pass\n    return False\n\n\ndef _collect_from_dir(source, include=\"\"):\n    \"\"\"Read the ontology''s text files into {rel_path: content}. Returns (files, skipped).\"\"\"\n    root = _pl.Path(source).expanduser()\n    if not root.is_dir():\n        return None, [str(root) + \" is not a directory\"]\n\n    wanted = [w.strip().strip(\"/\") for w in (include or \"\").split(\",\") if w.strip()]\n\n    files, skipped = {}, []\n    for path in sorted(root.rglob(\"*\")):\n        if not path.is_file():\n            continue\n        parts = path.relative_to(root).parts\n        rel = \"/\".join(parts)\n        if _declaration_noise(parts, path.name):\n            continue\n        if wanted and not _matches(rel, wanted):\n            skipped.append(rel + \" (not named in include)\")\n            continue\n        if path.suffix.lower() not in _TEXT_SUFFIXES:\n            skipped.append(rel + \" (not a declaration/profile/text type)\")\n            continue\n        size = path.stat().st_size\n        if size > _MAX_FILE_BYTES:\n            skipped.append(rel + \" (%d bytes is over the %d limit)\" % (size, _MAX_FILE_BYTES))\n            continue\n        try:\n            files[rel] = path.read_text(encoding=\"utf-8\")\n        except UnicodeDecodeError:\n            skipped.append(rel + \" (not UTF-8 text)\")\n    if wanted:\n        for w in wanted:\n            if not any(_matches(r, [w]) for r in files):\n                skipped.append(w + \" (named in include but found nothing)\")\n    return files, skipped\n\n\ndef _resolve_source(source):\n    \"\"\"Relative paths are taken from the workspace root, not from the server''s cwd.\"\"\"\n    path = _pl.Path(source).expanduser()\n    if path.is_absolute():\n        return path\n    try:\n        from services.user_roots import current_root\n        return _pl.Path(current_root()) / path\n    except Exception:\n        return path\n\n\ndef ontology_publish(ontology_key: str, source_dir: str = \"\", files_json: str = \"\",\n                     include: str = \"\", note: str = \"\", profile_name: str = \"\") -> str:\n    \"\"\"Publish (stage) an ontology build or edit through the validated channel.\n\n    Use me when the ontology files are written and the gates you can run locally are green -\n    this hands them to the platform''s publish channel, which re-runs the whole compile + gate\n    suite against a STAGING copy of the installed ontology and records the result.\n\n    I stage, I never install: the installed ontology, the running workbench and git are\n    untouched. A human with the ontology_editor role confirms the apply (one click in\n    Settings -> Ontology -> pending publishes), and only then does the workbench reload.\n\n    Pass either or both of:\n\n    source_dir\n        a directory holding the ontology (01-structure.ttl, 02-meaning.ttl, metrics_ext.ttl,\n        *_settings.json, tutorial.json, ...). A relative path is taken from your workspace\n        root. Text files are collected, binaries are named and skipped, and an agent\n        workspace''s scaffolding (AGENTS.md, CLAUDE.md, skills/, conversation_history/) never\n        travels.\n    include\n        optional comma-separated paths relative to source_dir that ARE the ontology, e.g.\n        \"ontology, metrics_ext.ttl, logistics_settings.json, tutorial.json\". Use it when your\n        workspace root also holds drafts and notes. Empty = every text file.\n    files_json\n        a JSON object {relative path: full file content}, for a small edit where you already\n        have the new file text. These override files from source_dir.\n\n    Read the returned report: new_refusals is the list of things this publish would BREAK (a\n    metric that stops compiling, a gate that goes red) and a staged publish with any of them is\n    refused. Carried refusals were already refused before you started - they are not yours.\n    \"\"\"\n    try:\n        from services import ontology_publish as _pub\n    except Exception as exc:\n        return (\"ERROR: the publish channel is not available in this install (%s). \"\n                \"The harness needs backend/services/ontology_publish.py.\" % exc)\n    try:\n        from services.user_roots import subject_user_id\n        _uid = subject_user_id()\n        actor = \"agent:user%d\" % _uid if _uid is not None else \"agent\"\n    except Exception:\n        actor = \"agent\"\n\n    key = (ontology_key or \"\").strip()\n    if not key:\n        return \"ERROR: ontology_key is required (the folder name under ontologies/, e.g. ''logistics'').\"\n\n    files, skipped = {}, []\n    if source_dir and source_dir.strip():\n        resolved = _resolve_source(source_dir.strip())\n        got, skipped = _collect_from_dir(resolved, include=include or \"\")\n        if got is None:\n            return (\"ERROR: \" + skipped[0] + \". Pass the directory that holds the ontology \"\n                    \"files, or use files_json for a single-file edit.\")\n        files.update(got)\n\n    if files_json and files_json.strip():\n        try:\n            extra = _json.loads(files_json)\n        except Exception as exc:\n            return \"ERROR: files_json is not valid JSON (%s)\" % exc\n        if not isinstance(extra, dict) or not all(\n                isinstance(k, str) and isinstance(v, str) for k, v in extra.items()):\n            return \"ERROR: files_json must be a JSON object of {relative path: file content}\"\n        files.update(extra)\n\n    if not files:\n        return (\"ERROR: nothing to publish. Pass source_dir (the folder with the TTL/profile) \"\n                \"or files_json ({path: content}), or widen `include` - it named nothing that exists.\")\n\n    live_dir = _pl.Path(getattr(_pub, \"ONTOLOGIES\", \"\")) / key\n    is_installed_copy = False\n    if source_dir and source_dir.strip():\n        try:\n            is_installed_copy = _resolve_source(source_dir.strip()).resolve() == live_dir.resolve()\n        except Exception:\n            is_installed_copy = False\n\n    res = _pub.stage(key, files, actor=actor, note=(note or \"\").strip() or \"staged by an agent\",\n                     profile_name=(profile_name or \"\").strip() or None)\n\n    lines = []\n    staged_id = res.get(\"staged_id\")\n    if not res.get(\"ok\"):\n        lines.append(\"REFUSED at stage time for \" + key + \": \"\n                     + str(res.get(\"error\") or \"see the report\"))\n    else:\n        lines.append(\"STAGED \" + key + \" as \" + str(staged_id) + \" - installed ontology untouched.\")\n    report = res.get(\"report\") or {}\n    if report:\n        comp = report.get(\"compile\") or {}\n        lines.append(\"\")\n        lines.append(\"compile: %d of %d metric(s) compiled, %d refused by name\" % (\n            int(comp.get(\"compiled\") or 0), int(comp.get(\"metrics\") or 0),\n            len(comp.get(\"refused\") or [])))\n        for row in (comp.get(\"refused\") or [])[:10]:\n            lines.append(\"  REFUSED %s: %s\" % (row.get(\"name\"), row.get(\"why\")))\n        if comp.get(\"error\"):\n            lines.append(\"  compiler error: \" + str(comp[\"error\"]))\n        if report.get(\"new_refusals\"):\n            lines.append(\"NEW refusals introduced by this publish (this is why it is refused): \"\n                         + \", \".join(report[\"new_refusals\"]))\n        if report.get(\"carried_refusals\"):\n            lines.append(\"carried refusals (already refused in the installed ontology): \"\n                         + \", \".join(report[\"carried_refusals\"]))\n        lines.append(\"gates: \" + (\"PASS\" if report.get(\"gates_ok\") else\n                                  \"FAIL - \" + \"; \".join(report.get(\"gates_fails\") or [])))\n        if report.get(\"gates_not_run\"):\n            lines.append(\"gates NOT RUN (named, not passed): \" + \", \".join(report[\"gates_not_run\"]))\n        lines.append(\"\")\n        lines.append(\"files (%d): %s\" % (len(report.get(\"files\") or []),\n                                         \", \".join(report.get(\"files\") or [])))\n        if skipped:\n            lines.append(\"skipped %d: %s\" % (len(skipped), \", \".join(skipped[:10])))\n\n    lines.append(\"\")\n    if res.get(\"ok\"):\n        lines.append(\"Next step (a human, one click): Settings -> Ontology -> Pending publishes \"\n                     \"-> apply \" + str(staged_id) + \". That re-runs the gates on the installed \"\n                     \"copy, commits with the gate summary, and reloads the workbench. Do NOT copy \"\n                     \"files into the ontology repo yourself - that skips the gates.\")\n        if is_installed_copy:\n            lines.append(\"Note: source_dir IS the installed ontology folder. Staging re-validates \"\n                         \"the installed truth; there is nothing new to install unless it differs, \"\n                         \"so an apply here would restore identical bytes.\")\n    else:\n        lines.append(\"Nothing was installed. Fix what the report names and publish again - a \"\n                     \"refusal is the ontology''s contract, not a tool failure.\")\n    return \"\\n\".join(lines)\n", "args_schema": {"ontology_key": {"type": "string", "description": "The ontology''s folder name under ontologies/, e.g. ''logistics''."}, "source_dir": {"type": "string", "description": "Directory holding the ontology files to publish.", "default": ""}, "include": {"type": "string", "description": "Comma-separated paths relative to source_dir that ARE the ontology (empty = every text file).", "default": ""}, "files_json": {"type": "string", "description": "JSON object {relative path: full file content} for a small edit.", "default": ""}, "note": {"type": "string", "description": "One line on what changed and why.", "default": ""}, "profile_name": {"type": "string", "description": "Profile file name if the ontology has more than one (*_settings.json).", "default": ""}}}', '{"type": "object", "properties": {"ontology_key": {"type": "string", "description": "The ontology''s folder name under ontologies/, e.g. ''logistics''."}, "source_dir": {"type": "string", "description": "Directory holding the ontology files to publish (relative paths resolve against your workspace root).", "default": ""}, "include": {"type": "string", "description": "Comma-separated paths relative to source_dir that ARE the ontology (e.g. ''ontology, metrics_ext.ttl, logistics_settings.json, tutorial.json''); empty = every text file.", "default": ""}, "files_json": {"type": "string", "description": "JSON object {relative path: full file content} for a small edit; overrides source_dir.", "default": ""}, "note": {"type": "string", "description": "One line on what changed and why — this is the audit trail a reviewer reads.", "default": ""}, "profile_name": {"type": "string", "description": "Profile file name if the ontology has more than one (*_settings.json). Empty = the single one.", "default": ""}}, "required": ["ontology_key"]}', 'string', NULL, '{"category": "ontology", "order": 1, "section": null, "is_concurrency_safe": false, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, NULL, FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'ontology', TRUE, 'false', '["ontology", "publish", "gates", "semantic-layer"]', '2026-11-06 23:39:21.863394+00:00', '2026-11-06 23:42:51.293296+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'ontology_publish')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 221);

