SELECT 70, 'pg_list_custom_tools', 'PG - List Custom Tools', 'List all custom (user-created) tools with their type, description, and usage stats.

Custom tools extend agent capabilities with API integrations, database connectors,
image generators, and custom Python functions.

Args:
    tool_type: Optional filter by type (api, notification, image_video, database, data_transform, python_function)

Returns:
    Formatted list of custom tools

Example:
    >>> pg_list_custom_tools()
    >>> pg_list_custom_tools(tool_type="database")', 'python_function', 'custom', '{"function_name": "pg_list_custom_tools", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_custom_tools(tool_type: str | None = None) -> str:\n    \"\"\"\n    List all custom (user-created) tools with their type, description, and usage stats.\n\n    Custom tools extend agent capabilities with API integrations, database connectors,\n    image generators, and custom Python functions.\n\n    Args:\n        tool_type: Optional filter by type (api, notification, image_video, database, data_transform, python_function)\n\n    Returns:\n        Formatted list of custom tools\n\n    Example:\n        >>> pg_list_custom_tools()\n        >>> pg_list_custom_tools(tool_type=\"database\")\n    \"\"\"\n    from models.custom_tool import CustomTool\n    db = _get_pg_session()\n    try:\n        query = db.query(CustomTool).order_by(CustomTool.usage_count.desc())\n        if tool_type:\n            query = query.filter(CustomTool.tool_type == tool_type)\n        tools = query.all()\n        if not tools:\n            return \"No custom tools found.\" if not tool_type else f\"No custom tools of type ''{tool_type}'' found.\"\n        lines = [f\"## Custom Tools ({len(tools)} total)\", \"\"]\n        for t in tools:\n            lines.append(\n                f\"- **{t.name}** (`{t.tool_id}`)  \"\n                f\"type={t.tool_type.value}  \"\n                f\"template={t.template_type.value if t.template_type else ''custom''}  \"\n                f\"used={t.usage_count}x\"\n            )\n            if t.description:\n                lines.append(f\"  {t.description[:150]}\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing custom tools: {e}\"\n    finally:\n        db.close()", "args_schema": {"tool_type": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"tool_type": {"type": "string", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "database", "order": 44, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034611+00:00', '2026-11-11 01:12:26.319864+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_custom_tools')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 70);

