SELECT 68, 'pg_list_projects', 'PG - List Projects', 'List projects: id, name, document count, indexing status.

Projects group documents and workflows, and are the scope for the
graphindex/doc_index retrieval tools. Use it to find a project id — not to
read a project''s documents.

Args:
    limit: Maximum number of projects to return (default 50).

Returns:
    Formatted list of projects

Example:
    >>> pg_list_projects(limit=10)', 'python_function', 'custom', '{"function_name": "pg_list_projects", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_projects(limit: int = 50) -> str:\n    \"\"\"\n    List projects: id, name, document count, indexing status.\n\n    Projects group documents and workflows, and are the scope for the\n    graphindex/doc_index retrieval tools. Use it to find a project id — not to\n    read a project''s documents.\n\n    Args:\n        limit: Maximum number of projects to return (default 50).\n\n    Returns:\n        Formatted list of projects\n\n    Example:\n        >>> pg_list_projects(limit=10)\n    \"\"\"\n    from models.core import Project, ContextDocument\n    from sqlalchemy import func\n    db = _get_pg_session()\n    try:\n        projects = db.query(\n            Project,\n            func.count(ContextDocument.id).label(\"doc_count\")\n        ).outerjoin(\n            ContextDocument, ContextDocument.project_id == Project.id\n        ).group_by(Project.id).order_by(Project.updated_at.desc()).limit(\n            max(1, int(limit or 50))\n        ).all()\n        if not projects:\n            return \"No projects found.\"\n        lines = [\"## Projects\", \"\"]\n        for proj, doc_count in projects:\n            lines.append(\n                f\"- **{proj.name}** (id={proj.id})  \"\n                f\"status=`{proj.status.value}`  \"\n                f\"docs={doc_count}  \"\n                f\"index={proj.indexing_status.value}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing projects: {e}\"\n    finally:\n        db.close()", "args_schema": {"limit": {"type": "integer", "description": "", "default": 50}}}', '{"type": "object", "properties": {"limit": {"type": "integer", "description": "", "default": 50}}, "required": []}', 'string', NULL, '{"category": "database", "order": 42, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034608+00:00', '2026-11-11 01:12:26.319863+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_projects')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 68);

