SELECT 67, 'pg_list_skills', 'PG - List Skills', 'List skills in the database: id, description, tags, usage count.

Skills are reusable capabilities an agent can load on demand; use this to
find the id to pass to the `skill` tool. Use it when the user asks what
skills exist — not for running a skill.

Args:
    limit: Maximum number of skills to return (default 50, most used first).

Returns:
    Formatted list of available skills

Example:
    >>> pg_list_skills(limit=10)', 'python_function', 'custom', '{"function_name": "pg_list_skills", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_skills(limit: int = 50) -> str:\n    \"\"\"\n    List skills in the database: id, description, tags, usage count.\n\n    Skills are reusable capabilities an agent can load on demand; use this to\n    find the id to pass to the `skill` tool. Use it when the user asks what\n    skills exist — not for running a skill.\n\n    Args:\n        limit: Maximum number of skills to return (default 50, most used first).\n\n    Returns:\n        Formatted list of available skills\n\n    Example:\n        >>> pg_list_skills(limit=10)\n    \"\"\"\n    from models.skill import Skill\n    db = _get_pg_session()\n    try:\n        skills = (\n            db.query(Skill)\n            .order_by(Skill.usage_count.desc())\n            .limit(max(1, int(limit or 50)))\n            .all()\n        )\n        if not skills:\n            return \"No skills found in the database.\"\n        lines = [f\"## Skills ({len(skills)} total)\", \"\"]\n        for s in skills:\n            tags = \", \".join(s.tags or []) if s.tags else \"\"\n            tag_str = f\"  tags=[{tags}]\" if tags else \"\"\n            lines.append(\n                f\"- **{s.name}** (`{s.skill_id}`){tag_str}\\n\"\n                f\"  {s.description[:120]}{''…'' if len(s.description) > 120 else ''''}\\n\"\n                f\"  used {s.usage_count}x | source={s.source_type.value}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing skills: {e}\"\n    finally:\n        db.close()", "args_schema": {"limit": {"type": "integer", "description": "", "default": 50}}}', '{"type": "object", "properties": {"limit": {"type": "integer", "description": "", "default": 50}}, "required": []}', 'string', NULL, '{"category": "database", "order": 40, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034606+00:00', '2026-11-11 01:12:26.319862+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_skills')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 67);

