SELECT 61, 'pg_list_tables', 'PG - List Tables', 'List all tables and views in a PostgreSQL schema with row counts.

Use this to discover what tables exist in the database before querying.

Args:
    schema_name: Schema name to list (default: ''public'')

Returns:
    Formatted table list with type (table/view) and estimated row count

Example:
    >>> pg_list_tables()
    >>> pg_list_tables(schema_name="public")', 'python_function', 'custom', '{"function_name": "pg_list_tables", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_tables(schema_name: str = \"public\") -> str:\n    \"\"\"\n    List all tables and views in a PostgreSQL schema with row counts.\n\n    Use this to discover what tables exist in the database before querying.\n\n    Args:\n        schema_name: Schema name to list (default: ''public'')\n\n    Returns:\n        Formatted table list with type (table/view) and estimated row count\n\n    Example:\n        >>> pg_list_tables()\n        >>> pg_list_tables(schema_name=\"public\")\n    \"\"\"\n    import sqlalchemy as sa\n    db = _get_pg_session()\n    try:\n        conn = db.connection()\n        # pg_stat_user_tables uses relname; fall back to information_schema for reliability\n        result = conn.execute(sa.text(\n            \"\"\"\n            SELECT\n                relname AS name,\n                ''table'' AS type,\n                n_live_tup AS estimated_rows\n            FROM pg_catalog.pg_stat_user_tables\n            WHERE schemaname = :schema\n            UNION ALL\n            SELECT\n                viewname AS name,\n                ''view'' AS type,\n                0 AS estimated_rows\n            FROM pg_catalog.pg_views\n            WHERE schemaname = :schema\n            ORDER BY name\n            \"\"\"\n        ), {\"schema\": schema_name})\n        rows = result.fetchall()\n        if not rows:\n            return f\"No tables found in schema ''{schema_name}''.\"\n        lines = [f\"## Tables in schema ''{schema_name}''\", \"\"]\n        for r in rows:\n            lines.append(f\"- **{r.name}** ({r.type}, ~{r.estimated_rows} rows)\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing tables: {e}\"\n    finally:\n        db.close()", "args_schema": {"schema_name": {"type": "string", "description": "", "default": "public"}}}', '{"type": "object", "properties": {"schema_name": {"type": "string", "description": "", "default": "public"}}, "required": []}', 'string', NULL, '{"category": "database", "order": 33, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034594+00:00', '2026-11-11 01:12:26.319859+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_tables')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 61);

