SELECT 63, 'pg_query', 'PG - Query (SELECT)', '用我：查平台自己的 PostgreSQL（只读 SELECT），例如 deep_agent_templates。
别用我：查 SQLite / 临时表用 sqlite_execute；用自然语言问业务库用 sql_agent_tool。

Run a read-only SQL SELECT query against PostgreSQL and return results as a table.

SAFETY: Only SELECT statements are allowed. INSERT/UPDATE/DELETE are rejected.
Use pg_execute for write operations.

Args:
    sql: The SELECT SQL query to run (e.g. ''SELECT * FROM deep_agent_templates LIMIT 5'')

Returns:
    Query results formatted as a markdown table

Example:
    >>> pg_query("SELECT id, name, category FROM deep_agent_templates ORDER BY created_at DESC LIMIT 10")
    >>> pg_query("SELECT count(*) AS total FROM skills")', 'python_function', 'custom', '{"function_name": "pg_query", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport re as _re\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_query(sql: str) -> str:\n    \"\"\"\n    用我：查平台自己的 PostgreSQL（只读 SELECT），例如 deep_agent_templates。\n    别用我：查 SQLite / 临时表用 sqlite_execute；用自然语言问业务库用 sql_agent_tool。\n\n    Run a read-only SQL SELECT query against PostgreSQL and return results as a table.\n\n    SAFETY: Only SELECT statements are allowed. INSERT/UPDATE/DELETE are rejected.\n    Use pg_execute for write operations.\n\n    Args:\n        sql: The SELECT SQL query to run (e.g. ''SELECT * FROM deep_agent_templates LIMIT 5'')\n\n    Returns:\n        Query results formatted as a markdown table\n\n    Example:\n        >>> pg_query(\"SELECT id, name, category FROM deep_agent_templates ORDER BY created_at DESC LIMIT 10\")\n        >>> pg_query(\"SELECT count(*) AS total FROM skills\")\n    \"\"\"\n    import sqlalchemy as sa\n    import re as _re\n    # Read-only guard: require a single, comment-free SELECT statement. '';'' is\n    # rejected so stacked multi-statements (e.g. \"SELECT 1; DROP TABLE x\") can''t\n    # slip past a naive startswith(\"select\") check, and leading comments are\n    # stripped so \"/* */ DROP ...\" can''t dodge the keyword check either.\n    stripped = sql.strip()\n    if stripped.endswith(\";\"):\n        stripped = stripped[:-1].rstrip()\n    if \";\" in stripped:\n        return \"❌ Multiple statements are not allowed. Use a single SELECT query.\"\n    no_comments = _re.sub(r\"^\\s*(--[^\\n]*\\n|/\\*.*?\\*/|#.*?\\n)*\\s*\", \"\", stripped,\n                          flags=_re.DOTALL).lower()\n    if not no_comments.startswith(\"select\"):\n        return \"❌ Only SELECT queries are allowed. Use pg_execute for write operations.\"\n    sql = stripped\n\n    db = _get_pg_session()\n    try:\n        conn = db.connection()\n        result = conn.execute(sa.text(sql))\n        rows = result.fetchall()\n        if not rows:\n            return \"Query returned no rows.\"\n        col_names = result.keys()\n        lines = [\"| \" + \" | \".join(col_names) + \" |\"]\n        lines.append(\"| \" + \" | \".join(\"---\" for _ in col_names) + \" |\")\n        for row in rows:\n            vals = []\n            for v in row:\n                s = str(v) if v is not None else \"NULL\"\n                if len(s) > 200:\n                    s = s[:200] + \"…\"\n                vals.append(s)\n            lines.append(\"| \" + \" | \".join(vals) + \" |\")\n        lines.append(f\"\\n*{len(rows)} row(s) returned*\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Query error: {e}\"\n    finally:\n        db.close()", "args_schema": {"sql": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"sql": {"type": "string", "description": ""}}, "required": ["sql"]}', 'string', NULL, '{"category": "database", "order": 35, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034598+00:00', '2026-11-11 01:12:26.319860+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_query')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 63);

