solve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef rename_file(old_path: str, new_path: str) -> str:\n    \"\"\"Rename a file or directory to a new name (same location).\n\n    Args:\n        old_path: Current path of the file/directory\n        new_path: New name/path (the destination must not already exist)\n    \"\"\"\n    src, error = _resolve_sandbox_path(old_path)\n    if error:\n        return error\n    dst, error = _resolve_sandbox_path(new_path)\n    if error:\n        return error\n    if not src.exists():\n        return f\"Error: ''{old_path}'' not found\"\n    if dst.exists():\n        return f\"Error: destination ''{new_path}'' already exists\"\n    src.rename(dst)\n    return f\"Renamed ''{old_path}'' → ''{new_path}''\"", "args_schema": {"old_path": {"type": "string", "description": ""}, "new_path": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"old_path": {"type": "string", "description": ""}, "new_path": {"type": "string", "description": ""}}, "required": ["old_path", "new_path"]}', 'string', NULL, '{"category": "filesystem", "order": 10, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-15 08:02:47.985669+00:00', '2026-11-11 02:00:59.925340+00:00'
