SELECT 84, 'search_skills', 'Search Skills', 'Search skills by name, description, or tags.', 'python_function', 'custom', '{"function_name": "search_skills", "code": "def _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef search_skills(query: str) -> str:\n    \"\"\"\n    Search skills by name, description, or tags.\n\n    Useful for an agent to find relevant skills for a given task.\n    Returns matching skills with their ID, name, description, tags, and triggers.\n\n    Args:\n        query: Search keyword (e.g., ''stock'', ''database'', ''research'')\n\n    Returns:\n        Formatted list of matching skills\n\n    Example:\n        >>> search_skills(\"stock market\")\n    \"\"\"\n    from models.skill import Skill\n    db = _get_pg_session()\n    try:\n        query_lower = query.lower()\n        skills = db.query(Skill).order_by(Skill.usage_count.desc()).all()\n        matches = []\n        for s in skills:\n            if (query_lower in s.name.lower() or\n                query_lower in (s.description or \"\").lower() or\n                any(query_lower in t.lower() for t in (s.tags or [])) or\n                any(query_lower in t.lower() for t in (s.triggers or []))):\n                matches.append(s)\n        if not matches:\n            return f\"No skills found matching ''{query}''.\"\n        lines = [f\"## Matching skills for ''{query}'' ({len(matches)} found)\", \"\"]\n        for s in matches:\n            tags = \", \".join(s.tags or [])\n            triggers = \"; \".join((s.triggers or [])[:3])\n            lines.append(f\"### {s.name} (`{s.skill_id}`)\")\n            lines.append(f\"  Description: {s.description or ''N/A''}\")\n            lines.append(f\"  Tags: {tags}\")\n            lines.append(f\"  Triggers: {triggers}\")\n            lines.append(f\"  Used: {s.usage_count}x\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error searching skills: {e}\"\n    finally:\n        db.close()", "args_schema": {"query": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": ""}}, "required": ["query"]}', 'string', NULL, '{"category": "database", "order": 41, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034639+00:00', '2026-11-11 01:12:26.327461+00:00'
