SELECT 94, 'skill', 'Read Skill', 'Fetch a skill''s full instructions by its id — or one of its support files.', 'python_function', 'custom', '{"function_name": "skill", "code": "# --- imports ---\n\nfrom pathlib import Path\n\ndef _skill_support_files(base: Path, limit: int = 40) -> list:\n    \"\"\"Files next to SKILL.md, as skill-relative paths (sorted, capped).\n\n    A skill that ships templates or reference tables is useless if the model\n    cannot see that they exist: the instructions are in the DB, the files are on\n    disk. Seen 2026-11-01 — Agent Builder rebuilt a template from memory because\n    `templates/` was invisible.\n    \"\"\"\n    if base is None or not base.is_dir():\n        return []\n    out = []\n    for path in sorted(base.rglob(\"*\")):\n        if not path.is_file() or path.name == \"SKILL.md\":\n            continue\n        out.append(str(path.relative_to(base)))\n        if len(out) >= limit:\n            break\n    return out\n\nasync def skill(skill_id: str, file: str = \"\", lang: str = \"\") -> str:\n    \"\"\"Fetch a skill''s full instructions by its id — or one of its support files.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Skills may ship supporting files next to SKILL.md (templates, fact tables,\n    scripts). Those are NOT loaded with the instructions; list them with this\n    tool first (it prints `Support files:`), then ask for one by path.\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n        file: Optional path inside the skill directory, e.g.\n              \"templates/T2-supervisor-experts.md\". Leave empty for the\n              instructions. Must stay inside the skill.\n        lang: Which language to serve. Empty (the default) serves `SKILL.md` — the working text, which is\n              Chinese for every skill that has been translated. `lang=\"en\"` serves the archived English\n              original from `backend/skills/en-originals/<id>/SKILL.md`, which nothing else reads: it is a\n              backup and a source for checking a translation, and it enters a context only when asked for\n              by name.\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            registry.record_usage(skill_id, \"explicit\", \"failed\", source=\"skill tool: not found\")\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        base = Path(found.source_path) if getattr(found, \"source_path\", None) else None\n\n        if file:\n            if base is None or not base.is_dir():\n                return f\"Error: skill ''{skill_id}'' has no source directory on disk.\"\n            target = (base / file).resolve()\n            try:\n                target.relative_to(base.resolve())\n            except ValueError:\n                return f\"Error: ''{file}'' escapes skill ''{skill_id}''.\"\n            if not target.is_file():\n                listing = _skill_support_files(base)\n                return (f\"Error: ''{file}'' not found in skill ''{skill_id}''. \"\n                        f\"Support files: {'', ''.join(listing) or ''none''}\")\n            text = target.read_text(encoding=\"utf-8\", errors=\"replace\")\n            return f\"# Skill file: {skill_id}/{file}\\n\\n{text}\"\n\n        # The working text is Chinese: `SKILL.md` is what an agent reads, and the English original lives\n        # outside the skill library (`backend/skills/en-originals/<id>/`) as a backup. Nothing loads it\n        # unless the caller asks for it explicitly by language — which is why the default below is the\n        # canonical file and not a sibling.\n        body_text, body_lang = found.instructions, \"zh\"\n        if lang and lang.split(\"-\")[0].lower() == \"en\":\n            # base is .../skills/builtin/<id>; the archive sits beside the library root\n            archived = (Path(base).parents[1] / \"en-originals\" / found.skill_id / \"SKILL.md\"\n                        if base is not None else None)\n            if archived is not None and archived.is_file():\n                raw = archived.read_text(encoding=\"utf-8\", errors=\"replace\")\n                if raw.startswith(\"---\"):\n                    end = raw.find(\"\\n---\", 3)\n                    if end != -1:\n                        raw = raw[end + 4:].lstrip(\"\\n\")\n                body_text, body_lang = raw, \"en\"\n        parts = [\n            f\"# Skill: {found.name}\" + (f\"  (instructions: {body_lang})\" if body_lang != \"zh\" else \"\"),\n            f\"**Description:** {found.description}\",\n            \"\",\n            body_text,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        support = _skill_support_files(base) if base else []\n        if support:\n            parts += [\n                \"\",\n                \"**Support files** (not loaded above — fetch one with \"\n                f\"skill(\\\"{found.skill_id}\\\", file=\\\"<path>\\\")):\",\n                *[f\"- {f}\" for f in support],\n            ]\n        # Count the use. Until this existed, `usage_count`/`avg_success_rate` were read by the UI and written by\n        # nobody: the library showed \"0 uses\" for skills that had been served hundreds of times.\n        registry.record_usage(found.skill_id, \"explicit\", \"success\", source=\"skill tool\")\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"", "args_schema": {"skill_id": {"type": "string", "description": ""}, "file": {"type": "string", "description": "", "default": ""}, "lang": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"skill_id": {"type": "string", "description": ""}, "file": {"type": "string", "description": "", "default": ""}, "lang": {"type": "string", "description": "", "default": ""}}, "required": ["skill_id"]}', 'string', NULL, '{"category": "skills", "order": 25, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-15 08:09:02.162849+00:00', '2026-11-11 01:12:26.331275+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'skill')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 94);

