SELECT 76, 'sqlite_execute', 'SQLite Execute', '用我：对 SQLite 文件或临时表跑只读 SQL（配 sqlite_load_csv 建表）。', 'python_function', 'custom', '{"function_name": "sqlite_execute", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nimport os\n\nimport sqlite3 as _sqlite3\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef _validate_sqlite_db_path(db_path: str):\n    \"\"\"Only '':memory:'' or a file inside the workspace sandbox is allowed.\"\"\"\n    if not db_path or db_path == \":memory:\":\n        return None\n    _, err = _resolve_sandbox_path(db_path)\n    return err\n\ndef sqlite_execute(sql: str, db_path: str = \":memory:\") -> str:\n    \"\"\"\n    用我：对 SQLite 文件或临时表跑只读 SQL（配 sqlite_load_csv 建表）。\n    别用我：查平台库用 pg_query。\n\n    Execute a read-only SQL query on a SQLite database.\n\n    Useful for the sql-skill-generator agent to validate generated SQL queries\n    against mock data before saving them as few-shot examples in a skill.\n\n    Args:\n        sql: SELECT SQL query to execute.\n        db_path: Path to SQLite DB file or \":memory:\" (default).\n\n    Returns:\n        Formatted query results or error message.\n    \"\"\"\n    # Safety: block all non-SELECT statements\n    sql_stripped = sql.strip().strip(\";\").strip()\n    sql_lower = sql_stripped.lower()\n\n    # ''pragma'' used to be whitelisted out of the blocked list, which made the\n    # guard below dead code for PRAGMA — it is now blocked like every other\n    # write verb (PRAGMA can mutate db state, e.g. PRAGMA writable_schema=ON).\n    blocked_keywords = [\"insert\", \"update\", \"delete\", \"drop\", \"alter\",\n                        \"create\", \"replace\", \"truncate\", \"exec\", \"pragma\"]\n\n    first_word = sql_lower.split()[0] if sql_lower.split() else \"\"\n    if first_word in blocked_keywords:\n        return f\"❌ BLOCKED: Only SELECT queries are allowed. Got: ''{sql_stripped[:100]}''\"\n    # Reject stacked statements (e.g. \"SELECT 1; DROP TABLE x\") — the sub-query\n    # wrapper below would otherwise only execute the first statement silently.\n    if \";\" in sql_stripped:\n        return \"❌ BLOCKED: Multiple statements are not allowed.\"\n\n    err = _validate_sqlite_db_path(db_path)\n    if err:\n        return err\n\n    conn = None\n    try:\n        conn = _sqlite3.connect(db_path)\n        conn.row_factory = _sqlite3.Row\n        cursor = conn.cursor()\n        cursor.execute(f\"SELECT * FROM ({sql_stripped}) LIMIT 200\")\n        rows = cursor.fetchall()\n        col_names = [desc[0] for desc in cursor.description] if cursor.description else []\n\n        if not rows:\n            return \"✅ Query executed. No rows returned (empty result).\"\n\n        # Format output as aligned table\n        widths = [len(c) for c in col_names]\n        for row in rows:\n            for i, val in enumerate(row):\n                widths[i] = max(widths[i], len(str(val)))\n\n        header = \" | \".join(c.ljust(w) for c, w in zip(col_names, widths))\n        sep = \"-+-\".join(\"-\" * w for w in widths)\n        body = \"\\n\".join(\n            \" | \".join(str(v).ljust(w) for v, w in zip(row, widths))\n            for row in rows[:50]  # Max 50 rows in output\n        )\n\n        summary = f\"✅ {len(rows)} row(s) returned\"\n        return f\"{summary}\\n\\n{header}\\n{sep}\\n{body}\"\n\n    except Exception as e:\n        return f\"❌ SQL Error: {e}\"\n    finally:\n        # Always release the connection — the success paths above no longer\n        # close explicitly, so an error mid-formatting can''t leak it.\n        if conn is not None:\n            conn.close()", "args_schema": {"sql": {"type": "string", "description": ""}, "db_path": {"type": "string", "description": "", "default": ":memory:"}}}', '{"type": "object", "properties": {"sql": {"type": "string", "description": ""}, "db_path": {"type": "string", "description": "", "default": ":memory:"}}, "required": ["sql"]}', 'string', NULL, '{"category": "analysis", "order": 71, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'data', TRUE, NULL, '["builtin", "data"]', '2026-08-01 14:44:18.034623+00:00', '2026-11-11 03:05:55.307374+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'sqlite_execute')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 76);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 91, 'sqlite_load_csv', 'SQLite Load CSV', 'Load CSV data into a SQLite database.
Utility function — infers column names from CSV header.

Args:
    csv_content: CSV content as string (with header row)
    table_name: Name of the table to create
    db_path: Path to SQLite DB file or ":memory:"

Returns:
    Status message with row count.', 'python_function', 'custom', '{"function_name": "sqlite_load_csv", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\nimport sqlite3 as _sqlite3\n\nimport csv as _csv\n\nimport io as _io\n\nimport re as _re\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    # A RELATIVE path (\"upload/orders.xlsx\") is how an agent names a file in ITS OWN workspace, but\n    # `Path(...).resolve()` resolves against the server''s cwd (`backend/`), which is not in any\n    # sandbox root — so the check above refused the most natural path there is. Measured on the\n    # table-building agent: it could not find its own uploaded workbook with glob/read_any_file\n    # and burned a whole turn asking for the file path. Try each root, first existing wins.\n    if not Path(path_str).is_absolute():\n        for root in _sandbox_roots():\n            candidate = (root / path_str).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    # A VIRTUAL path (\"/upload/brief.docx\") is how the agent''s own file tools display its workspace, so it is\n    # the form an agent naturally passes to a reader. `/upload/brief.docx` is not a real absolute path, so the\n    # check above refuses it — measured: three refusals in one turn while the file sat in the workspace the\n    # agent was told to read. Resolve it under each allowed root, and only accept a path that exists there.\n    if path_str.startswith(\"/\"):\n        for root in _sandbox_roots():\n            candidate = (root / path_str.lstrip(\"/\")).resolve()\n            try:\n                candidate.relative_to(root)\n            except ValueError:\n                continue\n            if candidate.exists():\n                return candidate, None\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef _validate_sqlite_db_path(db_path: str):\n    \"\"\"Only '':memory:'' or a file inside the workspace sandbox is allowed.\"\"\"\n    if not db_path or db_path == \":memory:\":\n        return None\n    _, err = _resolve_sandbox_path(db_path)\n    return err\n\ndef sqlite_load_csv(csv_content: str, table_name: str, db_path: str = \":memory:\") -> str:\n    \"\"\"\n    Load CSV data into a SQLite database.\n    Utility function — infers column names from CSV header.\n\n    Args:\n        csv_content: CSV content as string (with header row)\n        table_name: Name of the table to create\n        db_path: Path to SQLite DB file or \":memory:\"\n\n    Returns:\n        Status message with row count.\n    \"\"\"\n    try:\n        reader = _csv.DictReader(_io.StringIO(csv_content))\n        rows = list(reader)\n        if not rows:\n            return \"❌ CSV has no data rows.\"\n\n        col_names = list(rows[0].keys())\n\n        # Quote identifiers by doubling embedded quotes — never interpolate raw\n        # CSV headers / table names into SQL unescaped.\n        def _q(ident: str) -> str:\n            return ''\"'' + ident.replace(''\"'', ''\"\"'') + ''\"''\n\n        if not _re.match(r\"^[A-Za-z_][A-Za-z0-9_]*$\", table_name):\n            return (\"❌ Invalid table_name: use letters, digits and underscores \"\n                    \"only (got %r).\" % table_name[:50])\n\n        err = _validate_sqlite_db_path(db_path)\n        if err:\n            return err\n\n        col_defs = \", \".join(f\"{_q(c)} TEXT\" for c in col_names)\n        placeholders = \", \".join(\"?\" for _ in col_names)\n\n        conn = _sqlite3.connect(db_path)\n        cursor = conn.cursor()\n        cursor.execute(f\"DROP TABLE IF EXISTS {_q(table_name)}\")\n        cursor.execute(f''CREATE TABLE {_q(table_name)} ({col_defs})'')\n\n        for row in rows:\n            values = [row.get(c, \"\") for c in col_names]\n            col_list = '', ''.join(_q(c) for c in col_names)\n            cursor.execute(f''INSERT INTO {_q(table_name)} ({col_list}) VALUES ({placeholders})'', values)\n\n        conn.commit()\n        conn.close()\n        return f\"✅ Loaded {len(rows)} rows into table ''{table_name}'' ({len(col_names)} columns: {'', ''.join(col_names)})\"\n    except Exception as e:\n        return f\"❌ CSV Load Error: {e}\"", "args_schema": {"csv_content": {"type": "string", "description": ""}, "table_name": {"type": "string", "description": ""}, "db_path": {"type": "string", "description": "", "default": ":memory:"}}}', '{"type": "object", "properties": {"csv_content": {"type": "string", "description": ""}, "table_name": {"type": "string", "description": ""}, "db_path": {"type": "string", "description": "", "default": ":memory:"}}, "required": ["csv_content", "table_name"]}', 'string', NULL, '{"category": "analysis", "order": 72, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'data', TRUE, NULL, '["builtin", "data"]', '2026-08-15 08:02:47.985674+00:00', '2026-11-11 03:05:55.307379+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'sqlite_load_csv')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 91);

