SELECT 217, 'sync_skills', 'Sync Skills (disk → DB)', 'Re-read skills from disk into the database (the reverse of update_skill).

`SKILL.md` on disk is the source of truth a teammate edits and commits; the
DB row is what `skill()` serves and what the agent sees. Editing a file on
disk alone does NOT reach an agent until this runs — the startup sync only
compares mtimes once per boot. Requires approval (it writes the DB).

Args:
    dry_run: Report what would change without writing.', 'python_function', 'custom', '{"function_name": "sync_skills", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nasync def sync_skills(dry_run: bool = False) -> str:\n    \"\"\"Re-read skills from disk into the database (the reverse of update_skill).\n\n    `SKILL.md` on disk is the source of truth a teammate edits and commits; the\n    DB row is what `skill()` serves and what the agent sees. Editing a file on\n    disk alone does NOT reach an agent until this runs — the startup sync only\n    compares mtimes once per boot. Requires approval (it writes the DB).\n\n    Args:\n        dry_run: Report what would change without writing.\n    \"\"\"\n    from datetime import datetime, timezone\n\n    from sqlalchemy import select\n\n    from core.skills.sync import (\n        DEFAULT_BUILTIN_SKILLS_ROOT, derive_source_type, fs_to_db_dict,\n    )\n    from db.database import AsyncSessionLocal\n    from models.skill import Skill\n    from services import user_roots\n\n    roots = [DEFAULT_BUILTIN_SKILLS_ROOT, user_roots.personal_skills_dir_for(user_roots.subject_user_id())]\n    files = []\n    for root in roots:\n        if root and Path(root).is_dir():\n            files.extend(sorted(Path(root).rglob(\"SKILL.md\")))\n    if not files:\n        return \"❌ 没有找到任何 SKILL.md（检查 backend/skills/builtin 与 personal/<uid>）\"\n\n    refusal = _approval_gate(\n        \"sync_skills\", {\"files\": len(files), \"dry_run\": dry_run},\n        f\"Sync {len(files)} SKILL.md file(s) into the database\",\n    )\n    if refusal:\n        return refusal\n\n    created, updated, unchanged, errors = [], [], [], []\n    async with AsyncSessionLocal() as session:\n        for md in files:\n            try:\n                data = fs_to_db_dict(md)\n                data[\"source_type\"] = derive_source_type(md)\n            except Exception as exc:  # noqa: BLE001\n                errors.append(f\"{md}: {exc}\")\n                continue\n            res = await session.execute(select(Skill).where(Skill.skill_id == data[\"skill_id\"]))\n            row = res.scalar_one_or_none()\n            if row is None:\n                if not dry_run:\n                    data[\"indexed_at\"] = datetime.now(timezone.utc)\n                    session.add(Skill(**data))\n                created.append(data[\"skill_id\"])\n            elif (data.get(\"file_modified_at\") and\n                  (not row.file_modified_at or data[\"file_modified_at\"] > row.file_modified_at)):\n                if not dry_run:\n                    for key, value in data.items():\n                        if hasattr(row, key):\n                            setattr(row, key, value)\n                    row.indexed_at = datetime.now(timezone.utc)\n                updated.append(data[\"skill_id\"])\n            else:\n                unchanged.append(data[\"skill_id\"])\n        if not dry_run:\n            await session.commit()\n\n    head = \"（dry-run，未写入）\" if dry_run else \"\"\n    return (\n        f\"## sync_skills{head}\\n\"\n        f\"扫描 {len(files)} 个 SKILL.md\\n\"\n        f\"新建 {len(created)}: {created}\\n\"\n        f\"更新 {len(updated)}: {updated}\\n\"\n        f\"未变 {len(unchanged)}\\n\"\n        + (f\"错误 {len(errors)}:\\n  \" + \"\\n  \".join(errors) if errors else \"\")\n    )\n\nAGENT_BUILDER_APPROVED = \"[rejected] this write needs an approval decision — the tool did not run\"\n\ndef _in_agent_run() -> bool:\n    \"\"\"True when this tool call is executing inside a LangGraph run.\n\n    `interrupt()` raises outside a checkpointed graph, and these tools are also\n    callable from the UI and from scripts — those paths must not try to pause.\n    \"\"\"\n    try:\n        from langchain_core.runnables.config import ensure_config\n\n        cfg = ensure_config() or {}\n        return bool((cfg.get(\"configurable\") or {}).get(\"thread_id\"))\n    except Exception:\n        return False\n\ndef _approval_gate(tool_name: str, payload: dict, description: str) -> str | None:\n    \"\"\"Pause for a human decision. Returns None to proceed, or a refusal string.\"\"\"\n    if not _in_agent_run():\n        return None\n\n    from langgraph.types import interrupt\n\n    decision = interrupt(\n        {\n            \"action_requests\": [\n                {\"name\": tool_name, \"args\": payload, \"description\": description}\n            ],\n            \"review_configs\": [\n                {\"action_name\": tool_name, \"allowed_decisions\": [\"approve\", \"reject\"]}\n            ],\n        }\n    )\n\n    if isinstance(decision, dict) and \"decisions\" in decision:\n        flat = decision.get(\"decisions\") or []\n        decision = flat[0] if flat else {}\n    if isinstance(decision, list):\n        decision = decision[0] if decision else {}\n    kind = decision.get(\"type\") if isinstance(decision, dict) else decision\n\n    if kind == \"approve\":\n        return None\n    if kind == \"reject\":\n        return f\"[rejected by human] {decision.get(''message'') or ''no reason given''}\"\n    return AGENT_BUILDER_APPROVED", "args_schema": {"dry_run": {"type": "boolean", "description": "", "default": false}}}', '{"type": "object", "properties": {"dry_run": {"type": "boolean", "description": "", "default": false}}, "required": []}', 'string', NULL, '{"category": "agents", "order": 31, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-11-01 07:54:46.827395+00:00', '2026-11-11 01:12:26.331928+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'sync_skills')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 217);

