SELECT 44, 'tavily_search', 'Tavily Search', 'Search the web using Tavily - an AI-optimized search engine.

Returns structured, summarized results perfect for AI consumption.
Requires TAVILY_API_KEY configured in Settings > API Keys.

Use this for more accurate, context-aware search results compared
to general web search. Especially good for research questions.

Args:
    query: The search query
    max_results: Maximum number of results to return (default: 5)

Returns:
    Search results as formatted text

Example:
    >>> await tavily_search("LangGraph v1.0 middleware system")
    >>> await tavily_search("Python async patterns", max_results=3)', 'python_function', 'custom', '{"function_name": "tavily_search", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\n# --- tavily guard ---\n\ntry:\n    from langchain_community.tools.tavily_search import TavilySearchResults\n    TAVILY_AVAILABLE = True\nexcept ImportError:\n    TAVILY_AVAILABLE = False\n\nasync def tavily_search(query: str, max_results: int = 5) -> str:\n    \"\"\"\n    Search the web using Tavily - an AI-optimized search engine.\n\n    Returns structured, summarized results perfect for AI consumption.\n    Requires TAVILY_API_KEY configured in Settings > API Keys.\n\n    Use this for more accurate, context-aware search results compared\n    to general web search. Especially good for research questions.\n\n    Args:\n        query: The search query\n        max_results: Maximum number of results to return (default: 5)\n\n    Returns:\n        Search results as formatted text\n\n    Example:\n        >>> await tavily_search(\"LangGraph v1.0 middleware system\")\n        >>> await tavily_search(\"Python async patterns\", max_results=3)\n    \"\"\"\n    try:\n        from config import get_api_key_from_db\n\n        api_key = get_api_key_from_db(\"tavily_api_key\")\n        if not api_key:\n            return (\n                \"Tavily API key not configured.\\n\\n\"\n                \"To use Tavily search:\\n\"\n                \"1. Go to Settings > API Keys\\n\"\n                \"2. Add your TAVILY_API_KEY\\n\"\n                \"3. Alternatively, use web_search (DuckDuckGo, free, no key required)\"\n            )\n\n        if not TAVILY_AVAILABLE:\n            # langchain_community is always present in LangConfig; the flag\n            # guards environments where it is missing. We call Tavily''s REST\n            # API directly below (no wrapper dependency), so this is only a\n            # soft guard.\n            pass\n\n        logger.info(f\"Tavily search: {query}\")\n\n        # Call the Tavily REST API directly — the langchain wrapper''s\n        # parameter names keep changing across versions (api_key vs\n        # tavily_api_key) and it wants an env var in some versions. Direct\n        # HTTP is stable and returns the same structured content.\n        import httpx as _httpx\n\n        async with _httpx.AsyncClient(timeout=15) as client:\n            r = await client.post(\n                \"https://api.tavily.com/search\",\n                json={\n                    \"api_key\": api_key,\n                    \"query\": query,\n                    \"max_results\": max_results,\n                    \"include_answer\": False,\n                },\n            )\n            r.raise_for_status()\n            data = r.json()\n\n        results = data.get(\"results\") or []\n        if not results:\n            return f\"No results found for: {query}\"\n\n        result_text = f\"Search results for ''{query}'' (via Tavily):\\n\\n\"\n        for i, r_item in enumerate(results, 1):\n            content = r_item.get(\"content\", \"\")\n            url = r_item.get(\"url\", \"\")\n            if url:\n                result_text += f\"{i}. {content}\\n   Source: {url}\\n\\n\"\n            else:\n                result_text += f\"{i}. {content}\\n\\n\"\n\n        logger.info(f\"Tavily search returned {len(results)} results for: {query}\")\n        return result_text\n\n    except Exception as e:\n        logger.error(f\"Tavily search failed: {e}\")\n        return f\"Tavily search error: {str(e)}\"", "args_schema": {"query": {"type": "string", "description": ""}, "max_results": {"type": "integer", "description": "", "default": 5}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": ""}, "max_results": {"type": "integer", "description": "", "default": 5}}, "required": ["query"]}', 'string', NULL, '{"category": "web", "order": 1, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {"requires_api_key": "TAVILY_API_KEY"}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'web', TRUE, 'TAVILY_API_KEY', '["builtin", "web"]', '2026-08-01 14:44:18.034560+00:00', '2026-08-22 15:18:58.895640+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'tavily_search')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 44);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 216, 'test_agent', 'Test Agent (probe run)', 'Run one or more probes against an agent in ONE session and report what happened.

The probe must target the rubric — "hi" proves nothing. Runs through the same
HTTP chat path a user uses, so a pass here means the agent works where the user
will use it.

Use `probes` when a criterion needs several turns (a state machine that must
walk stage 1 → 2 → 3, or "the user says the earlier answer was wrong" which
only means something after two turns). Each message is sent in order in the
same session, and each turn gets its own tool sequence.

Args:
    agent_id: Agent to test
    probe: One message to send (write it against your rubric criteria)
    probes: Several messages, sent in order in the same session. Use this
            instead of `probe` for multi-turn criteria.
    max_seconds: Wall-clock cap for the whole run (all turns together)

Returns: per-turn tool sequence, elapsed time and answer text, then a total.', 'python_function', 'custom', '{"function_name": "test_agent", "code": "# --- imports ---\n\nimport asyncio\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport httpx\n\nimport os\n\nasync def test_agent(agent_id: int, probe: str = \"\", probes: list[str] | None = None,\n                    max_seconds: int = 120) -> str:\n    \"\"\"Run one or more probes against an agent in ONE session and report what happened.\n\n    The probe must target the rubric — \"hi\" proves nothing. Runs through the same\n    HTTP chat path a user uses, so a pass here means the agent works where the user\n    will use it.\n\n    Use `probes` when a criterion needs several turns (a state machine that must\n    walk stage 1 → 2 → 3, or \"the user says the earlier answer was wrong\" which\n    only means something after two turns). Each message is sent in order in the\n    same session, and each turn gets its own tool sequence.\n\n    Args:\n        agent_id: Agent to test\n        probe: One message to send (write it against your rubric criteria)\n        probes: Several messages, sent in order in the same session. Use this\n                instead of `probe` for multi-turn criteria.\n        max_seconds: Wall-clock cap for the whole run (all turns together)\n\n    Returns: per-turn tool sequence, elapsed time and answer text, then a total.\n    \"\"\"\n    import asyncio\n    import os\n    import time\n\n    import httpx\n\n    steps = list(probes or [])\n    if not steps and probe:\n        steps = [probe]\n    steps = [str(m).strip() for m in steps if str(m).strip()]\n    if not steps:\n        return \"❌ test_agent needs `probe` or `probes` — an empty probe proves nothing\"\n\n    base = os.getenv(\"LANGCONFIG_API_BASE\", \"http://127.0.0.1:8765\").rstrip(\"/\")\n    started = time.time()\n    sid = \"\"\n    try:\n        # Async on purpose. As a sync tool this ran in a worker thread while the\n        # caller''s event loop was busy with the outer run; the probe''s own\n        # streaming request then waited for that loop and died of a read timeout\n        # (measured: three attempts, 40/90/180s, all ReadTimeout while the same\n        # probe run from outside finished in 11.5s).\n        async with httpx.AsyncClient(timeout=httpx.Timeout(60.0, read=max_seconds + 30)) as client:\n            started_session = await client.post(f\"{base}/api/chat/start\", json={\"agent_id\": agent_id})\n            if started_session.status_code != 200:\n                return (f\"❌ 无法为 agent {agent_id} 开会话: HTTP {started_session.status_code} \"\n                        f\"{started_session.text[:200]}\")\n            sid = started_session.json()[\"session_id\"]\n\n            turns: list[dict] = []\n            timed_out = False\n            for index, message in enumerate(steps, 1):\n                tools: list[str] = []\n                answer_parts: list[str] = []\n                turn_started = time.time()\n\n                async def _one_turn() -> None:\n                    async with client.stream(\n                        \"POST\", f\"{base}/api/chat/message/stream\",\n                        json={\"session_id\": sid, \"message\": message},\n                    ) as resp:\n                        async for raw in resp.aiter_lines():\n                            if time.time() - started > max_seconds:\n                                return\n                            if not raw or not raw.startswith(\"data: \"):\n                                continue\n                            try:\n                                import json as _json\n                                event = _json.loads(raw[6:])\n                            except Exception:\n                                continue\n                            if event.get(\"type\") == \"tool_start\":\n                                tools.append(event.get(\"tool_name\") or \"?\")\n                            elif event.get(\"type\") == \"chunk\":\n                                answer_parts.append(event.get(\"content\") or \"\")\n                            elif event.get(\"type\") in (\"complete\", \"stopped\", \"interrupt\"):\n                                return\n\n                turn_note = \"\"\n                for attempt in (1, 2):\n                    try:\n                        # A turn that never closes its stream used to hang the\n                        # whole call until the client read-timeout fired (354s on\n                        # a handoff agent). Cap each turn; retry once, because the\n                        # usual cause is sending the next message while the server\n                        # is still finishing the previous run.\n                        await asyncio.wait_for(_one_turn(), timeout=min(max_seconds, 150))\n                        break\n                    except Exception as _exc:  # noqa: BLE001\n                        turn_note = type(_exc).__name__\n                        if attempt == 2:\n                            break\n                        await asyncio.sleep(2.0)\n                if False:  # placeholder kept out of the async-for shape\n                        if not raw or not raw.startswith(\"data: \"):\n                            continue\n                turns.append({\n                    \"n\": index, \"message\": message, \"tools\": tools,\n                    \"answer\": \"\".join(answer_parts).strip(),\n                    \"elapsed\": round(time.time() - turn_started, 1),\n                    \"note\": turn_note,\n                })\n                await asyncio.sleep(1.5)  # let the server close the previous run\n                if timed_out or turn_note:\n                    break\n    except Exception as e:\n        return f\"❌ test_agent failed: {type(e).__name__}: {e} (session={sid})\"\n\n    elapsed = round(time.time() - started, 1)\n    verdict = \"超时（未跑完）\" if timed_out else \"跑完\"\n    lines = [\n        f\"## test_agent(agent_id={agent_id}) — {verdict} in {elapsed}s \"\n        f\"({len(turns)}/{len(steps)} 轮)\",\n        f\"session: {sid}\",\n    ]\n    for turn in turns:\n        lines += [\n            \"\",\n            f\"### T{turn[''n'']} — {turn[''elapsed'']}s, {len(turn[''tools''])} 次工具\",\n            f\"U: {turn[''message''][:160]}\",\n            f\"tools: {turn[''tools'']}\",\n            f\"A ({len(turn[''answer''])} 字): {turn[''answer''][:700]}\"\n            + (f\"\\n⚠️ 本轮中断: {turn[''note'']}\" if turn.get(\"note\") else \"\"),\n        ]\n    lines += [\"\", \"---\", \"逐条对 rubric 判 pass/fail 时引用上面这段，不要凭印象。\"]\n    return \"\\n\".join(lines)", "args_schema": {"agent_id": {"type": "integer", "description": ""}, "probe": {"type": "string", "description": "", "default": ""}, "probes": {"type": "array", "description": "", "default": null}, "max_seconds": {"type": "integer", "description": "", "default": 120}}}', '{"type": "object", "properties": {"agent_id": {"type": "integer", "description": ""}, "probe": {"type": "string", "description": "", "default": ""}, "probes": {"type": "array", "description": "", "default": null}, "max_seconds": {"type": "integer", "description": "", "default": 120}}, "required": ["agent_id"]}', 'string', NULL, '{"category": "agents", "order": 30, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-11-01 03:15:07.803681+00:00', '2026-11-11 01:12:26.331928+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'test_agent')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 216);

INSERT INTO custom_tools (id, tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 215, 'update_agent', 'Update Agent Config', 'Patch an existing agent by id. Only the fields you pass change. Requires approval.

Prefer ``middleware_patch`` over ``middleware`` when changing one step of a
handoff or one entry of a HITL policy: it merges, so the rest of the
middleware stays exactly as it is.

Read it first with pg_get_agent and change one thing at a time, so a failing
test can be attributed to a specific edit.', 'python_function', 'custom', '{"function_name": "update_agent", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nAGENT_BUILDER_APPROVED = \"[rejected] this write needs an approval decision — the tool did not run\"\n\ndef _in_agent_run() -> bool:\n    \"\"\"True when this tool call is executing inside a LangGraph run.\n\n    `interrupt()` raises outside a checkpointed graph, and these tools are also\n    callable from the UI and from scripts — those paths must not try to pause.\n    \"\"\"\n    try:\n        from langchain_core.runnables.config import ensure_config\n\n        cfg = ensure_config() or {}\n        return bool((cfg.get(\"configurable\") or {}).get(\"thread_id\"))\n    except Exception:\n        return False\n\ndef _approval_gate(tool_name: str, payload: dict, description: str) -> str | None:\n    \"\"\"Pause for a human decision. Returns None to proceed, or a refusal string.\"\"\"\n    if not _in_agent_run():\n        return None\n\n    from langgraph.types import interrupt\n\n    decision = interrupt(\n        {\n            \"action_requests\": [\n                {\"name\": tool_name, \"args\": payload, \"description\": description}\n            ],\n            \"review_configs\": [\n                {\"action_name\": tool_name, \"allowed_decisions\": [\"approve\", \"reject\"]}\n            ],\n        }\n    )\n\n    if isinstance(decision, dict) and \"decisions\" in decision:\n        flat = decision.get(\"decisions\") or []\n        decision = flat[0] if flat else {}\n    if isinstance(decision, list):\n        decision = decision[0] if decision else {}\n    kind = decision.get(\"type\") if isinstance(decision, dict) else decision\n\n    if kind == \"approve\":\n        return None\n    if kind == \"reject\":\n        return f\"[rejected by human] {decision.get(''message'') or ''no reason given''}\"\n    return AGENT_BUILDER_APPROVED\n\ndef _agent_config_payload(kind: str, cfg: dict) -> dict:\n    \"\"\"The DeepAgentConfig for a new agent, normal or deep.\n\n    `kind=\"normal\"` flips `use_deepagents` off: the platform then assembles the\n    prompt (guardrails + tool enforcement) instead of taking ours verbatim, and\n    the harness file tools no longer arrive for free — a normal agent that needs\n    to write files must list `write_file` itself.\n    \"\"\"\n    from models.deep_agent import (\n        DeepAgentConfig,\n        MiddlewareConfig,\n        SubAgentConfig,\n        create_default_backend_config,\n        create_default_guardrails_config,\n        create_default_middleware_config,\n    )\n\n    subagents = []\n    for sub in cfg.get(\"subagents\") or []:\n        if not isinstance(sub, dict) or not sub.get(\"name\"):\n            continue\n        subagents.append(\n            SubAgentConfig(\n                name=sub[\"name\"],\n                description=sub.get(\"description\") or \"\",\n                system_prompt=sub.get(\"system_prompt\") or \"\",\n                tools=list(sub.get(\"tools\") or []),\n                middleware=list(sub.get(\"middleware\") or []),\n                interrupt_on=sub.get(\"interrupt_on\") or {},\n            )\n        )\n\n    middleware = []\n    for mw in cfg.get(\"middleware\") or []:\n        if isinstance(mw, dict) and mw.get(\"type\"):\n            middleware.append(\n                MiddlewareConfig(\n                    type=mw[\"type\"],\n                    enabled=mw.get(\"enabled\", True),\n                    config=mw.get(\"config\") or {},\n                )\n            )\n    # None = \"I did not say\" → platform defaults. [] = \"I said none\" → none.\n    # Collapsing the two made a template that says \"no middleware\" silently get\n    # todo_list + filesystem + subagent (found by Agent Builder, 2026-11-01).\n    if cfg.get(\"middleware\") is None:\n        middleware = create_default_middleware_config()\n\n    return DeepAgentConfig(\n        model=cfg.get(\"model\") or None,\n        temperature=cfg.get(\"temperature\") if cfg.get(\"temperature\") is not None else 0.3,\n        system_prompt=(cfg.get(\"system_prompt\") or \"\").strip(),\n        native_tools=list(cfg.get(\"native_tools\") or []),\n        cli_tools=[],\n        custom_tools=[],\n        skills=cfg.get(\"skills\"),\n        tools=[],\n        use_deepagents=(kind != \"normal\"),\n        middleware=middleware,\n        subagents=subagents,\n        mcp_servers=cfg.get(\"mcp_servers\") or None,\n        tool_params=cfg.get(\"tool_params\") or None,\n        backend=create_default_backend_config(),\n        guardrails=create_default_guardrails_config(),\n    )\n\ndef _apply_config(agent, cfg_obj) -> list[str]:\n    \"\"\"Write a DeepAgentConfig onto the template row; returns the fields saved.\"\"\"\n    from sqlalchemy.orm.attributes import flag_modified\n\n    dumped = cfg_obj.dict()\n    agent.config = dumped\n    agent.middleware_config = [m.dict() for m in cfg_obj.middleware]\n    agent.subagents_config = [s.dict() for s in cfg_obj.subagents]\n    agent.backend_config = cfg_obj.backend.dict()\n    agent.guardrails_config = cfg_obj.guardrails.dict()\n    flag_modified(agent, \"config\")\n    saved = [\"model\", \"temperature\", \"system_prompt\", \"native_tools\", \"middleware\"]\n    if cfg_obj.subagents:\n        saved.append(\"subagents\")\n    if cfg_obj.mcp_servers:\n        saved.append(\"mcp_servers\")\n    if cfg_obj.tool_params:\n        saved.append(\"tool_params\")\n    if cfg_obj.skills:\n        saved.append(\"skills\")\n    return saved\n\ndef _as_list(value, sep: str = \",\") -> list:\n    \"\"\"Accept a real list, a JSON array string, or CSV — models send all three.\n\n    The tool schema says \"array\" now, but a model that has seen older catalog\n    text still emits \"web_search,tavily_search\". Coercing here keeps the build\n    correct instead of silently creating an agent whose tools are the\n    characters of that string (which happened once).\n    \"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [str(v).strip() for v in value if str(v).strip()]\n    if isinstance(value, str):\n        text = value.strip()\n        if not text:\n            return []\n        if text.startswith(\"[\"):\n            try:\n                import json as _json\n\n                parsed = _json.loads(text)\n                if isinstance(parsed, list):\n                    return [str(v).strip() for v in parsed if str(v).strip()]\n            except Exception:\n                pass\n        return [part.strip() for part in text.split(sep) if part.strip()]\n    return [str(value)]\n\ndef _as_dict(value):\n    \"\"\"Accept a dict or a JSON object string.\"\"\"\n    if value is None:\n        return None\n    if isinstance(value, dict):\n        return value\n    if isinstance(value, str) and value.strip().startswith(\"{\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return parsed if isinstance(parsed, dict) else None\n        except Exception:\n            return None\n    return None\n\ndef _as_list_of_dicts(value) -> list:\n    \"\"\"Accept a list, or a JSON array string (subagents/middleware).\"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [v for v in value if isinstance(v, dict)]\n    if isinstance(value, str) and value.strip().startswith(\"[\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return [v for v in parsed if isinstance(v, dict)] if isinstance(parsed, list) else []\n        except Exception:\n            return []\n    return []\n\ndef _merge_middleware_patch(middleware: list, patch) -> list:\n    \"\"\"Merge a per-type middleware patch into an existing middleware list.\n\n    `update_agent(middleware=...)` replaces the whole field, so changing one\n    handoff step means reproducing every other step verbatim — a caller that has\n    only a stale copy either clobbers the agent or (correctly) refuses to act.\n    A patch says just what changes:\n\n        {\"handoff\": {\"steps\": {\"warranty_collector\": {\"system_prompt\": \"…\"}}}}\n        {\"hitl\": {\"interrupt_on\": {\"write_file\": True}}}\n\n    Steps merge one level deep, so touching one step leaves the others alone.\n    A type that is not present yet is appended.\n    \"\"\"\n    patch = _as_dict(patch) or {}\n    merged = [dict(m) if isinstance(m, dict) else m for m in (middleware or [])]\n    for mtype, spec in patch.items():\n        if not isinstance(spec, dict):\n            continue\n        target = None\n        for m in merged:\n            if isinstance(m, dict) and m.get(\"type\") == mtype:\n                target = m\n                break\n        if target is None:\n            merged.append({\"type\": mtype, \"enabled\": True, \"config\": dict(spec)})\n            continue\n        conf = dict(target.get(\"config\") or {})\n        for key, value in spec.items():\n            if key == \"steps\" and isinstance(value, dict):\n                steps = dict(conf.get(\"steps\") or {})\n                for step_name, step_spec in value.items():\n                    if not isinstance(step_spec, dict):\n                        continue\n                    step = dict(steps.get(step_name) or {})\n                    step.update(step_spec)\n                    steps[step_name] = step\n                conf[\"steps\"] = steps\n            else:\n                conf[key] = value\n        target[\"config\"] = conf\n        target.setdefault(\"enabled\", True)\n    return merged\n\ndef update_agent(agent_id: int,\n                 system_prompt: str | None = None,\n                 native_tools: list[str] | None = None,\n                 skills: list[str] | None = None,\n                 subagents: list[dict] | None = None,\n                 middleware: list[dict] | None = None,\n                 mcp_servers: dict | None = None,\n                 middleware_patch: dict | None = None,\n                 model: str | None = None,\n                 temperature: float | None = None,\n                 agent_docs: dict | None = None) -> str:\n    \"\"\"Patch an existing agent by id. Only the fields you pass change. Requires approval.\n\n    Prefer ``middleware_patch`` over ``middleware`` when changing one step of a\n    handoff or one entry of a HITL policy: it merges, so the rest of the\n    middleware stays exactly as it is.\n\n    Read it first with pg_get_agent and change one thing at a time, so a failing\n    test can be attributed to a specific edit.\n    \"\"\"\n    from db.database import SessionLocal\n    from models.deep_agent import DeepAgentTemplate\n\n    native_tools = _as_list(native_tools) if native_tools is not None else None\n    middleware_patch = _as_dict(middleware_patch) if middleware_patch is not None else None\n    skills = _as_list(skills) if skills is not None else None\n    subagents = _as_list_of_dicts(subagents) if subagents is not None else None\n    middleware = _as_list_of_dicts(middleware) if middleware is not None else None\n    mcp_servers = _as_dict(mcp_servers) if mcp_servers is not None else None\n    agent_docs = _as_dict(agent_docs) if agent_docs is not None else None\n\n    refusal = _approval_gate(\n        \"update_agent\",\n        {\"agent_id\": agent_id, \"fields\": [k for k, v in {\n            \"system_prompt\": system_prompt, \"native_tools\": native_tools, \"skills\": skills,\n            \"subagents\": subagents, \"middleware\": middleware, \"mcp_servers\": mcp_servers,\n            \"middleware_patch\": middleware_patch,\n            \"model\": model, \"temperature\": temperature, \"agent_docs\": agent_docs,\n        }.items() if v is not None]},\n        f\"Update agent {agent_id}\",\n    )\n    if refusal:\n        return refusal\n\n    db = SessionLocal()\n    try:\n        agent = db.query(DeepAgentTemplate).filter(DeepAgentTemplate.id == agent_id).first()\n        if not agent:\n            return f\"❌ Agent with id={agent_id} not found.\"\n        if getattr(agent, \"is_public\", False):\n            return (\"❌ 拒绝修改 public agent。public 的是共享基线，改它会影响所有人；\"\n                    \"请先复制成私有 agent（create_agent）再改。\")\n\n        cur = dict(agent.config or {})\n        before = {k: cur.get(k) for k in (\"model\", \"temperature\", \"native_tools\")}\n        merged = {\n            \"system_prompt\": system_prompt if system_prompt is not None else cur.get(\"system_prompt\"),\n            \"native_tools\": native_tools if native_tools is not None else cur.get(\"native_tools\"),\n            \"skills\": skills if skills is not None else cur.get(\"skills\"),\n            \"model\": model if model is not None else cur.get(\"model\"),\n            \"temperature\": temperature if temperature is not None else cur.get(\"temperature\"),\n            \"subagents\": subagents if subagents is not None else cur.get(\"subagents\"),\n            \"middleware\": (\n            _merge_middleware_patch(cur.get(\"middleware\") or [], middleware_patch)\n            if middleware_patch is not None\n            else (middleware if middleware is not None else cur.get(\"middleware\"))\n        ),\n            \"mcp_servers\": mcp_servers if mcp_servers is not None else cur.get(\"mcp_servers\"),\n            \"tool_params\": cur.get(\"tool_params\"),\n        }\n        kind = \"normal\" if cur.get(\"use_deepagents\") is False else \"deep\"\n        cfg_obj = _agent_config_payload(kind, merged)\n        saved = _apply_config(agent, cfg_obj)\n        if agent_docs is not None:\n            agent.agent_docs = agent_docs\n            saved.append(\"agent_docs\")\n        db.commit()\n        db.refresh(agent)\n\n        after = {k: (agent.config or {}).get(k) for k in (\"model\", \"temperature\", \"native_tools\")}\n        return (\n            f\"✅ agent {agent_id} updated — 保存字段: {'', ''.join(saved)}\\n\"\n            f\"改前: {before}\\n改后: {after}\\n\"\n            f\"下一步: test_agent(agent_id={agent_id}, probe=...) 复测同一批 rubric 条目。\"\n        )\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to update agent: {e}\"\n    finally:\n        db.close()", "args_schema": {"agent_id": {"type": "integer", "description": ""}, "system_prompt": {"type": "string", "description": "", "default": null}, "native_tools": {"type": "array", "description": "", "default": null}, "skills": {"type": "array", "description": "", "default": null}, "subagents": {"type": "array", "description": "", "default": null}, "middleware": {"type": "array", "description": "", "default": null}, "mcp_servers": {"type": "object", "description": "", "default": null}, "middleware_patch": {"type": "object", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": null}, "agent_docs": {"type": "object", "description": "", "default": null}}}', '{"type": "object", "properties": {"agent_id": {"type": "integer", "description": ""}, "system_prompt": {"type": "string", "description": "", "default": null}, "native_tools": {"type": "array", "description": "", "default": null}, "skills": {"type": "array", "description": "", "default": null}, "subagents": {"type": "array", "description": "", "default": null}, "middleware": {"type": "array", "description": "", "default": null}, "mcp_servers": {"type": "object", "description": "", "default": null}, "middleware_patch": {"type": "object", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": null}, "agent_docs": {"type": "object", "description": "", "default": null}}, "required": ["agent_id"]}', 'string', NULL, '{"category": "agents", "order": 29, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-11-01 03:15:07.803678+00:00', '2026-11-11 01:12:26.331927+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'update_agent')
  AND NOT EXISTS (SELECT 1 FROM custom_tools WHERE id = 215);

