SELECT 82, 'update_skill', 'Update Skill', 'Update an existing skill in the database. Only provided fields are updated.

Args:
    skill_id: The kebab-case ID of the skill to update
    name: New human-readable name
    description: New description
    instructions: New instructions
    tags: New list of tags
    triggers: New list of triggers', 'python_function', 'custom', '{"function_name": "update_skill", "code": "# --- imports ---\n\nimport json\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport re as _re\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _skill_support_files(base: Path, limit: int = 40) -> list:\n    \"\"\"Files next to SKILL.md, as skill-relative paths (sorted, capped).\n\n    A skill that ships templates or reference tables is useless if the model\n    cannot see that they exist: the instructions are in the DB, the files are on\n    disk. Seen 2026-11-01 — Agent Builder rebuilt a template from memory because\n    `templates/` was invisible.\n    \"\"\"\n    if base is None or not base.is_dir():\n        return []\n    out = []\n    for path in sorted(base.rglob(\"*\")):\n        if not path.is_file() or path.name == \"SKILL.md\":\n            continue\n        out.append(str(path.relative_to(base)))\n        if len(out) >= limit:\n            break\n    return out\n\nasync def skill(skill_id: str, file: str = \"\", lang: str = \"\") -> str:\n    \"\"\"Fetch a skill''s full instructions by its id — or one of its support files.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Skills may ship supporting files next to SKILL.md (templates, fact tables,\n    scripts). Those are NOT loaded with the instructions; list them with this\n    tool first (it prints `Support files:`), then ask for one by path.\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n        file: Optional path inside the skill directory, e.g.\n              \"templates/T2-supervisor-experts.md\". Leave empty for the\n              instructions. Must stay inside the skill.\n        lang: Which language to serve. Empty (the default) serves `SKILL.md` — the working text, which is\n              Chinese for every skill that has been translated. `lang=\"en\"` serves the archived English\n              original from `backend/skills/en-originals/<id>/SKILL.md`, which nothing else reads: it is a\n              backup and a source for checking a translation, and it enters a context only when asked for\n              by name.\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            registry.record_usage(skill_id, \"explicit\", \"failed\", source=\"skill tool: not found\")\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        base = Path(found.source_path) if getattr(found, \"source_path\", None) else None\n\n        if file:\n            if base is None or not base.is_dir():\n                return f\"Error: skill ''{skill_id}'' has no source directory on disk.\"\n            target = (base / file).resolve()\n            try:\n                target.relative_to(base.resolve())\n            except ValueError:\n                return f\"Error: ''{file}'' escapes skill ''{skill_id}''.\"\n            if not target.is_file():\n                listing = _skill_support_files(base)\n                return (f\"Error: ''{file}'' not found in skill ''{skill_id}''. \"\n                        f\"Support files: {'', ''.join(listing) or ''none''}\")\n            text = target.read_text(encoding=\"utf-8\", errors=\"replace\")\n            return f\"# Skill file: {skill_id}/{file}\\n\\n{text}\"\n\n        # The working text is Chinese: `SKILL.md` is what an agent reads, and the English original lives\n        # outside the skill library (`backend/skills/en-originals/<id>/`) as a backup. Nothing loads it\n        # unless the caller asks for it explicitly by language — which is why the default below is the\n        # canonical file and not a sibling.\n        body_text, body_lang = found.instructions, \"zh\"\n        if lang and lang.split(\"-\")[0].lower() == \"en\":\n            # base is .../skills/builtin/<id>; the archive sits beside the library root\n            archived = (Path(base).parents[1] / \"en-originals\" / found.skill_id / \"SKILL.md\"\n                        if base is not None else None)\n            if archived is not None and archived.is_file():\n                raw = archived.read_text(encoding=\"utf-8\", errors=\"replace\")\n                if raw.startswith(\"---\"):\n                    end = raw.find(\"\\n---\", 3)\n                    if end != -1:\n                        raw = raw[end + 4:].lstrip(\"\\n\")\n                body_text, body_lang = raw, \"en\"\n        parts = [\n            f\"# Skill: {found.name}\" + (f\"  (instructions: {body_lang})\" if body_lang != \"zh\" else \"\"),\n            f\"**Description:** {found.description}\",\n            \"\",\n            body_text,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        support = _skill_support_files(base) if base else []\n        if support:\n            parts += [\n                \"\",\n                \"**Support files** (not loaded above — fetch one with \"\n                f\"skill(\\\"{found.skill_id}\\\", file=\\\"<path>\\\")):\",\n                *[f\"- {f}\" for f in support],\n            ]\n        # Count the use. Until this existed, `usage_count`/`avg_success_rate` were read by the UI and written by\n        # nobody: the library showed \"0 uses\" for skills that had been served hundreds of times.\n        registry.record_usage(found.skill_id, \"explicit\", \"success\", source=\"skill tool\")\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"\n\ndef _coerce_str_list(value) -> list[str] | None:\n    \"\"\"Normalise a model-supplied \"list\" into a real list of strings.\n\n    Why this exists: ``create_skill``/``update_skill`` declare ``tags: list[str]``\n    and ``triggers: list[str]``, but Python does not enforce annotations at\n    runtime. Models routinely pass arrays as JSON text (``''[\"a\", \"b\"]''``) or as a\n    comma-separated string (``\"a, b\"``). Stored verbatim in the JSON columns,\n    that string makes ``SkillResponse`` fail validation — which surfaced as a\n    500 on ``GET /api/skills/{id}`` while ``GET /api/skills`` hid it behind a\n    placeholder row.\n\n    Coerce at the boundary rather than trusting the type hint: an LLM is the\n    caller here, so the input is untrusted text in practice.\n    \"\"\"\n    if value is None:\n        return None\n    if isinstance(value, (list, tuple, set)):\n        items = list(value)\n    elif isinstance(value, str):\n        text = value.strip()\n        if not text:\n            return []\n        parsed = None\n        try:\n            parsed = json.loads(text)\n        except (ValueError, TypeError):\n            parsed = None\n        if isinstance(parsed, list):\n            items = parsed\n        elif isinstance(parsed, dict) or parsed is None:\n            # Not JSON, or a JSON object: fall back to splitting on commas.\n            items = text.split(\",\")\n        else:\n            items = [parsed]\n    else:\n        items = [value]\n\n    out: list[str] = []\n    for item in items:\n        if item is None:\n            continue\n        text = str(item).strip()\n        if text:\n            out.append(text)\n    return out\n\ndef update_skill(skill_id: str, name: str | None = None,\n                 description: str | None = None,\n                 instructions: str | None = None,\n                 tags: list[str] | None = None,\n                 triggers: list[str] | None = None) -> str:\n    \"\"\"Update an existing skill in the database. Only provided fields are updated.\n\n    Args:\n        skill_id: The kebab-case ID of the skill to update\n        name: New human-readable name\n        description: New description\n        instructions: New instructions\n        tags: New list of tags\n        triggers: New list of triggers\n    \"\"\"\n    from db.database import SessionLocal\n    from models.skill import Skill\n    import datetime\n    import re as _re\n\n    # Sanitize the identifier — only kebab-case ids are valid; anything else is\n    # rejected before touching the DB (defense-in-depth against odd inputs).\n    if not _re.fullmatch(r\"[a-z0-9][a-z0-9-]*\", skill_id or \"\"):\n        return f\"❌ Invalid skill_id ''{skill_id}'': use kebab-case (letters, digits, hyphens).\"\n\n    db = SessionLocal()\n    try:\n        skill = db.query(Skill).filter(Skill.skill_id == skill_id).first()\n        if not skill:\n            return f\"❌ Skill ''{skill_id}'' not found. Use create_skill first.\"\n\n        if name is not None:\n            skill.name = name.strip()\n        if description is not None:\n            skill.description = description.strip()\n        if instructions is not None:\n            skill.instructions = instructions.strip()\n        if tags is not None:\n            skill.tags = _coerce_str_list(tags)\n        if triggers is not None:\n            skill.triggers = _coerce_str_list(triggers)\n        skill.updated_at = datetime.datetime.now(datetime.timezone.utc)\n        db.commit()\n        # Mirror to SKILL.md: the file is what a teammate receives.\n        try:\n            from core.skills.sync import db_row_to_fs\n\n            row = db.query(Skill).filter(Skill.skill_id == skill_id).first()\n            if row is not None:\n                db_row_to_fs(row)\n        except Exception as _e:  # noqa: BLE001\n            logger.warning(f\"update_skill: SKILL.md mirror skipped: {_e}\")\n        return f\"✅ Skill ''{skill_id}'' updated successfully!\"\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to update skill: {e}\"\n    finally:\n        db.close()", "args_schema": {"skill_id": {"type": "string", "description": ""}, "name": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "instructions": {"type": "string", "description": "", "default": null}, "tags": {"type": "array", "description": "", "default": null}, "triggers": {"type": "array", "description": "", "default": null}}}', '{"type": "object", "properties": {"skill_id": {"type": "string", "description": ""}, "name": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "instructions": {"type": "string", "description": "", "default": null}, "tags": {"type": "array", "description": "", "default": null}, "triggers": {"type": "array", "description": "", "default": null}}, "required": ["skill_id"]}', 'string', NULL, '{"category": "skills", "order": 26, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-01 14:44:18.034635+00:00', '2026-11-11 01:12:26.325789+00:00'
